def test_assume_il_cannot_turn_a_navigation_menu_into_a_board(monkeypatch):
    """`SCRAPE_ASSUME_IL=1` makes every location-less card on an Israel-token page an Israel
    role. The activation gate (`looks_like_a_job_listing_page`) is what catches a nav menu
    with an Israeli footer; the parse itself must at least refuse the obvious shapes — a menu
    of one-word labels, a blog index of sentences, an offices page."""
    import scrape_universal as N
    monkeypatch.setenv("SCRAPE_ASSUME_IL", "1")
    footer = "<footer>Head office: HaMenofim 8, Herzliya, Israel</footer>"
    menu = "".join(f"<h3>{t}</h3>" for t in ("About", "Products", "Solutions", "Press Releases",
                                             "Domain Operations", "Contact", "Blog", "Partners"))
    blog = "".join(f'<h2 class="post-title">{t}</h2>' for t in (
        "Why we moved our data platform to Iceberg", "How our analysts think about churn",
        "What we learned shipping the product analytics suite", "Our engineering values"))
    offices = "".join(f"<h3>{t}</h3>" for t in ("Tel Aviv", "Haifa", "Herzliya", "New York"))
    for page in (menu, blog, offices):
        jobs, _ = N._extract("Co", "https://co.example/solutions/research", _rendered(page_html=page + footer),
                             fetch=_no_fetch)
        assert jobs == [], page[:60]
    assert N._page_is_il("https://co.example/careers", "<html>nothing local here</html>") is False


# ---- the refresh -----------------------------------------------------------------------------
_TODAY = _dtm.date.today().isoformat()


_mp = pytest.MonkeyPatch


def _il_job(name, n=1):
    return {"company": name, "title": f"Senior Data Analyst {n}", "location": "Tel Aviv",
            "country_code": "", "url": f"https://{name.lower()}.example/jobs/{n}", "posted_date": "",
            "ats_platform": "scrape", "job_id": str(n), "description": ""}


def _refresh_sandbox(tmp_path, monkeypatch, rows, old_cache=None, rot=None, outcomes=None):
    """A registry, cache, rot file and stage file under tmp_path; `outcomes` maps a company
    name to ("ok"|"empty"|"error", detail) and drives a fake `scrape_result`."""
    import refresh_scrape_cache as R
    from pipeline import stages
    tmp_path.mkdir(parents=True, exist_ok=True)
    paths = _NS(csv=tmp_path / "companies.csv", cache=tmp_path / "cache.json",
                rot=tmp_path / "rot.json", stages=tmp_path / "stages.json")
    with open(paths.csv, "w", newline="", encoding="utf-8") as f:
        w = _csv.writer(f)
        w.writerow(["company_name", "ats_platform", "token", "api_url", "active", "notes"])
        for r in rows:
            w.writerow(r if len(r) == 6 else
                       [r[0], "scrape", "", f"https://{r[0].lower()}.example/careers", "true",
                        r[1] if len(r) > 1 else ""])
    paths.cache.write_text(_json.dumps(old_cache or {}), encoding="utf-8")
    paths.rot.write_text(_json.dumps(rot or {}), encoding="utf-8")
    monkeypatch.setattr(R, "CSV_PATH", str(paths.csv))
    monkeypatch.setattr(R, "CACHE_PATH", str(paths.cache))
    monkeypatch.setattr(R, "ROT_PATH", str(paths.rot))
    monkeypatch.setattr(stages, "PATH", str(paths.stages))
    # the day-rotation is pure and pinned by its own test; here every scenario reads the
    # registry in order (BACKLOG 158: the shrink test was red on the dates the rotation moved
    # its emptied rows past the budget cut)
    monkeypatch.setattr(R, "_rotate", lambda rows, day: rows)
    monkeypatch.delenv("SCRAPE_REFRESH_TIME_BUDGET_MIN", raising=False)
    monkeypatch.delenv("SCRAPE_WORKERS", raising=False)
    outcomes = outcomes or {}

    def fake(name, url, timeout_ms=45000, **kw):
        kind, detail = outcomes.get(name, ("ok", 1))
        if kind == "error":
            return _NS(jobs=[], status="error", error=detail, http_status=403, strategy="",
                       elapsed_s=0.1, rescued=False)
        if kind == "empty":
            return _NS(jobs=[], status="empty", error="", http_status=200, strategy="",
                       elapsed_s=0.1, rescued=False)
        if kind == "weak":
            # a reading that named roles and knew no posting's own address (2026-08-26)
            return _NS(jobs=[_il_job(name, i + 1) for i in range(detail)], status="ok",
                       error="", http_status=200, strategy="cards", elapsed_s=0.1,
                       rescued=False, weak_read=True)
        return _NS(jobs=[_il_job(name, i + 1) for i in range(detail)], status="ok", error="",
                   http_status=200, strategy="dom", elapsed_s=0.1, rescued=False)
    monkeypatch.setattr(R, "scrape_result", fake)
    paths.R = R
    paths.stages_mod = stages
    return paths


def _snapshot(*ps):
    return [p.read_bytes() for p in ps]


def _days_ago(n):
    return (_dtm.date.today() - _dtm.timedelta(days=n)).isoformat()


def _rows_by_name(p):
    return {r["company_name"]: r for r in _csv.DictReader(open(p, encoding="utf-8"))}


def _set_active(p, names, value="true"):
    """Flip rows active in a sandbox registry, so one sandbox can play consecutive NIGHTS.
    The registry grew 873 -> 969 active rows in three days; an alarm about that growth can
    only be tested by a fixture that can reproduce it."""
    rows = list(_csv.reader(open(p, encoding="utf-8")))
    want = set(names)
    for r in rows[1:]:
        if r[0] in want:
            r[4] = value
    with open(p, "w", newline="", encoding="utf-8") as f:
        _csv.writer(f).writerows(rows)


def test_refresh_carries_jobs_forward_on_error_but_never_on_empty(tmp_path, monkeypatch):
    """A company in this market can have zero openings for a month and still be a healthy
    source. Parking an active scrape row after a 3-day EMPTY streak retired good companies
    and made the next role posted there invisible. Only ERRORS park a row (after
    ROT_PARK_DAYS) and only ERRORS carry yesterday's jobs; a long empty streak just asks
    triage to re-read the page, and the row stays active and scanned."""
    stable = [f"Ok{i}" for i in range(12)]         # keeps the run under the 20% shrink guard
    old = {"Acme": [_il_job("Acme")], "Beta": [_il_job("Beta")], "Delta": [_il_job("Delta")],
           **{n: [_il_job(n)] for n in stable}}
    rot = {"Acme": {"since": _days_ago(7), "why": "error", "last": _days_ago(1), "n": 6},
           "Beta": {"since": _days_ago(60), "why": "empty", "last": _days_ago(1), "n": 59},
           "Delta": {"since": _days_ago(14), "why": "error", "last": _days_ago(1), "n": 13}}
    P = _refresh_sandbox(tmp_path, monkeypatch,
                         [("Acme",), ("Beta",), ("Gamma",), ("Delta",)] + [(n,) for n in stable],
                         old, rot, {"Acme": ("error", "http:404"), "Beta": ("empty", ""),
                                    "Delta": ("error", "goto:TimeoutError")})
    assert P.R.run(["--workers", "1"]) == 0
    cache = _json.loads(P.cache.read_text(encoding="utf-8"))
    assert cache["Acme"] == old["Acme"], "an error carries yesterday's jobs"
    assert "Beta" not in cache, "an empty result carries nothing"
    assert "Delta" not in cache, "the carry expires after CARRY_MAX_DAYS"
    assert len(cache["Gamma"]) == 1
    rot = _json.loads(P.rot.read_text(encoding="utf-8"))
    assert "Acme" not in rot, "a parked row starts with a clean streak when something re-activates it"
    assert rot["Beta"]["why"] == "empty" and rot["Beta"]["n"] == 60 and "Gamma" not in rot
    rows = _rows_by_name(P.csv)
    assert rows["Acme"]["active"] == "false" and rows["Acme"]["notes"].count("scrape rotted (error 7d)") == 1
    assert rows["Delta"]["active"] == "false"
    assert rows["Beta"]["active"] == "true" and rows["Beta"]["notes"].count("empty-but-suspect") == 1
    assert rows["Gamma"]["active"] == "true" and rows["Gamma"]["notes"] == ""
    # a second night: the flag is not appended twice; the parked row is no longer active, so
    # it is not scanned and its segment is not touched
    assert P.R.run(["--workers", "1"]) == 0
    rows = _rows_by_name(P.csv)
    assert rows["Beta"]["notes"].count("empty-but-suspect") == 1
    assert rows["Acme"]["notes"].count("scrape rotted") == 1 and rows["Acme"]["active"] == "false"


def test_refresh_rereads_the_registry_before_parking_and_keeps_other_writers_notes(tmp_path, monkeypatch):
    """Single-writer rule: the registry is re-read immediately before the write, rows are
    matched by name, and another tool's segment written during the run survives."""
    rot = {"Acme": {"since": _days_ago(9), "why": "error", "last": _days_ago(1), "n": 8}}
    P = _refresh_sandbox(tmp_path, monkeypatch, [("Acme", "listing-hunt 2026-08-01: verified 3 IL"), ("Zed",)],
                         {"Acme": [_il_job("Acme")]}, rot, {"Acme": ("error", "http:404")})
    real = P.R.scrape_result

    def racing(name, url, **kw):          # another writer touches the registry mid-run
        rows = list(_csv.reader(open(P.csv, encoding="utf-8")))
        for r in rows:
            if r and r[0] == "Zed":
                r[5] = "dark-triage 2026-08-24: page-empty"
        with open(P.csv, "w", newline="", encoding="utf-8") as f:
            _csv.writer(f).writerows(rows)
        return real(name, url, **kw)
    monkeypatch.setattr(P.R, "scrape_result", racing)
    assert P.R.run(["--workers", "1"]) == 0
    rows = _rows_by_name(P.csv)
    assert rows["Zed"]["notes"] == "dark-triage 2026-08-24: page-empty"
    assert rows["Acme"]["active"] == "false"
    assert "listing-hunt 2026-08-01" in rows["Acme"]["notes"] and "scrape rotted (error 9d)" in rows["Acme"]["notes"]


def test_refresh_mass_failure_guard_refuses_to_rot_park_or_drop(tmp_path, monkeypatch):
    """The night the runner breaks looks like 100 sites erroring at once. Above
    MASS_FAILURE_PCT the run is not a measurement: rot streaks do not advance, nothing is
    parked, the cache keeps every old entry, and the stamp says why. Below the row floor it
    is only an alarm."""
    names = [f"Co{i:02d}" for i in range(25)]
    old = {n: [_il_job(n)] for n in names}
    rot = {n: {"since": _days_ago(8), "why": "error", "last": _days_ago(1), "n": 7} for n in names[:5]}
    outcomes = {n: ("error", "goto:TimeoutError") for n in names[:24]}
    outcomes[names[24]] = ("ok", 2)
    P = _refresh_sandbox(tmp_path / "big", monkeypatch, [(n,) for n in names], old, rot, outcomes)
    before = _snapshot(P.csv, P.rot)
    assert P.R.run(["--workers", "1"]) == 0
    assert _snapshot(P.csv, P.rot) == before, "rot and registry untouched under mass failure"
    cache = _json.loads(P.cache.read_text(encoding="utf-8"))
    assert set(cache) == set(names) and len(cache[names[24]]) == 2
    stamp = _json.loads(P.stages.read_text(encoding="utf-8"))["collect"]
    assert stamp["alarm"].startswith("mass-failure-errors-96%") and stamp["errors"] == 24
    assert stamp["parked"] == 0, "five rows were parkable; a mass-failure night parks none and says so"
    # the threshold: 10 of 25 (40%) is a broken runner too
    P = _refresh_sandbox(tmp_path / "forty", monkeypatch, [(n,) for n in names], old, rot,
                         {n: ("error", "goto:TimeoutError") for n in names[:10]})
    before = _snapshot(P.csv, P.rot)
    assert P.R.run(["--workers", "1"]) == 0
    assert _snapshot(P.csv, P.rot) == before
    assert _json.loads(P.stages.read_text(encoding="utf-8"))["collect"]["alarm"].startswith("mass-failure-errors-40%")
    # the floor: 3 of 3 erroring is a bad night for 3 sites, not a broken runner
    P = _refresh_sandbox(tmp_path / "small", monkeypatch, [("A",), ("B",), ("C",)], {"A": [_il_job("A")]},
                         {"A": {"since": _days_ago(8), "why": "error", "last": _days_ago(1), "n": 7}},
                         {n: ("error", "http:503") for n in "ABC"})
    assert P.R.run(["--workers", "1"]) == 0
    assert _json.loads(P.rot.read_text(encoding="utf-8"))["B"]["why"] == "error", "rot advanced"
    assert _rows_by_name(P.csv)["A"]["active"] == "false"
    # three rows are below MASS_FAILURE_MIN_ROWS: no percentage token, no `no-jobs` (a
    # `--limit 3` or a budget-starved night must not read as an outage)
    assert "alarm" not in _json.loads(P.stages.read_text(encoding="utf-8"))["collect"]


def test_refresh_time_budget_carries_the_unprocessed_and_stamps_the_count(tmp_path, monkeypatch):
    """~850 rows against a 330-minute job: a timeout used to discard the entire run. The
    budget stops cleanly, untouched companies carry over from last night's cache, and the
    stamp says how many."""
    names = ["A", "B", "C", "D", "E"]
    old = {n: [_il_job(n)] for n in names}
    P = _refresh_sandbox(tmp_path, monkeypatch, [(n,) for n in names], old, {}, {"B": ("empty", "")})
    real = P.R.scrape_result

    def slow(name, url, **kw):
        _time.sleep(0.05)
        return real(name, url, **kw)
    monkeypatch.setattr(P.R, "scrape_result", slow)
    monkeypatch.setenv("SCRAPE_REFRESH_TIME_BUDGET_MIN", "0.0005")     # 30 ms
    assert P.R.run(["--workers", "1"]) == 0
    cache = _json.loads(P.cache.read_text(encoding="utf-8"))
    stamp = _json.loads(P.stages.read_text(encoding="utf-8"))["collect"]
    assert stamp["scraped"] == 1 and stamp["unprocessed"] == 4
    assert set(cache) == set(names), "unprocessed companies keep last night's entry"
    assert "unprocessed-4" in stamp["alarm"]
    # ...but one row of 25 (4%) is not an alarm — the budget trimming a tail is normal
    many = [f"N{i:02d}" for i in range(25)]
    P = _refresh_sandbox(tmp_path / "tail", monkeypatch, [(n,) for n in many], {n: [_il_job(n)] for n in many}, {})
    real2 = P.R.scrape_result
    calls = []

    def slow2(name, url, **kw):
        calls.append(name)
        if len(calls) == 24:
            _time.sleep(0.2)                 # the 24th row overruns; the 25th is never started
        return real2(name, url, **kw)
    monkeypatch.setattr(P.R, "scrape_result", slow2)
    monkeypatch.setenv("SCRAPE_REFRESH_TIME_BUDGET_MIN", "0.002")      # 120 ms
    assert P.R.run(["--workers", "1"]) == 0
    stamp = _json.loads(P.stages.read_text(encoding="utf-8"))["collect"]
    assert stamp["unprocessed"] >= 1 and "unprocessed" not in stamp.get("alarm", ""), stamp


def test_refresh_scoped_and_dry_runs_write_nothing(tmp_path, monkeypatch):
    """`--only`, `--limit`, `--only-missing`, `--shard` and `--dry-run` never touch the
    registry, the rot file, the stamp or the cache; `--apply` on a scoped run MERGES its hits
    into the cache and nothing else."""
    old = {"Acme": [_il_job("Acme")], "Beta": [_il_job("Beta")]}
    rot = {"Acme": {"since": _days_ago(9), "why": "error", "last": _days_ago(1)}}
    P = _refresh_sandbox(tmp_path, monkeypatch, [("Acme",), ("Beta",), ("Gamma",)], old, rot,
                         {"Acme": ("error", "http:403"), "Beta": ("empty", "")})
    P.stages.write_text("{}", encoding="utf-8")
    before = _snapshot(P.csv, P.cache, P.rot, P.stages)
    for argv in (["--only", "Acme,Beta", "--workers", "1"], ["--limit", "2", "--workers", "1"],
                 ["--only-missing", "--workers", "1"], ["--shard", "0", "2", "--workers", "1"],
                 ["--dry-run", "--workers", "1"]):
        assert P.R.run(argv) == 0, argv
        assert _snapshot(P.csv, P.cache, P.rot, P.stages) == before, argv
    assert P.R.run(["--only-missing", "--apply", "--workers", "1"]) == 0
    cache = _json.loads(P.cache.read_text(encoding="utf-8"))
    assert set(cache) == {"Acme", "Beta", "Gamma"}, "additive merge: nothing dropped"
    assert _snapshot(P.csv, P.rot, P.stages) == [before[0], before[2], before[3]]


def test_refresh_stamps_collect_with_counts_the_digest_renders(tmp_path, monkeypatch):
    """Nothing about the scrape reached the email: the workflow stamped `collect` bare. The
    script stamps it with counts; every value is a space-free token so `stages.summary()`
    (k=v joined by spaces, stages by ' | ') renders it in all three digest renderers."""
    P = _refresh_sandbox(tmp_path, monkeypatch, [("Acme",), ("Beta",), ("Gamma",), ("D",), ("E",), ("F",)],
                         {}, {}, {"Beta": ("empty", ""), "Gamma": ("error", "http:403")})
    assert P.R.run(["--workers", "1"]) == 0
    stamp = _json.loads(P.stages.read_text(encoding="utf-8"))["collect"]
    assert {"rows", "scraped", "with_jobs", "empty", "errors", "carried", "unprocessed",
            "parked", "uncached", "unvisited", "workers", "minutes"} <= set(stamp) \
        and "alarm" not in stamp                                    # 1/6 errors: no alarm
    assert stamp["unvisited"] <= stamp["uncached"] <= stamp["rows"]
    assert stamp["unvisited"] <= stamp["unprocessed"]
    for k, v in stamp.items():
        assert _re.fullmatch(r"[A-Za-z0-9_.%+:-]+", str(v)), (k, v)
    line = P.stages_mod.summary()
    assert f"collect: {_TODAY} (TODAY)" in line          # keys render alphabetically (stamp sorts)
    for tok in ("scraped=6", "with_jobs=4", "empty=1", "errors=1", "unprocessed=0"):
        assert f" {tok}" in line.split(" | ")[1], tok
    from pipeline import digest as D
    stats = {"stages": line, "paths": {}}
    _, md = D.build_markdown([], _TODAY, stats)
    assert "with_jobs=4" in md and "with_jobs=4" in D._text_audit(stats)
    assert "with_jobs=4" in D._html_audit(stats, lambda v: _html.escape(str(v)))


def test_refresh_counts_the_rows_the_digest_cannot_see(tmp_path, monkeypatch):
    """287 of 496 active scrape rows had no cache entry on 2026-08-28 -- invisible to the
    board, to `stale.json` and to the mail, because `fetch_scrape` only READS that file --
    and NOTHING counted them. The stamp now carries the count, and `stages.summary()` puts it
    in all three digest renderers."""
    names = [f"Co{i:02d}" for i in range(20)]
    old = {n: [_il_job(n)] for n in names[:12]}
    outcomes = {names[12]: ("empty", ""), names[13]: ("empty", ""),
                names[14]: ("error", "http:404"), names[15]: ("error", "http:500")}
    P = _refresh_sandbox(tmp_path, monkeypatch, [(n,) for n in names], old, {}, outcomes)
    assert P.R.run(["--workers", "1"]) == 0
    stamp = _json.loads(P.stages.read_text(encoding="utf-8"))["collect"]
    cache = _json.loads(P.cache.read_text(encoding="utf-8"))
    assert stamp["uncached"] == 4 == len([n for n in names if n not in cache])
    assert stamp["unvisited"] == 0, "every scraped row lands in the cache or in the rot file"
    assert stamp["unvisited"] <= stamp["uncached"] <= stamp["rows"]
    assert stamp["unvisited"] <= stamp["unprocessed"]
    assert "alarm" not in stamp, "a level, on the first night, is never an alarm"
    line = P.stages_mod.summary()
    assert " uncached=4" in line and " unvisited=0" in line
    from pipeline import digest as D
    stats = {"stages": line, "paths": {}}
    _, md = D.build_markdown([], _TODAY, stats)
    assert "uncached=4" in md and "uncached=4" in D._text_audit(stats)
    assert "uncached=4" in D._html_audit(stats, lambda v: _html.escape(str(v)))


def test_the_uncached_alarm_separates_a_growing_registry_from_a_breaking_extractor(
        tmp_path, monkeypatch):
    """The two causes of a rising `uncached` need opposite responses, and wave 1 showed a
    one-night count delta cannot tell them apart: the whole 216 -> 287 jump of 2026-08-28 was
    the pool moving 421 -> 496, i.e. the registry activating rows, and a naive bar fired on it.
    Every row the registry activates arrives uncached by construction, so pool growth since
    the anchor is SUBTRACTED. Both numbers are on the same stamp line, so the reader can check
    the arithmetic without yesterday's file."""
    active = [f"Co{i:02d}" for i in range(60)]
    dark = [f"New{i:02d}" for i in range(40)]
    rows = [(n,) for n in active] + [
        [n, "scrape", "", f"https://{n.lower()}.example/careers", "false", ""] for n in dark]
    P = _refresh_sandbox(tmp_path, monkeypatch, rows, {n: [_il_job(n)] for n in active}, {},
                         {n: ("empty", "") for n in dark})

    def stamp():
        return _json.loads(P.stages.read_text(encoding="utf-8"))["collect"]

    assert P.R.run(["--workers", "1"]) == 0
    assert stamp()["uncached"] == 0 and "alarm" not in stamp()
    for batch in (dark[:20], dark[20:40]):          # the registry activates 20 dark rows twice
        _set_active(P.csv, batch)
        assert P.R.run(["--workers", "1"]) == 0
        assert "uncached-up" not in stamp().get("alarm", ""), \
            "rows and uncached rose together: that is triage's business, not extraction's"
    assert stamp()["uncached"] == 40 and stamp()["rows"] == 100
    assert stamp()["uncached_base"] == 0 and stamp()["rows_base"] == 60, "the anchor HELD"


def test_the_uncached_alarm_is_a_ratchet_so_a_slow_leak_cannot_hide(tmp_path, monkeypatch):
    """Wave 1, measured over the real series: against a YESTERDAY baseline a leak of 24 rows a
    night is silent forever -- 168 rows, a third of the pool, in seven quiet nights -- because
    every single delta is under the bar. The anchor holds while coverage worsens, so the loss
    accumulates against a fixed point; it ratchets DOWN the moment coverage improves, so a
    recovery re-arms it; and it resets when the alarm fires, so one loss is announced once."""
    # 120 rows and 10 a night: each step stays under the shrink guard (>20% of the companies
    # that HAD jobs coming back empty aborts the run and keeps yesterday's cache), which is
    # itself the reason a leak this size is the dangerous one -- it is small enough that every
    # other guard in this file deliberately ignores it.
    names = [f"Co{i:03d}" for i in range(120)]
    P = _refresh_sandbox(tmp_path, monkeypatch, [(n,) for n in names],
                         {n: [_il_job(n)] for n in names}, {})
    real_out = P.R.scrape_result
    broken = set()

    def breaking(name, url, **kw):
        if name in broken:
            return _NS(jobs=[], status="empty", error="", http_status=200, strategy="",
                       elapsed_s=0.1, rescued=False, embed="", embed_seen="")
        return real_out(name, url, **kw)
    monkeypatch.setattr(P.R, "scrape_result", breaking)

    def stamp():
        return _json.loads(P.stages.read_text(encoding="utf-8"))["collect"]

    assert P.R.run(["--workers", "1"]) == 0 and stamp()["uncached"] == 0
    for k in range(3):                      # 10 rows stop extracting, three nights running
        broken.update(names[10 * k:10 * (k + 1)])
        assert P.R.run(["--workers", "1"]) == 0
        assert stamp()["uncached"] == 10 * (k + 1) and stamp()["rows"] == 120
    assert "uncached-up-0-to-30" in stamp()["alarm"],         "three silent nights of 10 accumulate against the anchor and fire on the third"
    assert stamp()["uncached_base"] == 30, "the anchor resets, so one loss is announced once"
    # a same-day re-run recomputes from the SAME anchor instead of laundering the alarm away
    assert P.R.run(["--workers", "1"]) == 0
    assert "uncached-up" not in stamp().get("alarm", ""), "announced once, then it stands"
    assert stamp()["uncached"] == 30 and stamp()["uncached_base"] == 30
    for k in range(3, 6):                   # and it re-arms: three more nights of 10
        broken.update(names[10 * k:10 * (k + 1)])
        assert P.R.run(["--workers", "1"]) == 0
    assert "uncached-up-30-to-60" in stamp()["alarm"]
    # recovery ratchets the anchor DOWN, so the next loss is measured from the better number
    broken.clear()
    assert P.R.run(["--workers", "1"]) == 0
    assert stamp()["uncached"] == 0 and stamp()["uncached_base"] == 0


def test_the_uncached_growth_rule_is_pure_and_says_what_it_measured():
    """The rule is a function of four numbers, three of which are on the stamp line it writes.
    Driven directly so the thresholds are pinned without a sandbox."""
    R = __import__("refresh_scrape_cache")
    assert R.UNCACHED_JUMP_MIN == 25 and R.UNCACHED_JUMP_PCT == 5
    # the one extraction regression on record: 30 rows in a night, pool flat
    assert R._uncached_grew(246, 421, (216, 421))
    # the reality of 2026-08-28: uncached +71 because the pool grew +75
    assert not R._uncached_grew(287, 496, (216, 421))
    # a pool that SHRANK cannot be used to hide a loss
    assert R._uncached_grew(250, 400, (216, 421))
    # the anchor: holds while worse, ratchets down when better, resets when it fires
    assert R._next_base(240, 421, (216, 421), False) == (216, 421)
    assert R._next_base(200, 421, (216, 421), False) == (200, 421)
    assert R._next_base(246, 421, (216, 421), True) == (246, 421)
    assert R._next_base(9, 9, None, False) == (9, 9)


def test_a_night_that_could_not_read_the_cache_is_not_a_baseline(tmp_path, monkeypatch):
    """The cache-unreadable exit stamps `uncached = rows` -- it can see no cache at all. Taken
    as a baseline that would make the NEXT night's real jump read as a fall, so the alarm
    would be silent on exactly the morning after an abort."""
    names = [f"Co{i:02d}" for i in range(40)]
    P = _refresh_sandbox(tmp_path, monkeypatch, [(n,) for n in names], {}, {})
    P.cache.write_text('{"A": [', encoding="utf-8")
    assert P.R.run(["--workers", "1"]) == 1
    stamp = _json.loads(P.stages.read_text(encoding="utf-8"))["collect"]
    assert stamp["uncached"] == 40 and stamp["alarm"] == "cache-unreadable"
    assert P.R._uncached_base() is None, "an abort stamp is refused as an anchor"
    P.cache.write_text("{}", encoding="utf-8")
    P2 = _refresh_sandbox(tmp_path, monkeypatch, [(n,) for n in names], {}, {},
                          {n: ("empty", "") for n in names[:30]})
    assert P2.R.run(["--workers", "1"]) == 0
    stamp = _json.loads(P2.stages.read_text(encoding="utf-8"))["collect"]
    assert stamp["uncached"] == 30 and "uncached-up" not in stamp.get("alarm", "")
    assert P2.R._uncached_base() == (30, 40), "a night that MEASURED a cache is an anchor"


def test_unvisited_is_zero_until_a_row_is_reached_by_nothing(tmp_path, monkeypatch):
    """`unvisited` is the part of `uncached` with no rot entry either: no run has an OUTCOME
    for it. Zero by construction on a complete night -- which is what makes any N an event,
    and what made it the leading indicator of the 287 a day before they were 287."""
    names = [f"Co{i:02d}" for i in range(25)]
    # A: the budget strands rows that are in NEITHER file -- nothing has ever scraped them
    P = _refresh_sandbox(tmp_path / "budget", monkeypatch, [(n,) for n in names], {}, {})
    clock = _TickingClock(P, monkeypatch)
    monkeypatch.setenv("SCRAPE_REFRESH_TIME_BUDGET_MIN", str(20 / 60))
    assert P.R.run(["--workers", "1"], clock=clock) == 0
    s = _json.loads(P.stages.read_text(encoding="utf-8"))["collect"]
    assert s["unprocessed"] > 0 and s["unvisited"] == s["unprocessed"] == s["uncached"]
    assert f"unvisited-{s['unvisited']}" in s["alarm"]
    # B: the SAME cut with yesterday's entries present -- a carried row is not invisible
    P2 = _refresh_sandbox(tmp_path / "carried", monkeypatch, [(n,) for n in names],
                          {n: [_il_job(n)] for n in names}, {})
    clock = _TickingClock(P2, monkeypatch)
    monkeypatch.setenv("SCRAPE_REFRESH_TIME_BUDGET_MIN", str(20 / 60))
    assert P2.R.run(["--workers", "1"], clock=clock) == 0
    s2 = _json.loads(P2.stages.read_text(encoding="utf-8"))["collect"]
    assert s2["unprocessed"] > 0 and s2["unvisited"] == 0 and s2["uncached"] == 0
    # C: the park trap. A parked row is excluded from BOTH counts -- the registry write that
    #    follows makes it inactive, and an inactive row is not coverage we are missing. Only
    #    the `uncached` assertion discriminates here: at count time the rot entry is still
    #    present (the pop happens after the stamp), so `unvisited` would read 0 even if
    #    `parking` were ignored entirely. Wave 1 caught that; the direct call below is the
    #    assertion that actually tests the exclusion.
    stable = [f"Ok{i}" for i in range(12)]
    P3 = _refresh_sandbox(tmp_path / "park", monkeypatch,
                          [("Gone",)] + [(n,) for n in stable],
                          {n: [_il_job(n)] for n in stable}, {"Gone": _rot_entry(9)},
                          {"Gone": ("error", "http:404")})
    assert P3.R.run(["--workers", "1"]) == 0
    assert _rows_by_name(P3.csv)["Gone"]["active"] == "false"
    s3 = _json.loads(P3.stages.read_text(encoding="utf-8"))["collect"]
    assert s3["parked"] == 1 and s3["uncached"] == 0 and s3["unvisited"] == 0
    gone_rows = [{"company_name": "Gone"}]
    assert P3.R._uncached(gone_rows, {}, [("Gone", "error 9d")]) == 0
    assert P3.R._uncached(gone_rows, {}, []) == 1, "the exclusion is what makes it 0"


def test_uncached_describes_the_cache_each_exit_actually_leaves(tmp_path, monkeypatch):
    """The abort paths do not rewrite the cache, and their whole POINT is that the digest
    still reads yesterday's file. A count taken from the run's opinion instead of from the
    dict that is written would report a catastrophe on the night a guard prevented one."""
    names = [f"Co{i:02d}" for i in range(25)]
    old = {n: [_il_job(n)] for n in names}
    P = _refresh_sandbox(tmp_path / "mass", monkeypatch, [(n,) for n in names], old, {},
                         {n: ("error", "goto:TimeoutError") for n in names[:24]})
    assert P.R.run(["--workers", "1"]) == 0
    s = _json.loads(P.stages.read_text(encoding="utf-8"))["collect"]
    assert s["alarm"].startswith("mass-failure-") and s["uncached"] == 0
    assert len(_json.loads(P.cache.read_text(encoding="utf-8"))) == 25
    P2 = _refresh_sandbox(tmp_path / "shrink", monkeypatch, [(n,) for n in names], old, {},
                          {n: ("empty", "") for n in names[:9]})
    assert P2.R.run(["--workers", "1"]) == 0
    s2 = _json.loads(P2.stages.read_text(encoding="utf-8"))["collect"]
    assert s2["alarm"] == "shrink-abort-25-to-16" and s2["uncached"] == 0
    P3 = _refresh_sandbox(tmp_path / "normal", monkeypatch, [(n,) for n in names], old, {},
                          {n: ("empty", "") for n in names[:4]})     # under the shrink bar
    assert P3.R.run(["--workers", "1"]) == 0
    s3 = _json.loads(P3.stages.read_text(encoding="utf-8"))["collect"]
    assert "alarm" not in s3 and s3["uncached"] == 4

def _embed_rendered(html="", urls=(), comeet=None, url="https://x.example/careers"):
    import scrape_universal as SU
    r = SU.Rendered(url=url)
    r.page_html = html
    r.req_urls = list(urls)
    r.comeet = dict(comeet or {})
    return r


def test_scrape_an_embedded_token_never_carries_markup(tmp_path):
    """`resolve_deep.ATS_PATTERNS`' slug classes are `[^/?]+` and `wayback_rescue.extract_ats`
    applies them to raw HTML, so they swallow the attribute that follows. Measured 2026-08-28
    over the uncached rows: `stigg"`, `unframe"`, `traildsoftware" class="jw-cta`,
    `FORDEFIJobs.ashbyhq.com`. Two of those four build an api_url that 404s. The `.` must
    SURVIVE (a Comeet uid is `D3.00B`) and so must the `/` (a Workday token is `tenant/site`).
    Filed for `registry`; this is the defence, and it is pinned so it cannot rot after the fix."""
    import scrape_universal as SU
    for dirty, clean in [('stigg"', "stigg"), ('unframe"', "unframe"),
                         ('traildsoftware" class="jw-cta', "traildsoftware"),
                         ("FORDEFIJobs.ashbyhq.com", "FORDEFIJobs"),
                         ("D3.00B", "D3.00B"), ("03.009", "03.009"),
                         ("novartis/site3", "novartis/site3"),
                         ('bad"/tail', "bad"), ("", ""), ("---", "")]:
        assert SU._slug_ok(dirty) == clean, dirty
        got = SU._slug_ok(dirty)
        assert not got or _re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._~/-]{0,79}", got), got


def test_scrape_an_embedded_board_that_does_not_vouch_is_recorded_and_never_admitted():
    """`identity_gate.embedded_board_ok` is the gate written for this caller: a held page can
    REFUSE a board and never ADMIT one, because Cogniteam's own careers page carried
    Riskified's greenhouse board. Cannot-tell (a Comeet uid) is `unverified` -- DEFERRED, and
    handed to `registry`, which can declare the tenant -- never `not-ours`, which would tell
    the next reader the board was proven to belong to somebody else."""
    import scrape_universal as SU
    from pipeline import fetchers
    calls = []

    def boom(row):
        calls.append(row)
        raise AssertionError("a refused board must never be fetched")
    with _mp.context() as m:
        m.setattr(fetchers, "fetch_company", boom)
        r = _embed_rendered(urls=["https://boards-api.greenhouse.io/v1/boards/riskified/jobs"])
        assert SU._from_embedded_board("Cogniteam", r.url, r) == []
        assert r.embed_seen == "greenhouse:riskified:not-ours"
        r2 = _embed_rendered(comeet={"u": "D3.00B", "t": "A1B2C3D4E5F60718293A"})
        assert SU._from_embedded_board("REE Automotive", r2.url, r2) == []
        assert r2.embed_seen == "comeet:D3.00B:unverified"
        assert calls == []


def test_scrape_reads_the_board_a_rendered_page_names_only_in_its_own_traffic():
    """The two signals an unrendered probe cannot see, and which are why 15 detections over
    287 uncached rows is a FLOOR: the widget's own XHR, and `window.comeetvar` (Comeet writes
    the uid and token into `window`, never into the markup -- which is why Nova's page
    contains the word `comeet` and no board)."""
    import scrape_universal as SU
    r = _embed_rendered(urls=["https://cdn.x.example/a.js",
                              "https://api.ashbyhq.com/posting-api/job-board/stigg"])
    assert SU._detect_embedded_board(r)[:2] == ("ashby", "stigg")
    r2 = _embed_rendered(comeet={"u": "2E.001", "t": "FFEEDDCCBBAA99887766"})
    plat, tok, api, repaired = SU._detect_embedded_board(r2)
    assert (plat, tok) == ("comeet", "2E.001") and "2E.001" in api and "FFEEDD" in api
    assert SU._detect_embedded_board(_embed_rendered(html="<p>no board here</p>")) is None
    # an ATS name in prose is not a board: the detector needs a real address
    assert SU._detect_embedded_board(_embed_rendered(html="we use comeet and greenhouse")) is None


def test_scrape_the_embed_record_reaches_the_rot_file_and_the_stamp(tmp_path, monkeypatch):
    """A refused board on a row that yields ZERO is the only nightly handoff `registry` has
    for 'this row should be a comeet/ashby row'. It rides the row's existing rot entry -- a
    file scrape-refresh.yml already commits -- so no workflow change is needed, and it is
    counted on the `collect` line so the mail says how many there were."""
    names = [f"Co{i:02d}" for i in range(14)]
    outcomes = {names[0]: ("empty", ""), names[1]: ("empty", "")}
    P = _refresh_sandbox(tmp_path, monkeypatch, [(n,) for n in names],
                         {n: [_il_job(n)] for n in names[2:]}, {}, outcomes)
    real = P.R.scrape_result

    def with_embed(name, url, **kw):
        res = real(name, url, **kw)
        if name == names[0]:
            res.embed_seen = "greenhouse:riskified:not-ours"
        if name == names[1]:
            res.embed_seen = "comeet:D3.00B:unverified"
        return res
    monkeypatch.setattr(P.R, "scrape_result", with_embed)
    assert P.R.run(["--workers", "1"]) == 0
    rot = _json.loads(P.rot.read_text(encoding="utf-8"))
    assert rot[names[0]]["embed"] == "greenhouse:riskified:not-ours"
    assert rot[names[1]]["embed"] == "comeet:D3.00B:unverified"
    stamp = _json.loads(P.stages.read_text(encoding="utf-8"))["collect"]
    assert stamp["embeds"] == 2 and stamp["embeds_won"] == 0
    assert stamp["embeds_won"] <= stamp["embeds"] <= stamp["scraped"]
    for k, v in stamp.items():
        assert _re.fullmatch(r"[A-Za-z0-9_.%+:-]+", str(v)), (k, v)
    assert " embeds=2" in P.stages_mod.summary()


def test_the_scraper_never_reaches_a_gate_that_can_spend_bright_data():
    """`identity_gate.page_names_company` -- reachable from `activation_verdict`,
    `activation_ok`, `ok_to_write`, `write_verdict` and `identity_ok` -- reads a page, and a
    short read falls through to `bd_rescue.unlock` under BRIGHTDATA_API_KEY, which
    scrape-refresh.yml SETS. Its budget is PER PROCESS (100) in a 4-way pool recycled every
    25 rows, and the `collect` stamp counts none of it. A free rung must not become the
    largest un-metered consumer of the paid pool, so the scraper may reach exactly two gates:
    `embedded_board_ok` and `board_vouches`, neither of which touches the network."""
    import ast as _ast
    import pathlib
    banned = {"activation_verdict", "activation_ok", "ok_to_write", "write_verdict",
              "identity_ok", "page_names_company", "human_board_url"}
    # resolved from THIS FILE, never from cwd: a test that reads `pathlib.Path("x.py")`
    # inherits whatever directory the runner happens to be in (docs/BACKLOG.md 344)
    root = pathlib.Path(__file__).resolve().parent.parent
    for mod in ("scrape_universal.py", "refresh_scrape_cache.py", "cache_new_rows.py"):
        tree = _ast.parse((root / mod).read_text(encoding="utf-8"))
        names = {n.attr for n in _ast.walk(tree) if isinstance(n, _ast.Attribute)}
        names |= {n.id for n in _ast.walk(tree) if isinstance(n, _ast.Name)}
        for n in _ast.walk(tree):
            if isinstance(n, _ast.ImportFrom):
                names |= {a.name for a in n.names}
        assert not (names & banned), (mod, sorted(names & banned))
    # and the scraper is not a registry writer, so GATE_CALLERS must NOT name it
    from pipeline import identity_gate as G
    for who in G.GATE_CALLERS.values():
        assert not ({"scrape_universal.py", "refresh_scrape_cache.py"} & set(who))

def test_scrape_the_embed_rung_never_fires_when_the_ladder_read_the_board():
    """The non-regression proof, as an assertion. The rung sits after the ladder's own
    `if add.israeli: return done()`, so `add.israeli == 0` is guaranteed by the line above it
    -- and it receives no adder, so it cannot promote, dedupe against, re-locate or reorder
    anything the five strategies produced. A row that already works cannot change."""
    import scrape_universal as SU
    from pipeline import fetchers
    board = "https://boards-api.greenhouse.io/v1/boards/someoneelse/jobs"

    def boom(row):
        raise AssertionError("the ladder already read this board")

    ld = {"@context": "https://schema.org", "@type": "JobPosting",
          "title": "Senior Data Analyst", "datePosted": "2026-08-20",
          "hiringOrganization": {"name": "Acme"},
          "jobLocation": {"address": {"addressLocality": "Tel Aviv",
                                      "addressCountry": "IL"}},
          "url": "https://acme.example/jobs/1"}
    with _mp.context() as m:
        m.setattr(fetchers, "fetch_company", boom)
        r = SU.Rendered(url="https://acme.example/careers")
        r.blobs = [_json.dumps(ld), _json.dumps({**ld, "title": "Senior BI Analyst",
                                                 "url": "https://acme.example/jobs/2"}),
                   _json.dumps({**ld, "title": "Product Analyst",
                                "url": "https://acme.example/jobs/3"})]
        r.req_urls = [board]
        jobs, strategy = SU._extract("Acme", r.url, r)
        assert jobs and strategy and "embed" not in strategy, (len(jobs), strategy)
        assert r.embed == "" and r.embed_seen == "", "not even detected: the rung is unreached"


def test_scrape_the_embed_handoff_is_one_bounded_call_with_a_kill_switch():
    """A rung that spends no shared quota still spends WALL CLOCK, and `pipeline.http` binds
    its timeout default at import while `fetch_company` takes none -- worst case 3 retries at
    30 s, which overruns COMPANY_BUDGET_S on its own. One call, a hard join, a deadline floor,
    and a switch that actually switches it off."""
    import scrape_universal as SU
    from pipeline import fetchers
    calls = []

    def counting(row):
        calls.append(row["company_name"])
        return [dict(_il_job("Stigg"), country_code="IL")]

    def mk():
        r = SU.Rendered(url="https://stigg.io/careers")
        r.req_urls = ["https://api.ashbyhq.com/posting-api/job-board/stigg"]
        return r
    # `_detect_ats` returns ONE tuple however many boards a page names -- and it picks by
    # ATS_PATTERNS order, not by which board is the company's, so a page carrying a partner's
    # greenhouse widget beside its own ashby board detects the greenhouse one and the gate
    # then refuses it. That costs a conversion; it can never cost an admission. Filed for
    # `registry` (docs/BACKLOG.md). What matters here is that the fetch is at most ONE.
    two = SU.Rendered(url="https://stigg.io/careers")
    two.req_urls = ["https://api.ashbyhq.com/posting-api/job-board/stigg",
                    "https://boards-api.greenhouse.io/v1/boards/other/jobs"]
    det = SU._detect_embedded_board(two)
    assert det is not None and len(det) == 4 and det[0] == "greenhouse"
    with _mp.context() as m:
        m.setattr(fetchers, "fetch_company", counting)
        m.delenv("SCRAPE_EMBED_HANDOFF", raising=False)
        m.delenv("SCRAPE_EMBED_DETECT", raising=False)
        assert SU._from_embedded_board("Stigg", two.url, two) == [] and calls == []
        assert two.embed_seen == "greenhouse:other:unverified", two.embed_seen
        r = mk()
        assert SU._from_embedded_board("Stigg", r.url, r)
        assert calls == ["Stigg"], "one admitted board, exactly one fetch"
        # the deadline floor: what cannot finish is not started
        calls.clear()
        r = mk()
        assert SU._from_embedded_board("Stigg", r.url, r, deadline=SU.Deadline.start(1)) == []
        assert calls == [] and r.embed_seen.endswith(":ok:deadline")
        # the kill switches
        calls.clear()
        m.setenv("SCRAPE_EMBED_HANDOFF", "0")
        r = mk()
        assert SU._from_embedded_board("Stigg", r.url, r) == [] and calls == []
        assert r.embed_seen == "ashby:stigg:ok", "detection and the record survive the switch"
        m.setenv("SCRAPE_EMBED_DETECT", "0")
        r = mk()
        assert SU._from_embedded_board("Stigg", r.url, r) == [] and r.embed_seen == ""
    # a fetcher that never returns is abandoned at the wall, not waited on
    with _mp.context() as m:
        m.setattr(SU, "_EMBED_FETCH_TIMEOUT_S", 1)
        m.setattr(fetchers, "fetch_company", lambda row: _time.sleep(30))
        r = mk()
        t0 = _time.monotonic()
        assert SU._from_embedded_board("Stigg", r.url, r) == []
        assert _time.monotonic() - t0 < 8, "the join is a WALL, not a suggestion"
        assert r.embed_seen.endswith(":ok:timeout")


def test_a_handed_off_posting_is_still_a_scrape_row_and_keeps_the_boards_country_code():
    """Two things the handoff must not quietly change. The ROW stays `scrape`: `store.seen_id`
    and the card's `sources` tag are keyed on it, so flipping it would re-key every role this
    company ever had. And `country_code` is KEPT, unlike a scraped card's, which this module
    blanks because the SCRAPER guessed -- here the board STATES it, and `is_israel_job` treats
    a non-IL code as an authoritative negative, which drops a foreign role a card would keep."""
    import scrape_universal as SU
    from pipeline import fetchers, israel
    payload = [dict(_il_job("Stigg", 1), country_code="IL", ats_platform="ashby"),
               dict(_il_job("Stigg", 2), country_code="US", location="New York",
                    ats_platform="ashby")]
    with _mp.context() as m:
        m.setattr(fetchers, "fetch_company", lambda row: [dict(j) for j in payload])
        m.delenv("SCRAPE_EMBED_HANDOFF", raising=False)
        r = SU.Rendered(url="https://stigg.io/careers")
        r.req_urls = ["https://api.ashbyhq.com/posting-api/job-board/stigg"]
        jobs = SU._from_embedded_board("Stigg", r.url, r)
    assert len(jobs) == 2 and r.embed == "ashby" and r.embed_seen == "ashby:stigg:won"
    assert all(j["ats_platform"] == "scrape" for j in jobs), "the ROW is a scrape row"
    assert all(j["_board"] == "ashby" for j in jobs), "the real platform rides in _board"
    assert [j["country_code"] for j in jobs] == ["IL", "US"], "the board's own claim survives"
    assert [israel.is_israel_job(j) for j in jobs] == [True, False], "a US code is a negative"


def test_a_board_with_no_israel_role_is_not_a_discovery_and_does_not_take_over():
    """A handoff that reaches a foreign-only board has not learned that this company has no
    Israel roles -- it has learned nothing. It must fall through with the ladder's own list so
    `no_il` still counts what the PAGE showed, and it must say which of the four ways it
    failed: `no-il`, `empty`, a fetcher name, or `timeout`."""
    import scrape_universal as SU
    from pipeline import fetchers

    def mk():
        r = SU.Rendered(url="https://stigg.io/careers")
        r.req_urls = ["https://api.ashbyhq.com/posting-api/job-board/stigg"]
        return r
    for payload, tail in (([dict(_il_job("Stigg"), country_code="US", location="Austin")],
                           "ok:no-il"),
                          ([], "ok:empty")):
        with _mp.context() as m:
            m.setattr(fetchers, "fetch_company", lambda row, p=payload: [dict(j) for j in p])
            r = mk()
            assert SU._from_embedded_board("Stigg", r.url, r) == []
            assert r.embed == "" and r.embed_seen.endswith(tail), r.embed_seen
    with _mp.context() as m:
        def raiser(row):
            raise ValueError("boom")
        m.setattr(fetchers, "fetch_company", raiser)
        r = mk()
        assert SU._from_embedded_board("Stigg", r.url, r) == []
        assert r.embed_seen == "ashby:stigg:ok:ValueError"


def test_the_embed_stage_keeps_the_via_counts_summing_to_with_jobs(tmp_path, monkeypatch):
    """ARCHITECTURE section 5a: `via` sums to `with_jobs` and a line that does not reconcile
    is not from this code. A sixth ladder stage must not break that, and its label must be a
    space-free token or `stages.summary()`'s k=v rendering comes apart."""
    import scrape_universal as SU
    assert SU._STAGES[-1] == "embed" and len(SU._STAGES) == 6
    names = [f"Co{i:02d}" for i in range(14)]
    P = _refresh_sandbox(tmp_path, monkeypatch, [(n,) for n in names], {}, {},
                         {names[0]: ("empty", ""), names[1]: ("error", "http:404")})
    real = P.R.scrape_result

    def some_embed(name, url, **kw):
        res = real(name, url, **kw)
        if name in names[2:5]:
            res.strategy, res.embed, res.embed_seen = "embed", "comeet", "comeet:ab.001:won"
        return res
    monkeypatch.setattr(P.R, "scrape_result", some_embed)
    assert P.R.run(["--workers", "1"]) == 0
    stamp = _json.loads(P.stages.read_text(encoding="utf-8"))["collect"]
    assert stamp["with_jobs"] + stamp["empty"] + stamp["errors"] == stamp["scraped"] == 14
    via = dict(_re.fullmatch(r"([a-z-]+)(\d+)", part).groups()
               for part in stamp["via"].split("+"))
    assert sum(int(v) for v in via.values()) == stamp["with_jobs"], stamp["via"]
    assert via.get("embed") == "3" and stamp["embeds_won"] == 3 and stamp["embeds"] == 3
    assert _re.fullmatch(r"[A-Za-z0-9_.%+:-]+", stamp["via"])
    assert stamp["embeds_won"] <= stamp["embeds"] <= stamp["scraped"]

def test_unvisited_counts_the_rot_file_each_exit_actually_leaves(tmp_path, monkeypatch):
    """Wave 1 falsified the invariant. `_apply_result` POPS a healthy company's rot entry and
    INSERTS a rotting one, but the two abort exits return before `write_json(ROT_PATH, rot)`,
    so a count taken from the live dict describes a file that will never exist. Both
    directions were reachable with no race and no corruption:

    * shrink-abort — a row scraped SUCCESSFULLY tonight and absent from yesterday's cache had
      its entry popped in memory, so it read as never-visited, raising a false `unvisited-N`
      on the one morning the operator is already reading that line closely. It also broke
      `unvisited <= unprocessed`, which is the claim the whole design rests on.
    * mass-failure — a row nothing has ever scraped, which errored tonight, had an entry
      INSERTED in memory, so `unvisited` read 0 while the file on disk still knew nothing
      about it: the leading indicator is silent on exactly the night that would produce it.
    """
    names = [f"C{i:02d}" for i in range(25)]
    old = {n: [_il_job(n)] for n in names}
    # A. shrink-abort: RotCo succeeds tonight, is not in yesterday's cache, and HAS a rot entry
    P = _refresh_sandbox(tmp_path / "shrink", monkeypatch,
                         [(n,) for n in names] + [("RotCo",)], old,
                         {"RotCo": _rot_entry(9)},
                         {n: ("empty", "") for n in names[:9]})
    assert P.R.run(["--workers", "1"]) == 0
    s = _json.loads(P.stages.read_text(encoding="utf-8"))["collect"]
    assert s["alarm"].startswith("shrink-abort-"), s["alarm"]
    assert "RotCo" in _json.loads(P.rot.read_text(encoding="utf-8")), "the pop never reached disk"
    assert s["uncached"] == 1, "RotCo is genuinely not in the cache this exit left"
    assert s["unvisited"] == 0, "...but the rot file on disk has known it for nine nights"
    assert s["unvisited"] <= s["unprocessed"], "the invariant the design rests on"
    assert "unvisited-" not in s.get("alarm", ""), "no false alarm on an abort night"
    # B. mass-failure: NeverSeen is in neither file, and tonight's insert is discarded
    P2 = _refresh_sandbox(tmp_path / "mass", monkeypatch,
                          [(n,) for n in names] + [("NeverSeen",)], old, {},
                          {n: ("error", "goto:TimeoutError") for n in names + ["NeverSeen"]})
    assert P2.R.run(["--workers", "1"]) == 0
    s2 = _json.loads(P2.stages.read_text(encoding="utf-8"))["collect"]
    assert s2["alarm"].startswith("mass-failure-")
    assert _json.loads(P2.rot.read_text(encoding="utf-8")) == {}, "the insert never reached disk"
    assert s2["uncached"] == 1 and s2["unvisited"] == 1, \
        "a row nothing has ever scraped is STILL unvisited after a night that measured nothing"


def test_a_scope_flag_that_parses_to_nothing_is_refused_not_widened(tmp_path, monkeypatch):
    """`--only "$COMPANY"` with COMPANY unset parsed to the empty set, which is falsy, so
    `scoped` was False: a flag typed to NARROW the run rewrote the whole cache, parked rows in
    companies.csv and STAMPED `collect` -- replacing the entry and resetting `date` to today.
    `--limit 0` is the same shape (wave-1 attacker A, F4)."""
    R = __import__("refresh_scrape_cache")
    for argv in (["--only", ""], ["--only", ","], ["--only", " , "],
                 ["--limit", "0"], ["--limit", "-3"]):
        with pytest.raises(SystemExit):
            R._parse(argv)
    assert R._parse(["--only", "Wix,Fiverr"]).scoped
    assert R._parse(["--limit", "5"]).scoped and R._parse(["--only-missing"]).scoped
    assert not R._parse([]).scoped, "the cron is still unscoped"


def test_one_scalar_in_the_rot_file_does_not_cost_the_night(tmp_path, monkeypatch):
    """`_load` validates only the TOP level, and `scrape_rot.json` is merged per key on a push
    conflict. A scalar value raised `AttributeError` inside `_rot_bump`, in the parent loop,
    AFTER all the Chromium work and BEFORE the cache was written: no cache, no stamp, the
    night gone. Exactly the reachability `_ip_age`'s own docstring was hardened against
    (wave-1 attacker A, F5)."""
    names = [f"Co{i:02d}" for i in range(14)]
    P = _refresh_sandbox(tmp_path, monkeypatch, [(n,) for n in names],
                         {n: [_il_job(n)] for n in names},
                         {names[0]: "not-a-dict", names[1]: 7, names[2]: None},
                         {names[0]: ("empty", ""), names[1]: ("error", "http:404")})
    assert P.R.run(["--workers", "1"]) == 0, "the night survives a malformed rot entry"
    rot = _json.loads(P.rot.read_text(encoding="utf-8"))
    assert isinstance(rot[names[0]], dict) and rot[names[0]]["n"] == 1, "the entry restarts"
    assert _json.loads(P.cache.read_text(encoding="utf-8")), "and the cache was written"

def test_the_embed_handoff_refuses_a_board_that_merely_starts_like_our_name():
    """CLAUDE.md rule 5, as the assertion the repo would most regret not having.

    `identity_gate.embedded_board_ok` is calibrated for a REGISTRY writer, where a human reads
    the note it stamps. Its near-equality composes two vocabulary strippers --
    `_EMBED_TOKEN_WORDS` over the token's tail, `_tenant_near` over legal suffixes -- into
    prefix-containment in practice, so it admits `<our name> + <any vocabulary tail>`. An
    adversarial pass drove six LIVE registry rows end to end into publishing a stranger's
    board, and measured that 492 of 496 active scrape rows admit some slug strictly longer
    than their own core. Here the next step is the public board and the 05:45 mail, with
    nobody in between, so the tenant must be DECLARED or normalise EXACTLY.

    Every left-hand name below is a real active row and every right-hand slug is a real other
    company's board. Exact equality refuses all of them and keeps all five boards the gate
    legitimately admitted on 2026-08-28 -- the whole cost of the strictness is conversions
    that become a handoff line for `registry` instead of a posting on the board.
    """
    import scrape_universal as SU

    def gh(slug):
        return f"https://boards-api.greenhouse.io/v1/boards/{slug}/jobs"

    leaks = [("Nova", "novalabs"), ("HUB Security", "hubinternational"),
             ("Aqua Security", "aquatech"), ("Zoomd", "zoom"), ("Skai", "kai"),
             ("Darrow", "arrow"), ("Gett", "getty"), ("Sight Sciences", "sight"),
             ("Bright Security", "bright"), ("TripleW", "triple"),
             ("one \u05e4\u05ea\u05e8\u05d5\u05e0\u05d5\u05ea", "onemedical")]
    for name, slug in leaks:
        assert not SU._embed_admits(name, slug, gh(slug)), f"{name} <- {slug}"
    for name, slug in [("Stigg", "stigg"), ("Digital Turbine", "digitalturbine"),
                       ("Unframe", "unframe"), ("Plateful", "plateful"),
                       ("REAL DEV INC", "real-dev-inc")]:
        assert SU._embed_admits(name, slug, gh(slug)), f"{name} <- {slug} must still pass"
    # and the incident the gate itself was written for still refuses
    assert not SU._embed_admits("Cogniteam", "riskified", gh("riskified"))


def test_a_token_the_scraper_had_to_repair_is_never_fetched():
    """Sanitising is monotone TOWARDS admission -- truncating at the first markup character
    returns a PREFIX, and prefix-containment is exactly what the old rule admitted on:
    `getty%20images` became `getty`, which was then admitted for `Gett`. The rebuilt api_url
    can also point at a different board than the page named (`nova/nova%20site` ->
    `nova/nova`, a different Workday site). So a token this module had to cut markup out of is
    RECORDED for `registry`, with the raw string, and never fetched (wave-1 attacker C, S2)."""
    import scrape_universal as SU
    from pipeline import fetchers
    calls = []
    with _mp.context() as m:
        m.setattr(fetchers, "fetch_company", lambda row: calls.append(row) or [])
        m.delenv("SCRAPE_EMBED_HANDOFF", raising=False)
        r = SU.Rendered(url="https://stigg.io/careers")
        r.page_html = '<iframe src="https://boards-api.greenhouse.io/v1/boards/stigg"></iframe>'
        det = SU._detect_embedded_board(r)
        assert det is not None and det[3] is True, "the markup was repaired"
        assert SU._from_embedded_board("Stigg", r.url, r) == []
        assert r.embed_seen.endswith(":markup") and "stigg" in r.embed_seen
        assert calls == [], "a repaired token is evidence for a human, not for a fetcher"


def test_no_posting_in_the_committed_cache_came_from_an_unadmitted_board():
    """A standing check on the artefact rather than the code: every posting a handoff put in
    `scraped_cache.json` carries `_board`, and its company must still admit that board under
    today's rule. If `registry` later declares a tenant this passes for a new reason; if
    someone loosens the rule, this is what goes red."""
    import json as _j
    import pathlib
    import scrape_universal as SU
    root = pathlib.Path(__file__).resolve().parent.parent
    cache = _j.loads((root / "scraped_cache.json").read_text(encoding="utf-8"))
    handed = [(name, j) for name, jobs in cache.items() for j in jobs if j.get("_board")]
    for name, j in handed:
        assert SU._embed_admits(name, j.get("_token", ""), j.get("_board_url", "")), \
            f"{name} carries a posting from {j['_board']} it no longer admits"

def test_only_missing_reaches_the_never_visited_rows_first(tmp_path, monkeypatch):
    """A scoped run is not day-rotated and the registry APPENDS, so rows no run has ever seen
    sit at the very end of `--only-missing`. On 2026-08-28 all 71 of them were at positions
    217-287 of 287 -- and every one of the 70 boards that pass recovered came from that tail,
    because the previously-visited rows genuinely extract zero. A time budget that binds would
    therefore strand exactly the rows the flag exists to reach, and this is the command the
    `unvisited-N` alarm tells the operator to run. Never-visited sorts first; the order stays
    deterministic within each group."""
    names = [f"Co{i:02d}" for i in range(6)]
    P = _refresh_sandbox(tmp_path, monkeypatch, [(n,) for n in names], {},
                         {n: _rot_entry(2, why="empty") for n in names[:4]})
    o = P.R._parse(["--only-missing"])
    cache, rot = {}, {n: _rot_entry(2, why="empty") for n in names[:4]}
    picked = [r["company_name"] for r in P.R._select_rows(o, cache, rot)]
    assert picked[:2] == [names[4], names[5]], picked
    assert picked[2:] == names[:4], "and the visited ones keep registry order behind them"
    assert P.R._select_rows(o, cache, rot) == P.R._select_rows(o, cache, rot)
    # with no rot file at all nothing is reordered
    assert [r["company_name"] for r in P.R._select_rows(o, cache, None)] == names



def test_refresh_shrink_abort_keeps_the_cache_and_stamps_its_reason(tmp_path, monkeypatch):
    """A run whose rebuilt cache would lose more than 20% of its companies keeps the old
    file (mass-empty is as suspicious as mass-error) — and now says so in the stamp instead
    of returning silently."""
    names = [f"C{i:02d}" for i in range(25)]
    old = {n: [_il_job(n)] for n in names}
    P = _refresh_sandbox(tmp_path / "full", monkeypatch, [(n,) for n in names], old, {},
                         {n: ("empty", "") for n in names[:9]})
    before = _snapshot(P.cache, P.rot, P.csv)
    assert P.R.run(["--workers", "1"]) == 0
    assert _snapshot(P.cache, P.rot, P.csv) == before
    stamp = _json.loads(P.stages.read_text(encoding="utf-8"))["collect"]
    assert stamp["alarm"] == "shrink-abort-25-to-16" and stamp["parked"] == 0
    # wave 1 (2026-08-24): the guard used to compare the whole rebuilt cache, so a night the
    # budget cut short (carried entries padding the count) could drop every processed
    # company's jobs unnoticed. It is measured over what was processed.
    P = _refresh_sandbox(tmp_path / "starved", monkeypatch, [(n,) for n in names], old, {},
                         {n: ("empty", "") for n in names[:19]})
    clock = _TickingClock(P, monkeypatch)                  # one second per company; no real sleeps
    monkeypatch.setenv("SCRAPE_REFRESH_TIME_BUDGET_MIN", str(19 / 60))     # ~20 rows
    assert P.R.run(["--workers", "1"], clock=clock) == 0
    stamp = _json.loads(P.stages.read_text(encoding="utf-8"))["collect"]
    assert stamp["alarm"].startswith("shrink-abort-") and stamp["unprocessed"] > 0
    assert _json.loads(P.cache.read_text(encoding="utf-8")) == old
    # ...and it is measured over what was PROCESSED, not the whole cache: 10 of 25 processed,
    # 5 of those lost = 50% (the whole-cache view would say 5 of 25 = 20%, no abort).
    # BACKLOG 158: this scenario was red on the calendar days the rotation moved the five
    # emptied rows past the budget cut, and flaky on a slow runner (real sleeps against a
    # wall-clock budget); the sandbox pins the rotation and the clock is injected.
    P = _refresh_sandbox(tmp_path / "half", monkeypatch, [(n,) for n in names], old, {},
                         {n: ("empty", "") for n in names[:5]})
    clock = _TickingClock(P, monkeypatch)
    monkeypatch.setenv("SCRAPE_REFRESH_TIME_BUDGET_MIN", str(9 / 60))      # ~10 rows
    assert P.R.run(["--workers", "1"], clock=clock) == 0
    stamp = _json.loads(P.stages.read_text(encoding="utf-8"))["collect"]
    assert 8 <= stamp["scraped"] <= 12 and stamp["alarm"].startswith("shrink-abort-")
    # the token names what was PROCESSED (had = scraped), not the 25-company cache
    assert int(stamp["alarm"].split("-")[2]) == stamp["scraped"], stamp["alarm"]


class _TickingClock:
    """A clock the refresh reads instead of `time.time`: advances one second per scraped
    company, so a time budget selects a row count, not a race."""

    def __init__(self, P, monkeypatch):
        self.t = 1_000_000.0
        real = P.R.scrape_result

        def ticking(name, url, **kw):
            self.t += 1.0
            return real(name, url, **kw)
        monkeypatch.setattr(P.R, "scrape_result", ticking)

    def __call__(self):
        return self.t


def test_refresh_pool_and_inline_paths_build_the_same_cache(tmp_path, monkeypatch):
    """Bookkeeping happens in the parent, in registry order: a 3-worker pool and the inline
    loop produce byte-identical cache, rot and counts."""
    import concurrent.futures as cf
    names = [f"Co{i:02d}" for i in range(12)]
    outcomes = {names[1]: ("empty", ""), names[4]: ("error", "http:403"), names[7]: ("ok", 3)}
    old = {names[4]: [_il_job(names[4])]}
    outs = []
    for argv, pool in ((["--workers", "1"], None), (["--workers", "3"], cf.ThreadPoolExecutor)):
        P = _refresh_sandbox(tmp_path / argv[1], monkeypatch, [(n,) for n in names], old, {}, outcomes)
        real = P.R.scrape_result

        def jitter(name, url, **kw):
            _time.sleep(0.01 * (hash(name) % 5))
            return real(name, url, **kw)
        monkeypatch.setattr(P.R, "scrape_result", jitter)
        assert P.R.run(argv, pool_cls=pool) == 0
        stamp = _json.loads(P.stages.read_text(encoding="utf-8"))["collect"]
        for k in ("minutes", "workers", "finished_at"):
            stamp.pop(k)
        outs.append((P.cache.read_bytes(), P.rot.read_bytes(), stamp))
    assert outs[0] == outs[1]


def test_refresh_pool_runs_a_module_level_worker_under_spawn():
    """The Linux/Windows proof: the real ProcessPoolExecutor with the `spawn` context and a
    picklable module-level worker; a worker that raises costs its company, not the run."""
    import refresh_scrape_cache as R
    from fake_scrape_worker import fake_worker
    rows = [{"company_name": n, "api_url": f"https://{n}.example"} for n in
            ("ok-1", "err-1", "empty-1", "boom-1", "slow-0.2", "ok-2")]
    t0 = _time.time()
    got = {r["name"]: r for r in R._scrape_all(rows, workers=2, worker=fake_worker)}
    assert set(got) == {r["company_name"] for r in rows}
    # recycling: more rows than one chunk of workers * tasks_per_worker — every row still
    # comes back (CPython's max_tasks_per_child hung the first full rehearsal at 4 x 25)
    many = [{"company_name": f"ok-{i}", "api_url": "https://x.example"} for i in range(11)]
    assert len(list(R._scrape_all(many, workers=2, worker=fake_worker, tasks_per_worker=2))) == 11
    assert got["ok-1"]["status"] == "ok" and got["err-1"]["error"] == "http:403"
    assert got["empty-1"]["status"] == "empty" and got["boom-1"]["error"] == "pool:RuntimeError"
    assert _time.time() - t0 < 60


