def test_run_py_holds_one_classifier_and_the_mail_gets_its_alarms():
    """The producer must be wired, not just the renderer (a blanked producer left the suite
    green in the registry lane's confirmation wave). Both classify sites, the summary, the
    alarms into `_stage_alarms`, the commit-then-save order, and `llm_calls` = attempts."""
    import inspect
    from pipeline import run as run_mod
    src = inspect.getsource(run_mod.run)
    # 2026-09-01 (`classifier` lane, disclosed): the constructor gained `cache_dates`, so the
    # call wraps. Collapsed to one line first, so a future re-wrap is not a failure -- the
    # claim is the WIRING, and the dates are half of it (docs/BACKLOG.md 541: without them
    # the seam picks a superseded verdict by sorting contract hashes).
    _flat = " ".join(src.split())
    assert ("clf = seniority.Classifier(use_llm=use_llm, llm_cache=llm_cache, "
            "cache_dates=llm_cache_dates)") in _flat
    # 2026-08-25 (`roles` lane, disclosed): both loops now judge through ONE seam,
    # roles.classify_grouped(candidates, clf, ...) — one call per ROLE, not per posting
    assert src.count("roles.classify_grouped(") == 2            # the ATS loop AND the aggregator loop
    assert "clf.classify(" not in src, "no loop may judge a posting behind the seam's back"
    assert "seniority.classify(" not in src
    assert 'print("  " + clf.summary(), flush=True)' in src
    assert "for _line in clf.alarms():" in src and "_stage_alarms.append(_line)" in src
    assert 'stats["llm_calls"] = clf.attempts' in src
    assert src.index("if clf.commit():") < src.index("st.save_llm_cache(llm_cache, run_date)") < src.index("company_intel.enrich_for_run(")
    assert "sum(paths.values()) != stats[\"israel_matched\"]" in src
    # 2026-08-31 (`classifier` lane, disclosed): the dataset backfill. Only the wiring is
    # pinned here — the behaviour has its own tests — because this is the half no unit test
    # can reach: an unscoped run is the only thing that executes it, and a hook that is
    # written but never called is exactly how a column stays empty for a week.
    assert "_cbf.backfill_verdicts(ledger, clf)" in src
    assert "class_backfill=_class_backfill" in src, "the map must reach record_run"
    # ...after BOTH classify sites (fresh roles judged first, so no backlog can take a call
    # slot the 48h window needed) and before the commit that persists what it bought
    assert src.rindex("roles.classify_grouped(") < src.index("_cbf.backfill_verdicts(") \
        < src.index('stats["llm_calls"] = clf.attempts')
    # ...never on a scoped run or with no seam, and a QUARANTINED morning writes nothing
    # into the dataset: `rec["class"]` is written once and never re-judged
    gate = src[src.index("_class_backfill = {}"):src.index("_cbf.backfill_verdicts(")]
    assert "if use_llm and not (only or limit):" in gate
    assert "clf.quarantine()" in src[src.index("_cbf.backfill_verdicts("):
                                     src.index('stats["llm_calls"] = clf.attempts')]


def test_save_llm_cache_writes_only_new_or_changed_rows(tmp_path):
    """Every row used to be upserted every run: all 247 said updated=2026-08-24."""
    from pipeline import store
    st = store.SeenStore(str(tmp_path / "t.db"))
    st.save_llm_cache({"a": True, "b": False}, "2026-08-01")
    st.save_llm_cache({"a": True, "b": True, "c": False}, "2026-08-02")
    rows = dict((k, u) for k, u in st.conn.execute("SELECT title_key, updated FROM llm_cache"))
    assert rows == {"a": "2026-08-01", "b": "2026-08-02", "c": "2026-08-02"}
    assert st.load_llm_cache() == {"a": True, "b": True, "c": False}


