def test_an_evidenced_display_name_names_the_cell_and_the_blob_never_the_join_key(monkeypatch):
    """2026-08-30: 8 of 161 published rows carried a URL slug as the employer's name
    (`withfaye` for Faye). The evidenced brand on the firmographics record now names the
    cell; anything short of evidence — absent, empty, whitespace, non-str, over-long —
    leaves every field byte-identical, because `company` is the join key for the ledger,
    the facts and the public CSV and only what the READER sees may change."""
    from pipeline import rolecard
    firmo = {"withfaye": {"display_name": "Faye"}}
    card = rolecard.build(_job(company="withfaye"), "2026-08-30", firmographics=firmo)
    assert card["company"] == "withfaye"                      # the join key never moves
    assert card["display_company"] == "Faye" and card["display_name"] == "Faye"
    assert " Faye" in card["blob"] and card["blob"].startswith("withfaye ")
    # no evidence, in every shape it arrives → the card equals the no-firmographics build
    plain = rolecard.build(_job(company="withfaye"), "2026-08-30")
    for rec in (None, {}, {"display_name": ""},
                {"display_name": "   "}, {"display_name": 42}, {"display_name": ["Faye"]},
                {"display_name": "x" * 61}):
        got = rolecard.build(_job(company="withfaye"), "2026-08-30",
                             firmographics={"withfaye": rec} if rec is not None else {})
        assert got == plain, rec
    # a record with facts but no display_name feeds the chips and nothing name-shaped
    facts_only = rolecard.build(_job(company="withfaye"), "2026-08-30",
                                firmographics={"withfaye": {"sector": "insurtech"}})
    assert facts_only["facts"] == ["insurtech"]
    assert (facts_only["display_company"], facts_only["display_name"], facts_only["blob"]) == \
           (plain["display_company"], plain["display_name"], plain["blob"])
    # a stray newline collapses, and bidi/zero-width controls are stripped, not rendered
    assert rolecard.display_name({"display_name": " Bounce\nAI "}, "finbounce") == "Bounce AI"
    assert rolecard.display_name({"display_name": "Fa\u202e\u200bye"}, "withfaye") == "Faye"
    assert rolecard.display_name(
        {"display_name": chr(0xFEFF) + "Fa" + chr(0x061C) + "ye" + chr(0xAD)}, "withfaye") == "Faye"
    # an LLM non-answer, entity-shaped text (GitHub renders `&rlm;` AFTER `_md_esc`),
    # a styled/homoglyph name (NFKC rewrites it) or a letterless string is junk, not a name
    for junk in ("N/A", "unknown", "null", "the company", "Acme &rlm; Ltd", "!!! ???", "\u2014",
                 chr(0xFF37) + chr(0xFF49) + chr(0xFF58),          # \uff46\uff55\uff4c\uff4c\uff57\uff49\uff44\uff54\uff48 "Wix"
                 "W" + chr(0x0456) + "x",                           # Cyrillic \u0456: identity {w,x}
                 "M" + chr(0x043E) + "nday.com",                    # Cyrillic \u043e mid-Latin (wave 2)
                 "Wi" + chr(0x0445)):                               # Cyrillic \u0445 keeps a 2-char token
        assert rolecard.display_name({"display_name": junk}, "withfaye") == "", junk
    # every degradation path carries the key the renderers read (a keyless card would
    # KeyError the whole product): the stub keeps the registry name, and a fill that
    # dies AFTER the derivation keeps the brand (it depends only on the record)
    from pipeline import jdtext, roleprofile
    monkeypatch.setattr(roleprofile, "extract", lambda *a, **k: (_ for _ in ()).throw(ValueError("x")))
    degraded = rolecard.build(_job(company="withfaye"), "2026-08-30", firmographics=firmo)
    assert degraded["display_name"] == "Faye" and "card degraded (ValueError)" in degraded["issues"]
    monkeypatch.setattr(jdtext, "_norm_location", lambda *a, **k: (_ for _ in ()).throw(RuntimeError("x")))
    stub = rolecard.build(_job(company="withfaye"), "2026-08-30", firmographics=firmo)
    assert stub["display_name"] == "" and stub["display_company"] == "withfaye"


def test_a_display_name_that_is_another_companys_identity_is_refused_at_the_source():
    """A record carrying ANOTHER employer's name is the wrong-facts failure shape
    (`Bounce`, 489) — rendered, it would impersonate that employer on every surface with
    only the tooltip carrying the truth, and the display-collision guard cannot catch it
    (per-product and case-sensitive). Refused in `display_name` itself, so finbounce
    renders `finbounce` in mail, board and archive alike until 487 parks the row."""
    from pipeline import rolecard
    firmo = {"finbounce": {"display_name": "Bounce AI"}, "Bounce AI": {"sector": "Fintech"}}
    cards = [rolecard.build(_job(company="finbounce", title="Data Analyst",
                                 url="https://f.io/jobs/1", mkey="f|1"), "2026-08-30",
                            firmographics=firmo),
             rolecard.build(_job(company="Bounce AI", title="BI Developer",
                                 url="https://b.ai/jobs/2", mkey="b|2"), "2026-08-30",
                            firmographics=firmo)]
    assert cards[0]["display_company"] == "finbounce" and cards[0]["display_name"] == ""
    assert not any(i.startswith("display-collision") for i in rolecard.cross_check(cards))
    # case does not launder the spoof: identity_key folds it — and neither does one
    # extra token ("Wix Analytics" is still Wix, either direction of the subset)
    assert rolecard.display_name({"display_name": "wix"}, "Acme Analytics",
                                 {"Acme Analytics": {}, "Wix": {}}) == ""
    assert rolecard.display_name({"display_name": "Wix Analytics"}, "Acme Analytics",
                                 {"Acme Analytics": {}, "Wix": {}}) == ""
    assert rolecard.display_name({"display_name": "WIX.com"}, "Acme Analytics",
                                 {"Acme Analytics": {}, "Wix": {}}) == ""
    # the brand is this employer's own other spelling: `Port` shown as `Port.io` must
    # not also print `(also listed as Port.io)` — the one live claimant shape
    ported = rolecard.build(_job(company="Port", url="https://p.io/1", mkey="p|1",
                                 _claimed_by=["Port.io"]), "2026-08-30",
                            firmographics={"Port": {"display_name": "Port.io"}})
    assert ported["display_company"] == "Port.io" and ported["also_listed_as"] == []
    unbranded = rolecard.build(_job(company="Port", url="https://p.io/1", mkey="p|1",
                                    _claimed_by=["Port.io"]), "2026-08-30")
    assert unbranded["also_listed_as"] == ["Port.io"]
    # one brand folding TWO registry rows onto one cell is a collision even when the raw
    # names fold too (a registry duplicate must not render as if it were one employer) —
    # while the same case-twin WITHOUT a brand stays silent, as always
    twin = {"helfy": {"display_name": "Helfy"}, "Helfy": {"display_name": "Helfy"}}
    merged = [rolecard.build(_job(company="helfy", url="https://h.io/1", mkey="h|1"),
                             "2026-08-30", firmographics=twin),
              rolecard.build(_job(company="Helfy", title="BI Developer",
                                  url="https://h.io/2", mkey="H|2"), "2026-08-30",
                             firmographics=twin)]
    assert "display-collision Helfy/helfy" in rolecard.cross_check(merged)
    assert all(c["display_name"] == "" and c["display_company"] == c["company"] for c in merged)
    silent = [rolecard.build(_job(company="helfy", url="https://h.io/1", mkey="h|1"), "2026-08-30"),
              rolecard.build(_job(company="Helfy", title="BI Developer",
                                  url="https://h.io/2", mkey="H|2"), "2026-08-30")]
    assert not any(i.startswith("display-collision") for i in rolecard.cross_check(silent))
    # the company's own identity under another casing is NOT a spoof (helfy/Helfy twin)
    assert rolecard.display_name({"display_name": "Helfy"}, "helfy",
                                 {"helfy": {}, "Helfy": {}}) == "Helfy"
    # two employers handed one fabricated brand still collide, revert — and the revert
    # clears display_name too, so every surface (heading, About, sort) reverts with the cell
    fab = {"Acme Data Ltd": {"display_name": "Nova"}, "Beta Analytics": {"display_name": "Nova"}}
    pair = [rolecard.build(_job(company="Acme Data Ltd", url="https://a.io/1", mkey="a|1"),
                           "2026-08-30", firmographics=fab),
            rolecard.build(_job(company="Beta Analytics", url="https://b.io/2", mkey="b|2"),
                           "2026-08-30", firmographics=fab)]
    issues = rolecard.cross_check(pair)
    assert "display-collision Acme Data Ltd/Beta Analytics" in issues
    assert [c["display_company"] for c in pair] == ["Acme Data Ltd", "Beta Analytics"]
    assert all(c["display_name"] == "" for c in pair)


def test_the_mail_heading_shows_the_evidenced_brand_and_survives_a_collision():
    """The 2026-08-30 mail rendered `### helfy` as an employer heading. The heading now
    reads the card's display_name — AFTER cross_check ran, which required building every
    block before emitting any (cross_check is not idempotent: its collision revert erases
    its own trigger, so it runs exactly once, above the headings)."""
    from pipeline import digest as D
    jobs = [{"company": "withfaye", "title": "Data Analyst", "location": "Tel Aviv",
             "url": "https://f.io/jobs/1", "posted_date": "2026-08-30", "description": "x"}]
    firmo = {"withfaye": {"display_name": "Faye"}}
    _, body = D.build_markdown(jobs, "2026-08-30", {"new": 1}, firmographics=firmo)
    assert "### Faye" in body and "### withfaye" not in body
    # a record without the field changes nothing
    _, plain = D.build_markdown(jobs, "2026-08-30", {"new": 1},
                                firmographics={"withfaye": {"sector": "insurtech"}})
    assert "### withfaye" in plain and "Faye" not in plain
    # one fabricated brand on two employers: the collision revert wins in the headings
    fab = {"Acme Data Ltd": {"display_name": "Nova"}, "Beta Analytics": {"display_name": "Nova"}}
    two = [{"company": "Acme Data Ltd", "title": "Data Analyst", "location": "Tel Aviv",
            "url": "https://a.io/1", "posted_date": "2026-08-30", "description": "x"},
           {"company": "Beta Analytics", "title": "BI Developer", "location": "Haifa",
            "url": "https://b.io/2", "posted_date": "2026-08-30", "description": "x"}]
    title2, body2 = D.build_markdown(two, "2026-08-30", {"new": 2}, firmographics=fab)
    assert "### Acme Data Ltd" in body2 and "### Beta Analytics" in body2
    assert "### Nova" not in body2 and "display-collision" in body2
    # the H1 still counts the bullets, and a company whose only card is mangled emits no
    # heading and does not crash the block loop
    blob = "Data Analyst Tel Aviv Full-time Apply now " * 5
    mangled = two + [{"company": "Blobco", "title": blob, "location": "Haifa",
                      "url": "https://c.io/3", "posted_date": "2026-08-30", "description": "x"}]
    t3, b3 = D.build_markdown(mangled, "2026-08-30", {"new": 3}, firmographics=fab)
    assert t3.startswith("🎯 2 ") and "### Blobco" not in b3 and D._subject_vs_body(t3, b3) == ""
    # ...and a NEWCO company whose only card is mangled is not COUNTED either — the
    # section heading counts emitted blocks, not the input list
    mixed = two + [{"company": "Blobco", "title": blob, "location": "Haifa",
                    "url": "https://c.io/3", "posted_date": "", "description": "x",
                    "_new_company": True},
                   {"company": "Zeta", "title": "Data Analyst", "location": "Haifa",
                    "url": "https://z.io/4", "posted_date": "", "description": "x",
                    "_new_company": True}]
    t4, b4 = D.build_markdown(mixed, "2026-08-30", {"new": 4}, firmographics=fab)
    assert "## Newly covered companies (1)" in b4 and "### Zeta" in b4 and "### Blobco" not in b4
    assert t4.startswith("🎯 3 ") and D._subject_vs_body(t4, b4) == ""


def test_the_board_searches_sorts_and_says_about_by_the_brand_but_keys_on_the_registry_name():
    """The cell showed `withfaye` where the employer is Faye — and a cell that says Faye
    must sort under F, say `About Faye`, and be findable by typing "faye", while the
    tooltip and the data joins keep the registry name."""
    from pipeline import digest as D
    jobs = [{"company": "withfaye", "title": "Data Analyst", "location": "Tel Aviv",
             "url": "https://f.io/jobs/1", "posted_date": "2026-08-30", "description": "x"}]
    info = {"withfaye": "Travel-insurance platform for consumers."}
    html = D.build_board_html(jobs, "2026-08-30", {"companies_scanned": 1}, info,
                              firmographics={"withfaye": {"display_name": "Faye"}})
    assert ">Faye</td>" in html and 'title="withfaye"' in html
    assert 'data-company="faye"' in html and "About Faye" in html
    assert "faye" in html.split('data-blob="', 1)[1].split('"', 1)[0]
    plain = D.build_board_html(jobs, "2026-08-30", {"companies_scanned": 1}, info,
                               firmographics={"withfaye": {"sector": "insurtech"}})
    assert 'data-company="withfaye"' in plain and "About withfaye" in plain and "Faye" not in plain


def test_the_boards_brand_verdict_reaches_the_mail_that_renders_last():
    """A fabricated brand on two employers collides on the BOARD and both revert — but
    the mail's 48h list is a subset, its own cross_check may hold only one of the pair,
    and it would print the fabricated `### Nova` under an audit line that says the raw
    names. The board renders first; its demotion travels (`display_demoted` on the
    shared render report) so one morning shows one verdict on every surface."""
    from pipeline import digest as D
    fab = {"Acme Data Ltd": {"display_name": "Nova"}, "Beta Analytics": {"display_name": "Nova"}}
    j1 = {"company": "Acme Data Ltd", "title": "Data Analyst", "location": "Tel Aviv",
          "url": "https://a.io/1", "posted_date": "2026-08-31", "description": "x"}
    j2 = {"company": "Beta Analytics", "title": "BI Developer", "location": "Haifa",
          "url": "https://b.io/2", "posted_date": "2026-08-31", "description": "x"}
    out = D.render_all([j1], [j1, j2], [], "2026-08-31", {"new": 1}, firmographics=fab)
    assert "### Nova" not in out["md_body"] and "### Acme Data Ltd" in out["md_body"]
    assert "display-collision Acme Data Ltd/Beta Analytics" in out["md_body"]
    # the wiring is live end to end: an unchallenged brand still reaches the mail
    solo = D.render_all([j1], [j1], [], "2026-08-31", {"new": 1},
                        firmographics={"Acme Data Ltd": {"display_name": "Nova"}})
    assert "### Nova" in solo["md_body"] and "### Acme Data Ltd" not in solo["md_body"]


# ======================================================================================
# lane: infra (2026-08-25) — the delivery path: persist_state.py, the merges, the failure
# notice, the run's alarms. Every guard is a proven loss or a shipped bug (the session
# record: docs/sessions/2026-08-24-infra.md).
# ======================================================================================
import shutil as _shutil
import subprocess as _sp

_REPO = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
_PERSIST = os.path.join(_REPO, "persist_state.py")
_GIT = _shutil.which("git")
# The git-backed guards below spawn ~40 git/python processes each (12 of them, ~40-100 s a
# pass). `tools/mutate.py` runs the WHOLE suite once per mutation (108) from a `git archive`
# export -- an hour of proving nothing about a registry mutation, which timed the gate out
# on 2026-08-25. They run only from a real checkout, i.e. `pytest` and `tests.yml`'s guard.
_needs_git = pytest.mark.skipif(
    _GIT is None or not os.path.isdir(os.path.join(_REPO, ".git")),
    reason="needs git and a real checkout (the mutation harness runs from a git archive)")


def _g(cwd, *args, check=True):
    p = _sp.run(["git", "-c", "core.autocrlf=false", "-c", "user.name=t", "-c", "user.email=t@x",
                 "-c", "commit.gpgsign=false", *args], cwd=cwd, capture_output=True)
    if check and p.returncode != 0:
        raise AssertionError(f"git {args}: {p.stderr.decode('utf-8', 'replace')}")
    return p.stdout.decode("utf-8", "replace")


def _repo_pair(tmp_path, seed):
    """A bare origin and two clones: A is "another workflow", B is the runner under test."""
    origin = tmp_path / "origin.git"
    _g(tmp_path, "init", "-q", "--bare", str(origin))
    _g(str(origin), "symbolic-ref", "HEAD", "refs/heads/master")
    a, b = tmp_path / "A", tmp_path / "B"
    _g(tmp_path, "clone", "-q", str(origin), str(a))
    for rel, content in seed.items():
        (a / rel).parent.mkdir(parents=True, exist_ok=True)
        (a / rel).write_bytes(content if isinstance(content, bytes) else content.encode("utf-8"))
    _g(str(a), "add", "-A")
    _g(str(a), "commit", "-q", "-m", "seed")
    _g(str(a), "push", "-q", "origin", "HEAD:master")
    _g(tmp_path, "clone", "-q", str(origin), str(b))
    return origin, a, b


def _persist(b, *own, msg="run", gate="", extra=()):
    return _sp.run([sys.executable, _PERSIST, "commit", "--cwd", str(b), "--as", "test-bot", "-m", msg,
                    "--sleep", "0", "--gate", gate, "--branch", "master", *extra, "--own", *own],
                   capture_output=True, cwd=_REPO)


def _origin(origin, path):
    p = _sp.run(["git", "show", f"master:{path}"], cwd=str(origin), capture_output=True)
    return p.stdout.decode("utf-8") if p.returncode == 0 else None


def _commit_other(a, rel, content, msg="other"):
    (a / rel).parent.mkdir(parents=True, exist_ok=True)
    (a / rel).write_text(content, encoding="utf-8")
    _g(str(a), "add", "-A"); _g(str(a), "commit", "-q", "-m", msg); _g(str(a), "push", "-q", "origin", "HEAD:master")


_STAMPS = json.dumps({"collect": {"date": "2026-08-24", "finished_at": "2026-08-24T01:00:00+00:00"},
                      "expand": {"date": "2026-08-24", "finished_at": "2026-08-24T10:17:01+00:00"}}, indent=1)


@_needs_git
def test_persist_merges_stage_stamps_per_key_on_a_conflict_day(tmp_path):
    """The 0b41823 case: listing-hunt stamped `repair` at 22:12; auto-expand, checked out at
    20:00, hit a push conflict at 23:40 and restored its own copy of pipeline_stages.json
    wholesale, deleting the key — so the mail read `repair: never run`. Per key now."""
    origin, a, b = _repo_pair(tmp_path, {"cloud_state/pipeline_stages.json": _STAMPS, "x.txt": "x"})
    # the other workflow lands `repair` after B's checkout
    later = json.loads(_STAMPS); later["repair"] = {"date": "2026-08-24", "finished_at": "2026-08-24T22:12:18+00:00"}
    _commit_other(a, "cloud_state/pipeline_stages.json", json.dumps(later, indent=1), "listing-hunt")
    # B stamps `expand` from its older checkout
    mine = json.loads(_STAMPS); mine["expand"] = {"date": "2026-08-24", "finished_at": "2026-08-24T23:40:42+00:00"}
    (b / "cloud_state" / "pipeline_stages.json").write_text(json.dumps(mine, indent=1), encoding="utf-8")
    r = _persist(b, "cloud_state/pipeline_stages.json", msg="auto-expand")
    assert r.returncode == 0, r.stdout.decode() + r.stderr.decode()
    got = json.loads(_origin(origin, "cloud_state/pipeline_stages.json"))
    assert got["repair"]["finished_at"] == "2026-08-24T22:12:18+00:00", got
    assert got["expand"]["finished_at"] == "2026-08-24T23:40:42+00:00", got
    assert "row-merged" in _g(str(a), "log", "--oneline", "origin/master", "-1") or \
        "(row-merged)" in _g(str(b), "log", "--oneline", "-1")


def test_stage_stamp_strategy_takes_the_newer_finish_when_both_sides_stamped():
    import persist_state as P
    base = json.dumps({"collect": {"finished_at": "2026-08-24T01:00:00+00:00"}}).encode()
    ours = json.dumps({"collect": {"finished_at": "2026-08-25T01:00:00+00:00"}}).encode()
    theirs = json.dumps({"collect": {"finished_at": "2026-08-25T02:00:00+00:00"}, "repair": {"finished_at": "x"}}).encode()
    out = json.loads(P.s_stage_stamps(base, ours, theirs))
    assert out["collect"]["finished_at"] == "2026-08-25T02:00:00+00:00" and "repair" in out
    out = json.loads(P.s_stage_stamps(base, theirs, ours))     # symmetric: the newer wins either way
    assert out["collect"]["finished_at"] == "2026-08-25T02:00:00+00:00"


def test_company_dict_strategy_honours_deletions_and_never_writes_a_corrupt_side_back():
    import persist_state as P
    base = json.dumps({"A": [1], "F": [6]}).encode()
    ours = json.dumps({"A": [1], "D": [4]}).encode()            # we dropped F, added D
    theirs = json.dumps({"A": [1], "F": [6], "E": [5]}).encode()
    out = json.loads(P.s_company_dict(base, ours, theirs))
    assert "F" not in out and out["D"] == [4] and out["E"] == [5]
    assert P.s_company_dict(base, b"{not json", theirs) == theirs, "a corrupt ours yields to origin"
    assert P.s_company_dict(base, ours, b"[]") == ours, "a corrupt origin yields to ours"


def test_the_delivery_cutoff_follows_the_trigger_not_the_clock():
    """`deliver` defers a digest written past the relay's last POLL, because no poller would
    see it. That reason exists only while a poll is the relay's only reader. Once the digest
    can hand the relay an event, the deadline must move with it -- otherwise the change ships
    and the system keeps withholding mail it can now deliver.

    The case that makes it concrete: on 2026-08-27 the 05:00 cron was dispatched at **16:18**,
    `deliver` refused it at the 10:17 deadline, and the operator got **no mail at all that
    day** -- `digests/latest.md` was never written. At 23:39 that same run delivers.

    `daily-digest.yml` therefore sets `RELAY_LAST_POLL_UTC` from whether the deploy key exists,
    and 23:39 is 23:59 less `DELIVER_MARGIN_MIN`, so the arithmetic stays inside the UTC day."""
    import persist_state as P
    late, normal, midnight = 16 * 60 + 18, 7 * 60 + 8, 23 * 60 + 20
    assert P.cutoff_overshoot(late, last_poll="10:17") > 0, "the poll-only deadline defers 16:18"
    assert P.cutoff_overshoot(late, last_poll="23:39") < 0, "the event deadline delivers it"
    for poll in ("10:17", "23:39"):
        assert P.cutoff_overshoot(normal, last_poll=poll) < 0, "the ordinary morning always ships"
    assert P.cutoff_overshoot(midnight, last_poll="23:39") > 0, \
        "23:39 still refuses a delivery that would spill past midnight -- it is a deadline, not a removal"
    dd = open(os.path.join(_REPO, ".github", "workflows", "daily-digest.yml"), encoding="utf-8").read()
    assert "RELAY_LAST_POLL_UTC: ${{ secrets.INBOX_DEPLOY_KEY != '' && '23:39' || '10:17' }}" in dd, \
        "the deadline must be conditional on the event path existing, not hardcoded either way"


def test_no_workflow_expression_has_a_falsy_true_branch():
    """GitHub's `${{ cond && A || B }}` is not a ternary: `&&` yields A only when A is TRUTHY,
    so `cond && '' || '1'` returns **'1' for every input** and whatever the expression was
    switching silently never switches.

    This shipped into four steps on 2026-08-28 as the OFF switch for a paid Bright Data rung --
    an operator setting `BD_PAID_RUNGS=off` would have kept buying credits every night, and the
    same commit got it right in `scrape-refresh.yml` (`&& 'off' || 'on'`), so the two forms sat
    side by side looking alike and behaving oppositely. Caught by an adversarial pass before the
    push. This guard is the class, not the instance: a `&&` whose true branch is an empty or
    zero literal is always a bug."""
    bad = []
    for w in sorted(glob.glob(os.path.join(_REPO, ".github", "workflows", "*.yml"))):
        for n, line in enumerate(open(w, encoding="utf-8"), 1):
            for m in re.finditer(r"\$\{\{[^}]*?&&\s*('' |''\s*\|\||\"\"\s*\|\||'0'\s*\|\|)", line):
                bad.append(f"{os.path.basename(w)}:{n}: {line.strip()[:110]}")
    assert not bad, ("a GitHub expression whose `&&` branch is falsy always yields the `||` "
                     "branch:\n  " + "\n  ".join(bad))


def _mutate_module_for_tests():
    import importlib.util
    spec = importlib.util.spec_from_file_location(
        "_mutate_under_test", os.path.join(_REPO, "tools", "mutate.py"))
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def test_the_merge_does_not_resurrect_a_key_the_origin_retired():
    """The two deletion arms were asymmetric: OUR deletion stood, ORIGIN's was undone. So any
    process holding an older checkout re-added every key origin had retired since it was
    checked out, and a retirement could never stay retired.

    Measured 2026-08-30 (registry, BACKLOG 458): 44 names retired by `1ce0db5` and `a07e743`
    between 00:28 and 00:54 were back in `research_companies.json` at 00:41, put there by
    `5ccd60e` -- the listing-hunt cron's OWN state commit, checked out before the retirements.

    The rescue arm still fires for the case it was written for: an origin file that is empty
    or unreadable is not a deletion of everything."""
    import merge_json_cache as mjc
    base = {"a": 1, "keep": 2}
    ours = {"a": 1, "keep": 2}                      # we touched neither
    theirs = {"a": 1}                               # origin retired `keep`
    out, _changed, kept = mjc.merge(base, ours, theirs)
    assert "keep" not in out, "origin's retirement of a key we did not touch must stand"
    assert kept == 0
    # ours still wins when WE moved it
    out2, _c2, _k2 = mjc.merge(base, {"a": 1, "keep": 99}, theirs)
    assert out2["keep"] == 99, "a key this run actually wrote is not origin's to retire"
    # and an empty/unreadable origin is not a mass deletion
    out3, _c3, kept3 = mjc.merge(base, ours, {})
    assert out3 == {"a": 1, "keep": 2} and kept3 == 2, "an empty origin deletes nothing"


def test_a_broken_origin_is_not_a_deletion_of_a_quarter_of_the_cache():
    """`s_company_dict` refuses a run that dropped a quarter of the keys from OUR side
    (CLAUDE.md rule 2: that is a broken run, not a measurement). Nothing refused it from
    ORIGIN's side — the unconditional rescue arm was providing that protection by accident,
    and `_keyed_list` (`research_companies.json`, `discovered_cache.json`) has no other guard
    at all. Honouring origin's deletions (458) removes the accident, so the rule is now
    explicit: a few retirements stand, a truncated origin does not.

    Without it, one workflow committing a half-written cache would permanently delete every
    key the other side still held, with no alarm anywhere."""
    import merge_json_cache as mjc
    base = {"k%d" % i: i for i in range(40)}
    ours = dict(base)                                  # we touched nothing
    theirs = {k: v for k, v in base.items() if v < 25}  # origin lost 15 of 40 (37%)
    out, _c, kept = mjc.merge(base, ours, theirs)
    assert out == base and kept == 15, "a broken origin keeps our copies"
    # a handful of genuine retirements still stand
    few = {k: v for k, v in base.items() if v >= 5}     # origin retired 5 of 40 (12%)
    out2, _c2, kept2 = mjc.merge(base, ours, few)
    assert kept2 == 0 and all("k%d" % i not in out2 for i in range(5)), \
        "an ordinary retirement is not a broken run"
    # the guard needs a cache worth measuring: 3 of 4 gone is not a sample
    tiny = {"a": 1, "b": 2, "c": 3, "d": 4}
    out3, _c3, _k3 = mjc.merge(tiny, dict(tiny), {"a": 1})
    assert out3 == {"a": 1}, "below 20 keys the share is noise; origin's deletion stands"


import inspect as _j6_inspect
import textwrap as _j6_textwrap
from types import SimpleNamespace as _j6_NS2


def test_a_shard_past_its_wall_ceiling_says_so_on_its_own_run_page(capsys, monkeypatch):
    """"Past ~1,800 s, add a matrix entry, never the budget" was a workflow comment and a
    morning-check row, and nothing read either: every shard had been over the ceiling for
    days (2,014-2,317 s on run 33406913948, the green one) and two were killed at 40 min
    before anyone looked. The ceiling now announces itself while the shard is still green.

    It cannot be a job-level `if:` -- `test_every_long_tests_step_has_a_named_budget_below_
    its_job_timeout` forbids `if:` in this workflow -- so it lives in the harness.

    Run for real against the emitting block, rather than grepping for its text: a test that
    asserts a string is in a file passes just as well when the code around it is inert."""
    M = _mutate_module_for_tests()
    src = _j6_inspect.getsource(M.main)
    start = src.index("    try:\n        warn_at")
    block = src[start:src.index("flush=True)", src.index("(BACKLOG 195/476)")) + len("flush=True)")]

    def _emit(wall, shard, env=None):
        ns = {"os": os, "print": print, "wall": wall,
              "a": _j6_NS2(shard=shard), "__builtins__": __builtins__}
        for k, v in (env or {}).items():
            monkeypatch.setenv(k, v)
        exec(_j6_textwrap.dedent(block), ns)              # noqa: S102 - the shipped block
        return capsys.readouterr().out

    monkeypatch.delenv("MUTATE_WALL_WARN", raising=False)
    assert "::warning::mutation shard walled 2317 s" in _emit(2317.0, "1/5")
    assert "add a matrix entry" in _emit(2317.0, "1/5")
    assert _emit(1799.0, "1/5") == "", "under the ceiling is silent"
    # an unsharded local `--all` is the whole catalogue and is over by construction
    assert _emit(9999.0, "") == "", "only a shard is told to add a matrix entry"
    assert _emit(9999.0, "1/5", {"MUTATE_WALL_WARN": "0"}) == "", "0 disables"
    assert "walled 9999 s" in _emit(9999.0, "1/5", {"MUTATE_WALL_WARN": "60"}), "override"
    # a malformed override must not cost a 35-minute run its verdict
    assert "walled 9999 s" in _emit(9999.0, "1/5", {"MUTATE_WALL_WARN": "banana"})


def test_every_catalogue_anchor_test_stands_down_inside_a_mutant():
    """An anchor test asserts that each mutation record's `find` still occurs in its file.
    Apply any mutant and that string is gone by construction, so the anchor goes red under
    EVERY mutant of that catalogue -- and `tools/mutate.py` scores each one `killed`, by the
    one test whose job is to notice the catalogue drifting rather than by anything that
    exercises the code. The shard's number then means nothing.

    Measured 2026-08-31 (BACKLOG 540): `ci-cached-board-titles-never-read` reported
    `killed / test_every_company_intel_mutat (direct)` -- `direct`, not `static`, because
    `mutate._classify_killer`'s `_STATIC_MARKERS` looks for `inspect.getsource` / `ast.parse`
    / `ast.walk` and this anchor reads its file with `open(...).read()`. With the anchor
    deselected the same mutant SURVIVED the whole suite (`176 passed, 1 deselected`). What it
    hid: `_cached_board_titles`'s call site had no behavioural guard at all.

    The escape already existed for one catalogue and not the other, which is why this is a
    rule and not a second fix. Every anchor stands down under `AJIL_MUTANT` (set by
    `tools/mutate.py` and `tools/guard_kill.py`) so the mutant is judged by behaviour or
    honestly survives.

    Rejected, with the number: teaching `_STATIC_MARKERS` about `open().read()` instead --
    45 currently-`direct` tests would reclassify as `static` (most read YAML or Markdown, not
    the mutated module), every record killed solely by one of them would flip from `killed`
    to FAIL, and a static-only kill stops short-circuiting the subset, adding a full-suite run
    per record to a gate already over its wall budget."""
    import ast
    if os.environ.get("AJIL_MUTANT"):
        # this test reads test files, which guard-kill does not revert and mutate does not
        # mutate: inside a mutant it can only ever pass, so it stands down with the rest
        pytest.skip("the mutant's source is intentionally not HEAD's")
    def _anchors(src):
        """(name -> body) for every function that reads a catalogue and counts a `find`."""
        out = {}
        for fn in [n for n in ast.walk(ast.parse(src)) if isinstance(n, ast.FunctionDef)]:
            body = ast.unparse(fn)
            if "mutations.json" in body and ".count(" in body \
                    and "'find'" in body.replace('"find"', "'find'"):
                out[fn.name] = body
        return out

    unguarded = []
    for path in sorted(glob.glob(os.path.join(_REPO, "tests", "test_*.py"))):
        src = open(path, encoding="utf-8").read()
        anchors = _anchors(src)
        for fn in [n for n in ast.walk(ast.parse(src)) if isinstance(n, ast.FunctionDef)]:
            if not fn.name.startswith("test_"):
                continue                   # a helper is covered by the test that calls it
            body = ast.unparse(fn)
            # the counting may sit in a same-file helper (test_registry.py does exactly that),
            # so a test anchors the catalogue if its own body counts or it calls one that does
            reached = dict(anchors)
            reached.pop(fn.name, None)
            if not (fn.name in anchors or any(h + "(" in body for h in reached)):
                continue
            if "AJIL_MUTANT" not in body:
                unguarded.append("%s::%s" % (os.path.basename(path), fn.name))
    assert not unguarded, (
        "catalogue anchor test(s) with no AJIL_MUTANT stand-down: %s. Each one reddens under "
        "every mutant of its catalogue and scores it `killed` without exercising a line of "
        "the code (BACKLOG 540). Copy the three-line skip from "
        "tests/test_registry.py::test_no_mutation_record_goes_stale_unnoticed." % unguarded)


def test_the_mutation_shards_partition_the_whole_catalogue():
    """The mutation gate is sharded across a matrix, and a shard split that quietly stops
    covering a record is the exact silent-exclusion shape this repo keeps paying for: every
    shard would go green while nothing ran the mutations that matter.

    By RECORD since 2026-08-30 (BACKLOG 476/491): the first split bin-packed the `M<n>`
    classes, and `M1-gate-removal` is one class of 89 records, so shard 0 was killed at its
    40-minute budget on every push while "add a shard" changed nothing. The split is now
    `tools/mutate.shard` -- sorted ids, every N-th -- and this runs THAT function over the
    real catalogue with the matrix `tests.yml` declares, and asserts the shards cover every
    record exactly once, none empty, within one record of each other, and that the workflow
    hands the matrix value to the selector unchanged (0-based, `$SHARD/$SHARDS`).

    Context: the catalogue grew 105 -> 204 records between 2026-08-24 and 2026-08-28 while
    `timeout-minutes: 45` stood still, and the job was CANCELLED on 40 consecutive pushes
    (BACKLOG 195). A cancelled gate names no surviving mutant at all."""
    wf = open(os.path.join(_REPO, ".github", "workflows", "tests.yml"), encoding="utf-8").read()
    n = int(re.search(r'SHARDS:\s*"(\d+)"', wf).group(1))
    ids = re.search(r"shard:\s*\[([^\]]+)\]", wf).group(1)
    assert sorted(int(x) for x in ids.split(",")) == list(range(n)), \
        f"the matrix is {ids} but SHARDS says {n} -- a shard would never run"
    assert re.search(r'python -u tools/mutate\.py --all --shard "\$SHARD/\$SHARDS"', wf), \
        "the step must hand the matrix value to the selector unchanged, 0-based"
    import io
    import json
    M = _mutate_module_for_tests()
    muts = M._load([os.path.join(_REPO, "tests", "mutations.json")])
    seen, sizes = [], []
    for i in range(n):
        got = [m["id"] for m in M.shard(muts, f"{i}/{n}")]
        assert got, f"shard {i} of {n} drew no records: some mutations would run nowhere"
        seen += got
        sizes.append(len(got))
    assert sorted(seen) == sorted(m["id"] for m in muts), \
        f"the {n} shards cover {len(seen)} records, the catalogue has {len(muts)}"
    assert len(seen) == len(set(seen)), "a record runs in two shards"
    assert max(sizes) - min(sizes) <= 1, f"the stride is not balanced: {sizes}"
    # over IDS, not file order (wave A, 2026-08-30): a catalogue-order stride still partitions,
    # so nothing above would notice -- and then shard membership depends on merge order
    first = [m["id"] for m in M.shard(muts, f"0/{n}")]
    assert first == sorted(m["id"] for m in muts)[::n], "the stride must be over ids, not file order"
    for bad in (f"{n}/{n}", "0/0", "1", "-1/2", "a/b"):
        with pytest.raises(ValueError):
            M.shard(muts, bad)


def test_the_bright_data_ceiling_changes_itself_on_2026_09_01():
    """The operator's rule of 2026-08-28, pinned on BOTH sides of the boundary so it needs no
    one to remember it. BACKLOG 192 said 4,500 from September and 335 quoted 5,000; the rule
    that settled them is unlimited through August, 5,000 from 2026-09-01.

    This guard is the whole reason the date may live in code: a dated constant nobody verifies
    is exactly the confidently-wrong document this repo punishes hardest."""
    from pipeline import bd_budget as B
    os.environ.pop("BD_MONTHLY_BUDGET", None)
    assert B.ceiling(dt.date(2026, 8, 31)) == 0, "unlimited on the last day of August"
    assert B.ceiling(dt.date(2026, 9, 1)) == 5000, "the ceiling binds on 2026-09-01"
    assert B.ceiling(dt.date(2027, 3, 4)) == 5000, "and stays bound"


def test_an_unreadable_bright_data_balance_still_lets_the_run_spend(monkeypatch):
    """Fail OPEN, on purpose. A silent zero from a source that used to produce is the worst
    failure mode in this repo, and the opposite mistake costs a few dollars. The bound that
    does not depend on the network is `bd_rescue.BD_RUN_CAP`, not this."""
    from pipeline import bd_budget as B
    monkeypatch.setattr(B, "spent_this_month", lambda today=None: (None, None))
    for day in (dt.date(2026, 8, 28), dt.date(2026, 9, 15)):
        may, line = B.verdict(day)
        assert may, f"{day}: an unreadable balance must not throttle"
        assert "UNREADABLE" in line or "unknown" in line, line
    monkeypatch.setattr(B, "spent_this_month", lambda today=None: (6193, {}))
    may, line = B.verdict(dt.date(2026, 9, 15))
    assert not may and "CEILING" in line, line
    assert B.verdict(dt.date(2026, 8, 28))[0], "over 5,000 still spends in August: no ceiling yet"


def test_the_shared_bright_data_run_cap_is_off_unless_a_workflow_asks_for_it():
    """`BD_RUN_CAP` bounds what one PROCESS spends at the chokepoint ten of the thirteen spend
    paths share. UNSET means no cap, so a lane that does not name it sees exactly the behaviour
    it saw before this existed -- the cap may not be a silent change to anybody else's tool.

    **`0` means buy nothing, and `None` means no cap.** The first version had `0` mean UNLIMITED,
    which is the wrong way round for the one number an operator reaches for when they want spend
    to stop; an adversarial pass on 2026-08-28 pointed out that this very guard *codified* the
    hazard by asserting `("junk", 0)` and `("-5", 0)`. A value that will not parse (`1,000`,
    `1e3`) is a typo, not a licence: it warns and buys nothing rather than removing the cap it
    was meant to set.

    A capped call reports `bd-capped`, the same string jdfill.Unlocker uses -- but note
    `unlock()` discards the reason, so only a caller reading `LAST["error"]` can tell a refusal
    from a failure (BACKLOG 110)."""
    import bd_rescue as B
    for val, want in ((None, None), ("", None), ("   ", None),      # unset -> no cap
                      ("0", 0), ("-5", 0),                          # explicit stop
                      ("junk", 0), ("1,000", 0),                    # a typo never means unlimited
                      ("120", 120)):
        if val is None:
            os.environ.pop("BD_RUN_CAP", None)
        else:
            os.environ["BD_RUN_CAP"] = val
        assert B.run_cap() == want, f"BD_RUN_CAP={val!r}"
    os.environ["BD_RUN_CAP"] = "2"
    B.SPENT.update(n=2, capped=False)
    try:
        assert B.unlock_status("https://example.com/x") == ("", "bd-capped")
        assert B.LAST["error"] == "bd-capped"
    finally:
        B.SPENT.update(n=0, capped=False)
        os.environ.pop("BD_RUN_CAP", None)


def test_bright_data_spend_is_written_somewhere_a_later_run_can_read(tmp_path, monkeypatch):
    """The run page is not a durable channel and neither is the mail. `[bd-spend]` goes to the
    step log and `$GITHUB_STEP_SUMMARY`, both of which vanish when the run record is deleted --
    and this repo deletes run records on purpose (`CLAUDE.local.md` §3), which is exactly how
    the only evidence of a `pipeline: failure` was destroyed on 2026-08-28.

    So the number is also committed, one line per process, merged for every workflow by
    `persist_state` without any workflow naming it in `--own`."""
    import bd_rescue as B, persist_state as P
    monkeypatch.setattr(B, "ROOT", str(tmp_path))
    monkeypatch.setenv("BD_RUN_CAP", "2")
    monkeypatch.delenv("GITHUB_STEP_SUMMARY", raising=False)
    for n, capped in ((2, True), (5, False)):
        B.SPENT.update(n=n, capped=capped)
        B._report_spend()
    B.SPENT.update(n=0, capped=False)
    lines = (tmp_path / "cloud_state" / "bd_spend.jsonl").read_text(encoding="utf-8").splitlines()
    assert len(lines) == 2, lines
    recs = [json.loads(x) for x in lines]           # one record per PHYSICAL line, like the gate
    assert [r["credits"] for r in recs] == [2, 5]
    assert recs[0]["capped"] is True and recs[0]["cap"] == 2
    assert P.strategy_for(P.BD_SPEND_LOG)[0] is P.s_jsonl_union, \
        "many processes append to it, so the union IS the merge"


def test_the_cache_shrink_alarm_fires_on_every_regression_it_was_built_from():
    """The three nights that lost boards in silence: 16/279 (2026-08-28), 16/221 (08-27) and
    24/243 (08-26). Nothing saw them -- refresh_scrape_cache's abort needs >20%, s_company_dict's
    guard needs >25% AND only runs on a conflict, check_invariants never opens the cache.

    The other half of the assertion is the one that matters more: the alarm must stay QUIET for
    the 1-4 key deletions a parked row or an alias merge makes, because an alarm that cries wolf
    is an alarm nobody reads. Thresholds are PROVISIONAL on n=3 (docs/BACKLOG.md 356)."""
    import persist_state as P
    for lost, before in ((16, 279), (16, 221), (24, 243)):
        assert P.shrank({"lost": lost, "before": before}), f"{lost}/{before} must alarm"
    for lost, before in ((4, 243), (2, 20), (9, 100), (10, 500), (0, 279)):
        assert not P.shrank({"lost": lost, "before": before}), f"{lost}/{before} must stay quiet"


def test_a_cache_this_run_created_does_not_read_as_a_total_loss(tmp_path, monkeypatch):
    """`key_deltas` compares the tree against the checkout. A cache with no version at base --
    its first ever run, or a path only some workflows own -- has nothing to compare against, and
    reporting `N -> 0` there would put a false 100% loss on the run page every time a new keyed
    cache is introduced. Absent, or not a dict, yields NO record rather than a wrong one."""
    import persist_state as P
    (tmp_path / "scraped_cache.json").write_bytes(json.dumps({"A": [1], "B": [2]}).encode())
    assert P.key_deltas(["scraped_cache.json"], "HEAD", str(tmp_path)) == [], "no base -> no claim"
    monkeypatch.setattr(P, "git_show", lambda rev, path, cwd=None: b"[]")   # a list, not a cache
    assert P.key_deltas(["scraped_cache.json"], "HEAD", str(tmp_path)) == []


def test_the_persist_log_is_one_json_record_per_line(tmp_path):
    """`_dumps` indents, and an indented record is several lines none of which is valid JSON on
    its own -- `run_gates` parses a .jsonl line by line, so the first version of this failed the
    gate on the very log it exists to keep. Found by hand on 2026-08-28, before the push."""
    import persist_state as P
    d = [{"path": "scraped_cache.json", "before": 279, "after": 263, "lost": 16,
          "gained": 0, "names": []}]
    P.report_deltas(d, str(tmp_path), "one")
    P.report_deltas(d, str(tmp_path), "two")
    raw = (tmp_path / "cloud_state" / "persist_log.jsonl").read_bytes()
    lines = [x for x in raw.splitlines() if x.strip()]
    assert len(lines) == 2, raw
    for ln in lines:                       # exactly what _gate_json does to a .jsonl
        assert json.loads(ln.decode("utf-8"))["paths"][0]["lost"] == 16


def test_the_persist_log_union_keeps_every_writers_line():
    """Many workflows append to one log, so there is no conflict to resolve -- two runs that
    appended different lines both said something true. The union IS the merge, which is why this
    log needs no single-writer claim. A replayed rebase must not double a line, and a foreign
    line must not raise and lose the whole log."""
    import persist_state as P
    a = b'{"at":"2026-08-28T01:00:00Z","msg":"scrape"}\n'
    b = b'{"at":"2026-08-28T02:00:00Z","msg":"hunt"}\n'
    out = P.s_jsonl_union(b"", a, b).splitlines()
    assert out == [a.strip(), b.strip()], "both writers, oldest first"
    assert P.s_jsonl_union(a, a, a).splitlines() == [a.strip()], "a replayed append is not doubled"
    assert P.s_jsonl_union(None, None, None) == b"", "nothing in, nothing out"
    assert b"not json" in P.s_jsonl_union(b"", b"not json\n", b), "a foreign line survives"
    many = b"\n".join(b'{"at":"%03d"}' % i for i in range(P.PERSIST_LOG_MAX + 50))
    assert len(P.s_jsonl_union(b"", many, b"").splitlines()) == P.PERSIST_LOG_MAX, "capped"


def test_keyed_list_strategy_merges_discovery_lists_by_company_and_title():
    import persist_state as P
    j = lambda c, t, d="": {"company": c, "title": t, "posted_date": d}  # noqa: E731
    base = json.dumps([j("Acme", "Analyst", "old"), j("Old", "Gone")]).encode()
    ours = json.dumps([j("Acme", "Analyst", "old"), j("New", "Role")]).encode()      # pruned Old, added New
    theirs = json.dumps([j("Acme", "Analyst", "fresh"), j("Old", "Gone"), j("Other", "Job")]).encode()
    out = json.loads(P.STRATEGY["discovered_cache.json"][0](base, ours, theirs))
    keys = [(e["company"], e["title"]) for e in out]
    assert ("Old", "Gone") not in keys and ("New", "Role") in keys and ("Other", "Job") in keys
    assert next(e for e in out if e["company"] == "Acme")["posted_date"] == "fresh", "origin's newer card kept"


def test_merge_notes_keeps_a_deletion_ours_made_on_purpose():
    """probe_candidates._wake_note strips the listing-hunt segment so the hunt re-selects the
    row; the conflict merge re-added it from theirs and re-armed the 14-day cooldown on 47
    of 152 woken rows (BACKLOG 15/60). With the base note, the deletion stands."""
    from merge_csv_rows import _merge_notes
    base = "monitored candidate | listing-hunt 2026-08-10: no listing found"
    ours = "monitored candidate | probe-woken 2026-08-25: re-hunt pending"
    theirs = base
    merged = _merge_notes(theirs, ours, base=base)
    assert "listing-hunt" not in merged and "probe-woken" in merged, merged
    # ...unless theirs rewrote that segment since checkout: newer knowledge is kept
    theirs2 = "monitored candidate | listing-hunt 2026-08-25: verified 3 IL"
    assert "listing-hunt 2026-08-25" in _merge_notes(theirs2, ours, base=base)
    assert "listing-hunt" in _merge_notes(theirs, ours), "without a base the old union is unchanged"


def test_tool_keys_cover_every_marker_replace_own_is_called_with():
    """A segment whose tool is not in `_TOOL` is keyed by its first 28 characters, so two
    runs' stamps both survive a conflict merge. url-repaired (12 live rows) and self-heal
    (4) were missing on 2026-08-25."""
    from merge_csv_rows import _seg_key
    for seg in ("url-repaired 2026-08-20: was foo", "url-repaired 2026-08-25: was bar"):
        assert _seg_key(seg) == "url-repaired"
    assert _seg_key("self-heal 2026-08-25: re-pointed") == "self-heal"
    assert _seg_key("activated 2026-08-25: 3 IL") == "activated"


@_needs_git
def test_persist_stages_only_owned_paths_tolerates_a_missing_one_and_expands_a_directory(tmp_path):
    origin, a, b = _repo_pair(tmp_path, {"companies.csv": "company_name,a,b,c,active,notes\n", "cloud_state/x.json": "{}"})
    (b / "cloud_state" / "new.json").write_text("{}", encoding="utf-8")   # untracked, under an owned dir
    (b / "cloud_state" / "x.json").write_text('{"k": 1}', encoding="utf-8")
