# --- infra 2026-08-30: CI produces a verdict, and a cron that did not fire is visible --------


def _tests_yml_jobs():
    """{job name: (timeout-minutes or None, job text)} from tests.yml, by indentation."""
    wf = open(os.path.join(_REPO, ".github", "workflows", "tests.yml"), encoding="utf-8").read()
    body = wf.split("\njobs:\n", 1)[1]
    jobs = {}
    for m in re.finditer(r"^  ([\w-]+):\n(.*?)(?=^  [\w-]+:\n|\Z)", body, re.M | re.S):
        t = re.search(r"^\s+timeout-minutes:\s*(\d+)", m.group(2), re.M)
        jobs[m.group(1)] = (int(t.group(1)) if t else None, m.group(2))
    return jobs


def test_every_long_tests_step_has_a_named_budget_below_its_job_timeout():
    """Eleven consecutive `tests.yml` runs on 2026-08-30 were CANCELLED at the `guard` job's
    `timeout-minutes: 10` -- the suite passed inside each, the rehearsals outgrew the budget --
    and a cancelled job names nothing (BACKLOG 442). Every step that runs the suite, a
    rehearsal or a mutation shard now runs under GNU `timeout` with a budget BELOW its job's
    timeout, so an overrun is a FAILED STEP that says what it was running. This pins that a
    lane adding a long step cannot quietly reintroduce the cancelled shape."""
    jobs = _tests_yml_jobs()
    assert {"guard", "rehearse", "mutation-gate"} <= set(jobs), sorted(jobs)
    # wave 1 (2026-08-30) got past the first version six ways: the budget words in a
    # comment, `python3`, two budgets summing past the job, a job with no timeout, a second
    # long step without the handler, an `if:` that skips a whole job. Hence: comments are
    # stripped, the budget must START the command, budgets are summed per job, every job
    # needs a timeout, the handler is checked per STEP, and no `if:` exists in the file.
    long = re.compile(r"python3? (?:-u )?(?:-m pytest|tests/rehearse_registry\.py|tools/mutate\.py)")
    budget_re = re.compile(r"^timeout --signal=INT --kill-after=\d+ (\d+)m python3? ")
    checked = 0
    for name, (job_timeout, text) in jobs.items():
        assert job_timeout, f"{name}: every job in tests.yml carries timeout-minutes"
        total = 0
        for step in re.split(r"^\s+- name:", text, flags=re.M)[1:]:
            code = "\n".join(l.split("#", 1)[0] for l in step.splitlines())   # comments are not code
            lines = [l.strip() for l in code.splitlines() if long.search(l)]
            if not lines:
                continue
            for line in lines:
                checked += 1
                b = budget_re.match(line)
                assert b, f"{name}: a long step whose command does not START with a named `timeout` budget:\n  {line}"
                assert int(b.group(1)) < job_timeout, \
                    f"{name}: budget {b.group(1)}m is not below the job's {job_timeout} -- the job would be cancelled first"
                total += int(b.group(1))
                assert line.endswith("|| rc=$?"), f"{name}: the exit code must be captured under bash -e:\n  {line}"
            assert '"$rc" -eq 124' in code and '"$rc" -eq 137' in code and "::error::" in code \
                and 'exit "$rc"' in code, \
                f"{name}: THIS step must turn rc 124 (budget) and 137 (killed after the INT grace) into a NAMED ::error:: and still exit non-zero"
        assert total < job_timeout, f"{name}: the step budgets sum to {total}m, the job allows {job_timeout}"
    assert checked >= 3, f"only {checked} long steps found; the extractor stopped matching"
    wf = open(os.path.join(_REPO, ".github", "workflows", "tests.yml"), encoding="utf-8").read()
    assert not re.search(r"^\s+if:", wf, re.M), "an `if:` in tests.yml is a job that can silently not run"
    # the rehearsals are one job each: `worst` once, `mixed` under seeds 1..5, never fewer
    reh = jobs["rehearse"][1]
    pairs = re.findall(r"\{\s*policy:\s*(\w+),\s*seed:\s*(\d+)\s*\}", reh)
    assert sorted(pairs) == [("mixed", "1"), ("mixed", "2"), ("mixed", "3"), ("mixed", "4"),
                             ("mixed", "5"), ("worst", "1")], pairs
    assert "fail-fast: false" in reh and "name: rehearse (${{ matrix.policy }}, seed ${{ matrix.seed }})" in reh
    assert not re.search(r"^\s*continue-on-error:", wf, re.M), "tests.yml is meant to block"
    assert not re.search(r"^\s+fetch-depth:", jobs["guard"][1], re.M), \
        "a full-history guard checkout makes test_ci_itself_confirms_why_the_tree_check_cannot_run_there red on a non-master ref (wave 1); 439 lands with its docs half or not at all"


def test_persist_run_provenance_names_the_run_in_the_subject():
    """`cloud run: state + digest for <date> [skip ci]` said nothing about WHICH run made it,
    so "unattended" was provable only by `gh run view` against a run record that is sometimes
    deleted (BACKLOG 436). The layer adds `(<event> run <id>)` before `[skip ci]` from the
    runner's own env; a local run leaves the message untouched; the tag is never doubled."""
    ps = _ps()
    env = {"GITHUB_RUN_ID": "33250362574", "GITHUB_EVENT_NAME": "schedule"}
    out = ps.run_provenance("cloud run: state + digest for 2026-08-30 [skip ci]", env)
    assert out == "cloud run: state + digest for 2026-08-30 (schedule run 33250362574) [skip ci]", out
    assert out.endswith("[skip ci]"), "the skip token must stay where GitHub reads it"
    assert re.search(r"\brun\s+\d{9,}\b", out), "docs/check_docs.py's RUN_ID regex must match it"
    assert ps.run_provenance(out, env) == out, "idempotent"
    assert ps.run_provenance("company intel: x", env) == "company intel: x (schedule run 33250362574)"
    assert ps.run_provenance("cloud run [skip ci]", {}) == "cloud run [skip ci]", "no run id: untouched"
    assert ps.run_provenance("m [skip ci]", {"GITHUB_RUN_ID": "abc"}) == "m [skip ci]", "a non-numeric id is not a run"
    assert ps.run_provenance("m [skip ci]", {"GITHUB_RUN_ID": "1"}) == "m (unknown run 1) [skip ci]"
    # wave 1: a re-run keeps `schedule` as its event -- the attempt number is what says a
    # human re-ran it; the tag goes on the SUBJECT line only; a second call with another
    # event name does not double it; the outcome commit is tagged too
    assert ps.run_provenance("m [skip ci]", dict(env, GITHUB_RUN_ATTEMPT="2")) == "m (schedule run 33250362574 attempt 2) [skip ci]"
    assert ps.run_provenance("m [skip ci]", dict(env, GITHUB_RUN_ATTEMPT="1")) == "m (schedule run 33250362574) [skip ci]"
    assert ps.run_provenance("subject [skip ci]\n\nbody [skip ci]", env) == "subject (schedule run 33250362574) [skip ci]\n\nbody [skip ci]"
    assert ps.run_provenance(out, dict(env, GITHUB_EVENT_NAME="workflow_dispatch")) == out
    src = open(os.path.join(_REPO, "persist_state.py"), encoding="utf-8").read()
    assert 'run_provenance(f"run outcome {run_date}' in src, "the failure-notice commit is a state commit too"
    assert src.index("a.message = run_provenance(a.message)") < src.index("report_deltas(key_deltas("), \
        "the audit line must record the tagged message"


def test_stages_stamp_refuses_to_rebase_on_an_unreadable_file(tmp_path, monkeypatch, capsys):
    """`stages._load()` answers `{}` for a corrupt file, and `stamp()` wrote that `{}` plus one
    key back -- every other workflow's night erased, and the next mail said `collect never ran`
    about crons that ran (BACKLOG 451). A writer over an existing file that does not parse now
    refuses, loudly, and leaves the bytes exactly as they were; an ABSENT file still gets
    created, and a healthy file still gets the stamp."""
    from pipeline import stages
    p = tmp_path / "cloud_state" / "pipeline_stages.json"
    monkeypatch.setattr(stages, "PATH", str(p))
    stages.stamp("collect", n=1)                      # absent -> created
    assert json.load(open(p, encoding="utf-8"))["collect"]["n"] == 1
    p.write_text('{"collect": {"date": "2026-08-29", "n": 7}, "firmo": {"date": "2026-08-29"', encoding="utf-8")
    before = p.read_bytes()
    stages.stamp("cron", dropped=1)
    assert p.read_bytes() == before, "a stamp over a half-written file must not touch it"
    assert "NOT stamping 'cron'" in capsys.readouterr().out
    p.write_text('{"collect": {"date": "2026-08-29", "n": 7}}', encoding="utf-8")
    stages.stamp("cron", dropped=1)
    d = json.load(open(p, encoding="utf-8"))
    assert d["collect"]["n"] == 7 and d["cron"]["dropped"] == 1, "a healthy file keeps its keys and gains the stamp"
    p.write_text("[]", encoding="utf-8")
    assert stages.stamp("cron", dropped=2) is False
    assert p.read_text(encoding="utf-8") == "[]", "not an object: refused too"
    # wave 1: a BOM-prefixed but valid file, and a zero-byte file, are not corruption
    p.write_bytes(b"\xef\xbb\xbf" + b'{"collect": {"date": "2026-08-29", "n": 7}}')
    assert stages.stamp("cron", dropped=3) is True
    d = json.load(open(p, encoding="utf-8"))
    assert d["collect"]["n"] == 7 and d["cron"]["dropped"] == 3, "a BOM must not cost a night's stamps"
    p.write_bytes(b"")
    assert stages.stamp("cron", dropped=4) is True and json.load(open(p, encoding="utf-8"))["cron"]["dropped"] == 4
    assert "ci" in stages.ORDER and "cron" in stages.ORDER, "summary() shows only ORDER; the two new stages must be in it"


def test_llm_error_envelope_without_result_names_its_subtype_and_error(monkeypatch):
    """Claude Code 2.1.x's ERROR result variant carries no `result` and no `api_error_status`;
    its cause is in `errors[]` (BACKLOG 449). `_invoke` read `result` first and printed its own
    placeholder, so two mornings' mails said `is_error (api_error_status=None)` and nothing
    else. The envelope's own words now travel; the auth pins are untouched."""
    import subprocess as _sp2
    from pipeline import llm
    # the runner has no `claude` on PATH and `_invoke` says `cli-missing` before it spawns;
    # this test is about the envelope, so the CLI's presence is stubbed (run 33300302731)
    monkeypatch.setattr(llm.shutil, "which", lambda n, *a, **k: "/usr/bin/claude")
    def cli(payload, rc=1):
        monkeypatch.setattr(llm.subprocess, "run", lambda cmd, **kw: _sp2.CompletedProcess(
            cmd, rc, stdout=json.dumps(payload), stderr=""))
    kw = dict(system="s", schema={"type": "object"}, model="sonnet", timeout=5)
    cli({"is_error": True, "subtype": "error_max_structured_output_retries",
         "errors": ["Structured output failed after 2 retries: refusal"]})
    with pytest.raises(llm.LLMUnavailable) as ei:
        llm.call("p", **kw)
    assert "error_max_structured_output_retries: Structured output failed" in str(ei.value)
    assert "api_error_status=None" not in str(ei.value)
    # wave 1: an envelope with no words of its own must not hand its raw JSON to `_kind` --
    # `"duration_ms": 401` read as an auth failure, which opens the breaker on ONE strike
    cli({"is_error": True, "subtype": "error_during_execution", "errors": [],
         "duration_ms": 401, "cwd": "/login"}, rc=0)
    with pytest.raises(llm.LLMUnavailable) as ei:
        llm.call("p", **kw)
    assert str(ei.value).startswith("error_during_execution: no result and no errors in the envelope (keys: cwd,duration_ms,errors,is_error,subtype)"), str(ei.value)
    assert ei.value.kind != "auth", "a number in the envelope is not an HTTP status"
    cli({"is_error": True, "api_error_status": 401, "result": "Failed to authenticate"})
    with pytest.raises(llm.LLMUnavailable) as ei:
        llm.call("p", **kw)
    assert ei.value.kind == "auth" and str(ei.value).startswith("Failed to authenticate")


def test_secretsenv_arms_only_the_main_checkout_or_an_explicit_path(tmp_path, capsys):
    """Four copies of `_load_secrets` each resolved `secrets.env` against their own tree, so a
    git worktree had no credentials, every paid rung silently disarmed, and a mass-zero from
    there read as a finding (BACKLOG 438). One loader: `AJIL_SECRETS=<path>` arms any tree; the
    main checkout arms from its root as before; a worktree with neither gets NOTHING and one
    stderr line saying so. `setdefault` only -- an EMPTY value already present must win, which
    is how tests/conftest.py keeps pytest from spending."""
    from pipeline import secretsenv as S
    main = tmp_path / "main"; (main / ".git").mkdir(parents=True)
    (main / "secrets.env").write_bytes(b"\xef\xbb\xbf# comment\r\nBRIGHTDATA_API_KEY = k1\r\nOTHER=v\r\n\r\nbad line\r\n")   # a BOM + CRLF, as Notepad writes it
    wt = tmp_path / "wt"; wt.mkdir(); (wt / ".git").write_text("gitdir: ../main/.git/worktrees/x\n", encoding="utf-8")
    (wt / "secrets.env").write_text("BRIGHTDATA_API_KEY=copied\n", encoding="utf-8")   # the banned copy

    env = {}
    assert S.load(str(main), env) == str(main / "secrets.env") and env == {"BRIGHTDATA_API_KEY": "k1", "OTHER": "v"}
    env = {"BRIGHTDATA_API_KEY": ""}
    S.load(str(main), env)
    assert env["BRIGHTDATA_API_KEY"] == "", "an empty value already present is the disarm sentinel and must survive"
    env = {}
    assert S.load(str(wt), env) == "" and env == {}, "a worktree is never armed implicitly, even with a copy beside it"
    err = capsys.readouterr().err
    assert "WORKTREE" in err and "DISARMED" in err and "AJIL_SECRETS" in err
    S.load(str(wt), env)
    assert capsys.readouterr().err == "", "the warning is printed once per tree"
    env = {"AJIL_SECRETS": str(main / "secrets.env")}
    assert S.load(str(wt), env) == str(main / "secrets.env") and env["OTHER"] == "v"
    env = {"AJIL_SECRETS": str(tmp_path / "missing.env")}
    assert S.load(str(wt), env) == "" and "OTHER" not in env
    assert "not a file" in capsys.readouterr().err
    env = {"GITHUB_ACTIONS": "true"}
    assert S.load(str(wt), env) == "" and capsys.readouterr().err == "", "silent on a runner"
    assert S.parse("A=1\n#x\nB = 2 \n=nokey\nC\n") == {"A": "1", "B": "2"}


def _census():
    import importlib.util
    spec = importlib.util.spec_from_file_location(
        "schedule_census_under_test", os.path.join(_REPO, "tests", "schedule_census.py"))
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def test_cron_watch_alarms_on_a_dropped_or_late_slot_and_on_nothing_else():
    """Nothing in this repo noticed a cron that never fired (BACKLOG 292/308: 4 of 5 crons on
    2026-08-27, firmographics +293..+662 min on every run it has had). `schedule_census
    --alarm` scores the census rows the fortnightly tool already computes and says ONE clause
    per workflow with a dropped slot or one past the grace -- a pending slot, a slot that
    arrived inside the grace, and a workflow with nothing to say produce no alarm key at all,
    so `stages.alarms("cron", 1)` stays quiet on a clean night. A `gh` failure is an alarm
    about the WATCH, never a false drop."""
    C = _census()
    d = dt.date(2026, 8, 28)
    at = lambda h, m=0: dt.datetime(2026, 8, 28, h, m, tzinfo=dt.timezone.utc)
    rows = [(d, "auto-expand", at(8), "dropped", None),
            (d, "auto-expand", at(20), "fired", 12),
            (d, "daily-digest", at(5), "fired", 734),
            (d, "self-heal", at(6), "fired", 30),
            (d, "jd-archive", at(12, 30), "pending", None)]
    clauses = C.alarm_clauses(rows, 720)
    assert [s for s, _ in clauses] == ["auto-expand", "daily-digest"]
    assert clauses[0][1] == "auto-expand: 08:00 on 08-28 not seen"
    assert clauses[1][1] == "daily-digest: 05:00 on 08-28 arrived +734 min late"
    slots = {"auto-expand": [], "daily-digest": [], "self-heal": [], "jd-archive": []}
    st = C.alarm_stamp(rows, slots, 720, 3, undatable=[("firmographics", "17 10 * * *")])
    assert st["dropped"] == 1 and st["late"] == 1 and st["pending"] == 1 and st["workflows"] == 4
    assert st["alarm"] == "auto-expand: 08:00 on 08-28 not seen; daily-digest: 05:00 on 08-28 arrived +734 min late"
    assert st["undatable"] == "firmographics"
    clean = C.alarm_stamp([(d, "self-heal", at(6), "fired", 30)], slots, 720, 3)
    assert "alarm" not in clean and clean["dropped"] == 0, "a clean night stamps counts and no alarm"
    broken = C.alarm_stamp([], slots, 720, 3, fetch_error="gh run list failed: 403")
    assert broken["alarm"].startswith("watch could not read the run list (gh run list failed: 403)")
    assert broken["dropped"] == 0, "a watch that could not look never reports a drop"
    # wave 1: auto-expand's 20:00 dropped, its 08:00 the next morning ON TIME -- the first
    # census looked for "the next slot" within the same day only, consumed the 08:00 run as
    # a +720 20:00 and reported the 08:00 `not seen`. The next slot of a 20:00 is tomorrow's 08:00.
    now = dt.datetime(2026, 8, 30, 5, 10, tzinfo=dt.timezone.utc)
    ae = {"auto-expand": [(8 * 60, None, "0 8,20 * * *"), (20 * 60, None, "0 8,20 * * *")]}
    since = {("auto-expand", "0 8,20 * * *"): dt.datetime(2026, 8, 1, tzinfo=dt.timezone.utc)}
    runs = [(dt.datetime(2026, 8, 28, 8, 2, tzinfo=dt.timezone.utc), "auto-expand"),
            (dt.datetime(2026, 8, 29, 8, 5, tzinfo=dt.timezone.utc), "auto-expand"),
            (dt.datetime(2026, 8, 29, 20, 1, tzinfo=dt.timezone.utc), "auto-expand")]
    got = {(r[0].isoformat(), r[2].strftime("%H:%M")): (r[3], r[4]) for r in C.census(runs, ae, 3, now, 720, since)}
    assert got[("2026-08-28", "20:00")] == ("dropped", None), got
    assert got[("2026-08-29", "08:00")] == ("fired", 5), got
    assert got[("2026-08-29", "20:00")] == ("fired", 1), got
    assert [c for _, c in C.alarm_clauses(C.census(runs, ae, 3, now, 720, since), 720)] == \
        ["auto-expand: 20:00 on 08-28 not seen"]


def test_daily_digest_alarm_steps_stamp_before_persist_and_reach_the_mail():
    """The filed diff for BACKLOG 444 placed the ci_health step AFTER persist, where its stamp
    would have landed in the tree and never in the commit. Both alarm steps (ci_health, the
    cron watch) sit before `persist`, carry ids (continue-on-error rule), the token and the
    `actions: read` grant they need, and run.py reads both stages onto the Stages: line."""
    dd = open(os.path.join(_REPO, ".github", "workflows", "daily-digest.yml"), encoding="utf-8").read()
    for sid in ("id: ci_health", "id: cron_watch", "id: firmo_drain"):
        # BEFORE the pipeline step, which reads the stamps at the top of run() -- after it
        # the mail carries yesterday's verdict (wave 1); and before persist, which commits them
        assert dd.index("id: stamp_enrich") < dd.index(sid) < dd.index("id: pipeline") < dd.index("id: persist"), sid
        step = dd.split(sid, 1)[1].split("      - name:", 1)[0]
        assert "continue-on-error: true" in step, sid
        if sid != "id: firmo_drain":
            assert "if: always()" in step and "GH_TOKEN: ${{ github.token }}" in step, sid
    assert re.search(r"^permissions:\n  contents: write.*\n  actions: read", dd, re.M), "gh run list needs actions: read"
    assert "fetch-depth: 0" in dd.split("- uses: actions/setup-python", 1)[0], "cron_since needs history"
    assert "--status completed --limit 200" in dd, "an in-progress run has no conclusion and must not read as unknown"
    ci = dd.split("id: ci_health", 1)[1].split("      - name:", 1)[0]
    assert "gh could not read" in ci and '"none" if not r' in ci and '"%d+" % len(r)' in ci, \
        "a gh failure is an honest stamp, an empty list is `none`, a streak longer than the window is `N+` (wave 1: it fabricated 50)"
    drain = dd.split("id: firmo_drain", 1)[1].split("      - name:", 1)[0]
    assert "timeout --signal=INT --kill-after=60 23m python research_firmographics.py" in drain \
        and "--budget-min 20" in drain and "stamp firmo \"alarm=step-failed(rc $rc)\"" in drain and "timeout-minutes: 25" in drain
    assert 'node-version: "22"' in dd
    assert "python tests/schedule_census.py --alarm --stamp --days 3" in dd
    run_py = open(os.path.join(_REPO, "pipeline", "run.py"), encoding="utf-8").read()
    assert 'stages.alarms("ci", 1)' in run_py and 'stages.alarms("cron", 1)' in run_py
    assert "THIS LINE IS BLIND" in run_py and "BACKLOG 474" in run_py, \
        "the digest's own drain stamps `firmo` today, so the 2-day alarm cannot fire; company-intel's tests pin the 2, so run.py must at least say so (wave 1, 474)"
    # the public dataset beside the board, and never an empty file over a good one
    pub = dd.split("id: publish", 1)[1].split("      - name:", 1)[0]
    for f in ("cloud_state/roles.csv", "cloud_state/roles.csv.meta.json", "cloud_state/funnel.csv", "docs/archive.html",
              # 498: the operator's "db with descriptions" is one self-contained published
              # location, not a CSV on Pages and its text at raw.githubusercontent
              "cloud_state/roles_archive.csv", "cloud_state/roles_text.jsonl"):
        assert f in pub, f
    # all THREE lists, or a dry run says "WOULD publish" and omits them, and the copy lands
    # in /tmp/board without ever being staged
    assert pub.count("roles_text.jsonl") == 3 and "roles_text.jsonl; do" in pub, \
        "the dry-run ls, the copy loop and the git add basenames each carry the new files"
    assert "roles_archive.csv roles_text.jsonl" in pub.split("git add", 1)[1]
    for env in ('ROLES_ARCHIVE_PAGES_URL: "https://analystjobsil.github.io/board/roles_archive.csv"',
                'ROLES_TEXT_PAGES_URL: "https://analystjobsil.github.io/board/roles_text.jsonl"'):
        assert env in dd, ("roles.build_meta reads this to say published_on_pages; without it "
                           "the file is on Pages and the meta still points at raw.github: " + env)
    assert 'if [ -s "$f" ]; then cp "$f"' in pub and "::warning::$f is empty" in pub
    assert "[ -s docs/index.html ] ||" in pub, "the board itself keeps its hard guard"
    assert 'ROLES_PAGES_URL: "https://analystjobsil.github.io/board/roles.csv"' in dd


def test_board_publish_copies_only_non_empty_optional_files(tmp_path):
    """The shell of the publish step's optional-file loop, run for real: a non-empty file is
    copied, an empty one is skipped with a warning and the board's copy survives, an absent one
    is silent. The static test above pins the text; this pins the behaviour."""
    bash = _shutil.which("bash")
    if not bash:
        pytest.skip("no bash on this machine")
    dd = open(os.path.join(_REPO, ".github", "workflows", "daily-digest.yml"), encoding="utf-8").read()
    loop = re.search(r"(          for f in docs/archive\.html .*?\n          done\n)", dd, re.S).group(1)
    src, board = tmp_path / "src", tmp_path / "board"
    (src / "docs").mkdir(parents=True); (src / "cloud_state").mkdir(); board.mkdir()
    (src / "docs" / "archive.html").write_text("<html>new</html>", encoding="utf-8")
    (src / "cloud_state" / "roles.csv").write_text("", encoding="utf-8")            # empty: keep the board's
    (board / "roles.csv").write_text("old,good\n", encoding="utf-8")
    script = "set -e\n" + "\n".join(l[10:] for l in loop.splitlines()).replace("/tmp/board", str(board).replace("\\", "/"))
    r = _sp.run([bash, "-c", script], cwd=str(src), capture_output=True, text=True)
    assert r.returncode == 0, r.stderr + r.stdout
    assert (board / "archive.html").read_text(encoding="utf-8") == "<html>new</html>"
    assert (board / "roles.csv").read_text(encoding="utf-8") == "old,good\n", "an empty artefact must never replace a good dataset"
    assert "::warning::cloud_state/roles.csv is empty" in r.stdout
    assert not (board / "funnel.csv").exists() and "funnel" not in r.stdout, "absent is silent"


def test_firmographics_workflow_carries_its_budget_its_failure_stamp_and_an_off_minute_cron():
    """BACKLOG 450: (a) `--budget-min` existed and no workflow passed it; (c) a step killed
    from outside stamped nothing, so the digest read yesterday's stamp as a drained night;
    (d) the pinned CLI ran on node 20 against a `>=22` engine. (b), the second cron, was
    REJECTED: every run this cron ever had was late, not absent, and a second slot carries
    the same lag; the one mechanism with a measurable hypothesis is moving off the `:00`
    minute GitHub names as congested (BACKLOG 305), which the 09-06 morning check reads."""
    fw = open(os.path.join(_REPO, ".github", "workflows", "firmographics.yml"), encoding="utf-8").read()
    crons = re.findall(r'^\s*-\s*cron:\s*"([^"]+)"', fw, re.M)
    assert crons == ["17 10 * * *"], crons
    assert "--budget-min 60" in fw
    stamp = fw.split("Stamp the stage when the research step died", 1)[1].split("      - name:", 1)[0]
    assert "if: failure()" in stamp and "python -m pipeline.stages stamp firmo alarm=step-failed" in stamp
    assert fw.index("node-version: \"22\"") < fw.index("npm install -g @anthropic-ai/claude-code@2.1.241")


def test_a_queue_name_the_hunt_never_touched_is_refused_even_when_the_search_read_a_page():
    """A drain-only name -- pages from `queue_drain_search`, no hunt attempt at all -- must
    come back `no-hunt-attempt`, because retiring it records "nothing findable" about a
    company the deepest rung never looked for. The record `qdisp-retire-unhunted` was filed
    (00062ef) without a test reaching this line: the end-to-end fixture supplies an empty
    drain, so the NEXT guard (`no-evidence-to-read`) caught its "Never Hunted" name and the
    mutant survived on every CI run since 08-29. Written by infra 2026-08-30 so the mutation
    gate can produce a verdict; registry owns it and may move it to tests/test_registry.py.
    Kills `qdisp-retire-unhunted`."""
    import queue_disposition as QD
    drain = {"X": {"evidence": {"search_pages": ["https://x.example/careers"]}}}
    assert QD.retirable("X", {}, {}, {}, drain, have=set()) == (False, "no-hunt-attempt")
    assert QD.retirable("X", {}, {}, {"X": {"evidence": {"url": ""}}}, drain, have=set())[1] != "no-hunt-attempt"


def test_the_prune_refuses_a_recorded_verdict_that_carries_no_evidence(tmp_path, monkeypatch):
    """`queue_disposition.main --apply` asserts a persisted record WITH evidence for every name
    it prunes. Every in-run write sets `evidence`, so the assert can only fire on a record
    that reached `cloud_state/queue_disposition.json` some other way -- an older schema, a hand
    edit -- which is exactly the defence-in-depth the record `qdisp-prune-unrecorded` names
    and the reason its designed killer (which asserts the record is WRITTEN) never reached it.
    Seed such a record; the prune must refuse rather than delete the name. Written by infra
    2026-08-30; registry owns it. Kills `qdisp-prune-unrecorded`."""
    import queue_disposition as QD
    monkeypatch.chdir(tmp_path)
    (tmp_path / "cloud_state").mkdir(); (tmp_path / "out").mkdir()
    names = ["Recorded Without Evidence"] + ["Co%d" % i for i in range(9)]
    (tmp_path / QD.QUEUE).write_text(json.dumps([{"name": n, "slug": n.lower()} for n in names]), encoding="utf-8")
    (tmp_path / QD.PATH).write_text(json.dumps({"Recorded Without Evidence": {
        "date": "2026-08-20", "verdict": "no-board", "why": "an older schema"}}), encoding="utf-8")
    (tmp_path / "out" / "queue_drain_search.json").write_text(json.dumps({"proposals": []}), encoding="utf-8")
    with pytest.raises(AssertionError, match="pruning 'Recorded Without Evidence' with no record"):
        QD.main(["--apply"])
    left = {e["name"] for e in json.loads((tmp_path / QD.QUEUE).read_text(encoding="utf-8"))}
    assert "Recorded Without Evidence" in left, "the name must survive a refused prune"


# lane: infra (2026-08-30) -- a guard that cannot fail is the defect this repo is built
# around, and until today nothing measured whether a NEW test could. `tools/guard_kill.py`
# reverts every non-test file in a range and requires the range's new tests to go red.
# `docs/sessions/2026-08-30-test-isolation.md`.

import json
import subprocess as _gk_sp
import sys as _gk_sys


def _gk_repo(tmp_path):
    """A one-module git repo with one passing test, committed; returns (root, git)."""
    def git(*a):
        return _gk_sp.run(["git", *a], cwd=tmp_path, capture_output=True, text=True, check=True)
    git("init", "-q")
    git("config", "user.email", "t@example.invalid")
    git("config", "user.name", "t")
    (tmp_path / "m.py").write_text("def double(x):\n    return x + x\n", encoding="utf-8")
    (tmp_path / "tests").mkdir()
    (tmp_path / "tests" / "test_m.py").write_text(
        "import sys, os\nsys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))\n"
        "import m\n\ndef test_double():\n    assert m.double(2) == 4\n", encoding="utf-8")
    git("add", "-A")
    git("commit", "-q", "-m", "base")
    return git


def test_guard_kill_names_the_test_that_passes_with_its_fix_reverted(tmp_path, monkeypatch):
    """Two new tests land beside a fix. One asserts the fix (`triple`), one asserts something
    that was already true. The first is KILLS, the second CANNOT-FAIL, and the exit code is 1
    because of the second alone. Also pins that `tests/` stays at HEAD in the reverted copy:
    the new tests must exist there to run at all."""
    sys_path_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    _gk_sys.path.insert(0, os.path.join(sys_path_root, "tools"))
    import guard_kill as GK
    git = _gk_repo(tmp_path)
    (tmp_path / "m.py").write_text("def double(x):\n    return x + x\n\n"
                                   "def triple(x):\n    return 3 * x\n", encoding="utf-8")
    with open(tmp_path / "tests" / "test_m.py", "a", encoding="utf-8") as f:
        f.write("\ndef test_triple():\n    assert m.triple(2) == 6\n"
                "\ndef test_double_again():\n    assert m.double(3) == 6\n")
    git("add", "-A")
    git("commit", "-q", "-m", "fix + two tests")
    monkeypatch.setattr(GK, "ROOT", str(tmp_path))
    monkeypatch.setattr(GK, "_catalogued_ids", lambda: set())
    out = tmp_path / "verdicts.json"
    rc = GK.main(["--base", "HEAD~1", "--json", str(out)])
    got = {r["test"]: r["bucket"] for r in json.loads(out.read_text(encoding="utf-8"))["tests"]}
    assert got == {"tests/test_m.py::test_triple": "KILLS",
                   "tests/test_m.py::test_double_again": "CANNOT-FAIL"}, got
    assert rc == 1, "a CANNOT-FAIL test must be the exit code, not a line in the log"
    assert "tests/test_m.py" not in json.loads(out.read_text(encoding="utf-8"))["reverted"], \
        "tests/ must stay at HEAD in the reverted copy"


def test_guard_kill_accepts_a_catalogued_killer_and_is_green_when_every_guard_dies(tmp_path, monkeypatch):
    """The escape hatch is the mutation catalogue, not a comment: a passing new test whose
    docstring names a REAL mutation record (the mutate.py convention) is CATALOGUED (tools/mutate.py verifies
    it), an unknown id is not. With only KILLS and CATALOGUED the exit code is 0."""
    sys_path_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    _gk_sys.path.insert(0, os.path.join(sys_path_root, "tools"))
    import guard_kill as GK
    git = _gk_repo(tmp_path)
    (tmp_path / "m.py").write_text("def double(x):\n    return 2 * x\n", encoding="utf-8")
    with open(tmp_path / "tests" / "test_m.py", "a", encoding="utf-8") as f:
        f.write('\ndef test_vouched():\n    """Kills `m-double-remove`."""\n    assert m.double(1) == 2\n')
    git("add", "-A")
    git("commit", "-q", "-m", "refactor + a catalogued guard")
    monkeypatch.setattr(GK, "ROOT", str(tmp_path))
    monkeypatch.setattr(GK, "_catalogued_ids", lambda: {"m-double-remove"})
    out = tmp_path / "v.json"
    assert GK.main(["--base", "HEAD~1", "--json", str(out)]) == 0
    rows = json.loads(out.read_text(encoding="utf-8"))["tests"]
    assert [(r["bucket"], r["kills"]) for r in rows] == [("CATALOGUED", ["m-double-remove"])], rows
    # the same docstring naming an id the catalogue does not have vouches for nothing
    assert GK.classify([("t::x", "Kills `ghost`.")], {"t::x": "PASSED"}, {"m-double-remove"}) \
        == [{"test": "t::x", "verdict": "PASSED", "bucket": "CANNOT-FAIL", "kills": []}]
    # and a SKIPPED or uncollected test is reported as such, never judged either way
    assert [r["bucket"] for r in GK.classify([("t::s", ""), ("t::m", "")],
                                              {"t::s": "SKIPPED"}, set())] == ["SKIPPED", "NOT-RUN"]


def test_guard_kill_sees_new_tests_by_definition_not_by_diff_position():
    """A test is new when its NAME is absent from the base file, so a test added in the middle
    of a file (every lane's habit) counts, a moved one does not, and class methods count."""
    sys_path_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    _gk_sys.path.insert(0, os.path.join(sys_path_root, "tools"))
    import guard_kill as GK
    names = GK._test_names("def test_a():\n    'doc a'\n\nclass TestX:\n    def test_b(self):\n"
                           "        pass\n\ndef helper():\n    pass\n", "t.py")
    assert names == {"test_a": "doc a", "TestX::test_b": ""}
    assert GK._test_names("def test_broken(:\n", "t.py") == {}, "a syntax error is not a test"


def test_guard_kill_runs_in_ci_against_the_pushed_range_with_history_to_see_it():
    """`tests.yml` runs the tool in its own job with `fetch-depth: 0` (the `guard` job is depth
    1 on purpose -- see its comment) against `github.event.before`, falling back to `HEAD~1`
    when that sha is unknown (a force-push, or the all-zero sha of a new branch). Pinned so the
    check cannot be dropped from the gate, or left pointing at a base that makes it a no-op."""
    jobs = _tests_yml_jobs()
    assert "guard-kill" in jobs, sorted(jobs)
    timeout, text = jobs["guard-kill"]
    assert timeout, "every job in tests.yml carries timeout-minutes"
    assert "fetch-depth: 0" in text, "without history the tool cannot see the base"
    assert "github.event.before" in text and "HEAD~1" in text
    assert "python tools/guard_kill.py" in text


# --------------------------------------------------------------------------- registry, 2026-08-30 (c)
# The drain reads the ledger, reaches today's intake first, and stops before the step kills
# it; a query URL is a QUERY, and a park on one holds. `docs/sessions/2026-08-30-registry-c.md`.

def _r830c_tree(tmp_path, monkeypatch, queue, csv_rows=(), qstate=None, disp=None):
    _r830_tree(tmp_path, monkeypatch, queue, csv_rows=csv_rows, qstate=qstate, disp=disp)
    import queue_disposition as QD
    monkeypatch.setattr(QD, "PATH", str(tmp_path / "cloud_state" / "queue_disposition.json"))


def test_disposition_helpers_live_in_queue_disposition_and_are_reexported():
    """The drain must read a retirement without importing the orchestrator. The ledger's
    vocabulary moved to the ledger's module; `queue_pipeline` re-exports it unchanged."""
    import queue_pipeline as QP
    import queue_disposition as QD
    for name in ("RETIRABLE", "RETIRED_VERDICTS", "REOPEN_DAYS", "is_reopened",
                 "disposition_verdict"):
        assert getattr(QP, name) is getattr(QD, name), name
    assert QD.disposition_verdict("x", {"x": {"verdict": "no-board", "date": "2026-08-29"}},
                                  today=_dtm.date(2026, 8, 30)) == "no-board"
    assert QD.disposition_verdict("x", {"x": {"verdict": "no-board", "date": "2026-05-01"}},
                                  today=_dtm.date(2026, 8, 30)) == ""
    assert QD.disposition_verdict("x", {"x": {"verdict": "overturned-no-board"}}) == ""
    assert QD.disposition_verdict("x", {"x": {"verdict": "cannot-tell"}}) == ""


def test_drain_skips_a_name_whose_retirement_is_live(tmp_path, monkeypatch):
    """Kills `drain-targets-ignore-disposition`.

    Intake re-adds a retired name every morning (189 of 362 on 2026-08-30) and
    `--retire-settled` runs three steps AFTER the drain, so a name retired on evidence was a
    paid search away from being re-bought the night its 14-day cadence lapsed. `targets()`
    now reads the ledger: a LIVE retirement is skipped; `cannot-tell`, an overturned
    verdict and an expired `no-board` stay owed.
    """
    import queue_resolve_search as QRS
    today = _dtm.date(2026, 8, 30)
    disp = {"Retired Co": {"date": "2026-08-29", "verdict": "no-board"},
            "Dup Co": {"date": "2024-01-01", "verdict": "duplicate-of"},   # never expires
            "Old NoBoard": {"date": "2026-05-01", "verdict": "no-board"},   # past 90 days
            "Reopened Co": {"date": "2026-08-30", "verdict": "overturned-no-board"},
            "Unsure Co": {"date": "2026-08-30", "verdict": "cannot-tell"}}
    _r830c_tree(tmp_path, monkeypatch,
                queue=["Retired Co", "Dup Co", "Old NoBoard", "Reopened Co", "Unsure Co",
                       "Fresh Co"], disp=disp)
    got = QRS.targets(today=today)
    assert "Retired Co" not in got and "Dup Co" not in got, got
    assert {"Old NoBoard", "Reopened Co", "Unsure Co", "Fresh Co"} <= set(got), got
    # ...the cleanup's own verdicts count too (`covered-by-row`: Faye's board is read by a
    # row named `withfaye`), and the ledger key's casing does not matter
    disp["Faye"] = {"date": "2026-08-30", "verdict": "covered-by-row"}
    disp["NATASHA DENONA IL"] = {"date": "2026-08-30", "verdict": "duplicate-of",
                                 "evidence": {"x": 1}}
    _r830c_tree(tmp_path, monkeypatch, queue=["Faye", "Natasha Denona Il", "Fresh Co"], disp=disp)
    assert QRS.targets(today=today) == ["Fresh Co"]
    import queue_disposition as QD
    assert QD.is_retired("natasha denona il", disp) and not QD.is_retired("Fresh Co", disp)
    # ...and the cleanup PRUNES it under the other casing, instead of classifying it every
    # night and keeping it (the prune path looked the record up by the exact key)
    import queue_pipeline as QP
    assert QP.retire_settled(apply=True) >= 1
    left = {e["name"] for e in _json.loads(
        (tmp_path / "research_companies.json").read_text(encoding="utf-8"))}
    assert "Natasha Denona Il" not in left, left


def test_drain_targets_never_tried_first_then_stalest(tmp_path, monkeypatch):
    """The file is append-ordered (oldest intake first), so a day's new names waited behind
    every older residue. Never-searched names come first, then the oldest search; the
    stride is applied to the RANKED list, so every shard sees the same ranking."""
    import queue_resolve_search as QRS
    import queue_state as QS
    st = {}
    QS.record(st, "Searched Aug 1", "search-llm", "no-proposal", day="2026-08-01")
    QS.record(st, "Searched Jul 1", "search-llm", "no-proposal", day="2026-07-01")
    _r830c_tree(tmp_path, monkeypatch,
                queue=["Searched Aug 1", "Searched Jul 1", "New A", "New B"], qstate=st)
    assert QRS.targets() == ["New A", "New B", "Searched Jul 1", "Searched Aug 1"]
    assert QRS.targets(shard="2/2") == ["New B", "Searched Aug 1"]
    assert QRS.targets(cap=1) == ["New A"]
    # never ONLY the new: intake outruns capacity, so a re-try class no one reaches is a
    # name frozen at its first refusal for ever -- one slot in five is the stalest re-try
    ranked = [(0, "", "N%d" % i) for i in range(20)] + [(1, "2026-07-0%d" % d, "S%d" % d)
                                                         for d in range(1, 4)]
    got = QRS.select(ranked, 10)
    assert len(got) == 10 and [t[2] for t in got][-2:] == ["S1", "S2"], got
    assert QRS.select(ranked, 30) == ranked and QRS.select(ranked[:5], 10) == ranked[:5]


def test_the_drain_capacity_constants_match_the_workflow():
    """`nightly_capacity()` is derived from the constants the cloud runs on; if the workflow
    changes its shard count, cap or step timeout, this is the test that says so."""
    import queue_resolve_search as QRS
    wf = open(os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))),
                           ".github", "workflows", "listing-hunt.yml"), encoding="utf-8").read()
    step = wf[wf.index("Resolve intake names by search"):wf.index("Verify and apply queue proposals")]
    shards = _re.search(r"for i in ((?:\d+ ?)+); do", step).group(1).split()
    assert len(shards) == QRS.NIGHT_SHARDS, shards
    assert int(_re.search(r"--cap (\d+)", step).group(1)) == QRS.NIGHT_CAP
    timeout = int(_re.search(r"timeout-minutes: (\d+)", step).group(1))
    assert QRS.budgeted(QRS.NIGHT_CAP, 26, 55) == 28
    assert QRS.TIME_BUDGET_MIN < timeout, "the shard's own budget must end before GitHub's kill"
    assert QRS.budgeted(QRS.NIGHT_CAP) * QRS.SEC_PER_NAME / 60 < timeout, (
        "the names a shard selects must fit the step at the assumed pace")
    assert QRS.nightly_capacity() == QRS.NIGHT_SHARDS * QRS.budgeted(QRS.NIGHT_CAP)
    assert QRS.budgeted(30, 0, 55) == 30, "budget 0 means no clock"


def test_drain_stops_scoring_at_the_budget_and_records_nothing_for_the_rest(
        tmp_path, monkeypatch, capsys):
    """One shard past the step's 30 minutes loses EVERY shard's attempt log (the ingest
    runs after `wait` in the same step). So a shard stops itself between names -- and never
    writes a proposal for a name it did not score: ingested, that would start a 14-day
    cadence on a name nobody judged."""
    import queue_resolve_search as QRS
    _r830c_tree(tmp_path, monkeypatch, queue=["A", "B", "C"])
    # the preflight refuses a disarmed rung before selecting; this test stubs `search_one`,
    # so it declares the rung armed (`tests/conftest.py` bans the transport regardless).
    monkeypatch.setenv("BRIGHTDATA_API_KEY", "test-key-not-a-real-one")
    monkeypatch.setenv("BRIGHTDATA_ZONE", "test-zone")
    monkeypatch.setenv("DEEP_BD_SEARCH_CAP", "5")
    clock = iter([0, 0, 10, 20, 30, 40, 70, 100, 130, 200, 300, 400, 500, 600, 700])
    monkeypatch.setattr(QRS.time, "monotonic", lambda: next(clock))
    monkeypatch.setattr(QRS, "SEC_PER_NAME", 10.0)      # 1 min fits all three by estimate...
    monkeypatch.setattr(QRS, "search_one", lambda n: {"urls": ["https://%s.example/careers" % n],
                                                      "picked": "", "why": ""})
    monkeypatch.setattr(QRS, "score_one", lambda n, f: ("monitor", f["urls"][0], 0, ""))
    out = tmp_path / "qrs.json"
    assert QRS.main(["--propose", str(out), "--cap", "3", "--budget-min", "1"]) == 0
    props = _json.loads(out.read_text(encoding="utf-8"))["proposals"]
    text = capsys.readouterr().out
    assert "budget hit" in text and "not searched/scored" in text
    scored = [p["name"] for p in props if p["kind"] == "monitor"]
    paid = [p for p in props if p["kind"] == "refused"]
    assert 0 < len(scored) < 3 and paid, (scored, paid)
    # a name whose search WAS paid is recorded (or it is re-bought tomorrow)
    assert all(p["why"].startswith("budget hit") for p in paid)
    assert len(scored) + len(paid) == 3
    # ...and one that tripped in PHASE 1 (never searched) is written nowhere
    clock = iter([0, 100, 200, 300, 400, 500, 600, 700, 800, 900])   # over before the 1st search
    monkeypatch.setattr(QRS.time, "monotonic", lambda: next(clock))
    out2 = tmp_path / "qrs2.json"
    assert QRS.main(["--propose", str(out2), "--cap", "3", "--budget-min", "1"]) == 0
    props2 = _json.loads(out2.read_text(encoding="utf-8"))["proposals"]
    assert props2 == [], props2
    assert "3 untouched" in capsys.readouterr().out


def test_search_one_returns_a_dict_when_every_search_raises(monkeypatch):
    """Every other exit is a dict; the error path returned a 4-tuple, `main` did
    `cache[name]["urls"]` on it, the shard died and the malformed entry was already in the
    search cache so the re-run died on the same name."""
    import queue_resolve_search as QRS
    import deep_validate as DV

    def boom(name):
        raise RuntimeError("unlocker 502")
    monkeypatch.setattr(DV, "google_via_unlocker", boom)
    monkeypatch.setattr(QRS.time, "sleep", lambda s: None)
    got = QRS.search_one("Acme")
    assert isinstance(got, dict) and got["urls"] == [] and got["why"].startswith("search-error")
    # ...and a malformed cached entry is scored as "no-search-results", never a crash
    assert QRS.score_one("Acme", ["refused", "", 0, "search-error x"])[0] == "refused"


def test_the_stamp_separates_intake_from_resurrection(tmp_path, monkeypatch):
    """`queue GREW by N` could not tell today's arrivals from retired names intake put back.
    The stamp now carries both halves, and the BEHIND alarm counts only what the drain will
    actually select."""
    import queue_pipeline as QP
    import queue_state as QS
    st = {}
    QS.record(st, "Searched Co", "search-llm", "no-proposal", day="2026-07-01")
    _r830c_tree(tmp_path, monkeypatch, queue=["Fresh Co", "Retired Co", "Searched Co"],
                qstate=st, disp={"Retired Co": _r830_disp("no-board", QP.TODAY)})
    live = QP._drain_liveness()
    assert live["selectable"] == 2, live
    assert live["new_intake"] == 1 and live["retired_in_queue"] == 1, live
    assert QP.DRAIN_NIGHTLY_CAP == __import__("queue_resolve_search").nightly_capacity()
    # a corrupt attempt log is a HARD STOP for writers; the stamp says so instead of dying
    (tmp_path / "cloud_state" / "queue_state.json").write_text("{\"A\": [", encoding="utf-8")
    live = QP._drain_liveness()
    assert "UNREADABLE" in live.get("drain_alarm", ""), live
    # ...all the way up: `--stamp` writes the alarm into the stage instead of dying in census
    from pipeline import stages
    monkeypatch.setattr(stages, "PATH", str(tmp_path / "cloud_state" / "pipeline_stages.json"))
    assert QP.main(["--stamp"]) == 0
    assert "UNREADABLE" in (stages._load().get("queue") or {}).get("drain_alarm", "")
    # and the disposition ledger fails CLOSED too: the drain reads it to know what not to buy
    import queue_disposition as QD
    (tmp_path / "cloud_state" / "queue_disposition.json").write_text("[1,", encoding="utf-8")
    with pytest.raises(SystemExit):
        QD.load()


def test_queue_state_load_refuses_a_corrupt_log_and_tolerates_an_absent_one(tmp_path, monkeypatch):
    """`load` answered {} to every exception and `save` writes what it is handed: a truncated
    file plus one `--ingest` would have persisted ~120 names over 6,589 attempts."""
    import queue_state as QS
    missing = tmp_path / "none.json"
    assert QS.load(str(missing)) == {}
    bad = tmp_path / "bad.json"
    bad.write_text("{\"A\": {\"tried\": [", encoding="utf-8")
    with pytest.raises(SystemExit):
        QS.load(str(bad))
    wrong = tmp_path / "list.json"
    wrong.write_text("[]", encoding="utf-8")
    with pytest.raises(SystemExit):
        QS.load(str(wrong))
    assert bad.read_text(encoding="utf-8").startswith("{\"A\""), "nothing was written over it"


def test_the_queue_reports_what_is_owed_not_what_is_merely_unsettled(tmp_path, monkeypatch):
    """`STILL OWED AN ANSWER` was one number over three states, and it read **546** on
    2026-08-30 when the work actually available was **172**. The other 374 were not owed
    anything: 200 had been answered inside their 14-day cadence, 174 had an answer already
    on disk waiting for `--retire-settled`. Every plan written that day — including the
    operator's own spawn prompt — was sized against 546.

    OWED is defined as "the drain would select it tonight", and it is the drain's OWN
    selector, imported: a census that can disagree with the thing it measures is how 546
    happened."""
    import queue_pipeline as QP
    import queue_state as QS
    st = {}
    QS.record(st, "Answered Recently", "search-llm", "no-proposal", day=QP.TODAY)
    _r830c_tree(tmp_path, monkeypatch,
                queue=["Fresh Co", "Answered Recently", "Retired Co"],
                qstate=st, disp={"Retired Co": _r830_disp("no-board", QP.TODAY)})
    owed, cadence, answered = QS.queue_states()
    assert (owed, cadence, answered) == (1, 1, 1), (owed, cadence, answered)

    # the three states must partition the unsettled queue, and OWED must BE the drain's set
    import queue_resolve_search as QRS
    assert owed == len(QRS.targets()), "the census disagrees with the rung it describes"

    # ...and the number that reaches the daily mail is the owed one, not the raw total
    from pipeline import stages
    monkeypatch.setattr(stages, "PATH", str(tmp_path / "cloud_state" / "pipeline_stages.json"))
    detail = QP.stamp_queue({"buckets": {"owed, a nightly rung retries it": 3},
                             "unverified_rows": 0})
    assert detail["owed"] == 1 and detail["unsettled"] == 3, detail
    assert detail["on_cadence"] == 1 and detail["answered_on_disk"] == 1, detail
    assert "queue" in stages.ORDER, "a stage absent from ORDER is stamped and read by nobody"
    line = [p for p in stages.summary().split(" | ") if p.startswith("queue")]
    assert line and "owed=1" in line[0], line


def test_every_stamped_stage_is_rendered_somewhere_a_human_reads():
    """`summary()` renders `ORDER` and nothing else, so a stamp missing from that list is
    written nightly and read by nobody. On 2026-08-31 the file carried TEN stamps and the
    list named EIGHT: `queue` (the registry's) and `intel` (company-intel's `backlog` /
    `blurbs` / `board` / `researched`) were both invisible in the daily mail — two of the
    four queues that are supposed to be named there."""
    import json
    from pipeline import stages
    try:
        with open("cloud_state/pipeline_stages.json", encoding="utf-8-sig") as f:
            stamped = set(json.load(f))
    except Exception:                                             # noqa: BLE001
        pytest.skip("no stage file in this tree")
    missing = sorted(stamped - set(stages.ORDER))
    assert not missing, (f"these stages are stamped and rendered nowhere: {missing} — add "
                         f"them to stages.ORDER or nobody will ever read the number")


def test_the_drain_makes_its_own_output_directory(tmp_path, monkeypatch):
    """The cloud drain had never recorded an attempt, and this is why: `out/` is gitignored,
    nothing in `listing-hunt.yml` creates it, and no earlier step happens to. On 2026-08-31
    all four shards selected their names, bought the first search and died at the first
    cache write — `FileNotFoundError: out/qrs_4.json.search`, 6 seconds in. The step is
    `continue-on-error: true`, so it was GREEN, and `ingested 0 new attempts` was the only
    trace that 112 selected names had produced nothing."""
    import queue_resolve_search as QRS
    monkeypatch.chdir(tmp_path)
    # the preflight refuses a DISARMED rung (no key / a cap of 0) before it selects a
    # name, so a test that stubs the search must say the rung is armed. Nothing can be
    # bought: `tests/conftest.py` bans the transport itself.
    monkeypatch.setenv("BRIGHTDATA_API_KEY", "test-key-not-a-real-one")
    monkeypatch.setenv("BRIGHTDATA_ZONE", "test-zone")
    monkeypatch.setenv("DEEP_BD_SEARCH_CAP", "5")
    (tmp_path / "research_companies.json").write_text("[]", encoding="utf-8")
    monkeypatch.setattr(QRS, "targets", lambda *a, **k: [])
    monkeypatch.setattr(QRS, "ranked_targets", lambda *a, **k: [])
    out = tmp_path / "out" / "qrs_1.json"
    assert not out.parent.exists(), "the directory must be absent for this to mean anything"
    QRS.main(["--propose", str(out), "--cap", "1"])
    assert out.parent.is_dir(), "the drain did not create its own output directory"


def test_a_half_written_proposal_file_is_reported_not_swallowed(tmp_path, capsys):
    """A shard killed mid-write left an unparsable proposal file and `ingest` skipped it in
    SILENCE, so that shard's paid searches were never recorded and its names sorted first
    again the next night — the same credits bought twice, with nothing in the log to say so
    (`502`). The writers swap atomically now, so the skip should be unreachable; when it is
    not, it is loud."""
    import queue_state as QS
    good = tmp_path / "qrs_1.json"
    good.write_text(json.dumps({"generated": "2026-08-30", "proposals": [
        {"name": "Good Co", "kind": "scrape", "rung": "search-llm",
         "evidence": {"candidate_url": "https://good.example/careers"}}]}), encoding="utf-8")
    torn = tmp_path / "qrs_2.json"
    torn.write_text('{"generated": "2026-08-30", "proposals": [{"name": "Torn',
                    encoding="utf-8")
    state = {}
    n = QS.ingest(state, [str(tmp_path / "qrs_*.json")])
    assert n == 1 and "Good Co" in state, state
    err = capsys.readouterr().out
    assert "::warning::ingest:" in err and "qrs_2.json" in err, err
    assert "NOT recorded" in err, err


# ---- the query-URL class ---------------------------------------------------------------

_COMCAST_URL = "https://jobs.comcast.com/search-jobs?location=Israel"


def _cards(*paths, page=_COMCAST_URL, title="Analyst", **extra):
    return [dict({"title": title, "location": "Israel", "country_code": "",
                  "url": ("https://jobs.comcast.com" + p) if p else page}, **extra)
            for p in paths]


def test_has_location_query_names_the_class():
    import audit_query_urls as AQ
    for u in (_COMCAST_URL, "https://x.com/jobs?locationsearch=Israel",
              "https://x.com/careers#location=Israel", "https://x.com/s%3Flocation%3DIsrael",
              "https://www.amazon.jobs/en/search.json?country=ISR",
              "https://careers.snap.com/jobs?location=Tel%20Aviv%2C%20Israel",
              "https://jobs.careers.microsoft.com/global/en/search?lc=Israel",
              "https://xtra-mile.co/careers-result-page/?nam=&dep=&loc=IL&submit=Search",
              "https://www.metacareers.com/jobs?offices[0]=Tel%20Aviv%2C%20Israel"):
        assert AQ.has_location_query(u), u
    for u in ("https://www.comeet.com/careers-api/2.0/company/60.002/positions?token=abc",
              "https://boards-api.greenhouse.io/v1/boards/fiverr/jobs", "", None,
              "https://x.com/careers?page=2", "https://x.com/jobs?locale=en_US",
              "https://x.com/jobs?lang=il", "https://x.com/careers?block=2&blockId=7"):
        assert not AQ.has_location_query(u), u          # `il_jobs` fails CLOSED on a query URL


def test_query_filter_verdict_needs_card_level_majority():
    """Kills `query-audit-park-on-description`.

    A park stands on the board's OWN routing (the card's url path, title tail, country
    code), never on a description: ASML's cards say "China, Connecticut" in JD boilerplate
    on a filter it honours."""
    import audit_query_urls as AQ
    comcast = _cards("/job/pennsylvania/analyst/1", "/job/houston/manager/2",
                     "/job/plano/pm/3", "/job/colorado/pm/4", "", "")
    assert AQ.verdict_from(AQ.tally(comcast, _COMCAST_URL)) == "ignored"
    asml = _cards(*["/en/careers/job/%d" % i for i in range(25)],
                  page="https://www.asml.com/en/careers/find-your-job?location=Israel",
                  description="ASML has offices in China, Connecticut and Veldhoven")
    t = AQ.tally(asml, "https://www.asml.com/en/careers/find-your-job?location=Israel")
    assert t["foreign"] == 0 and AQ.verdict_from(t) == "no-signal", t
    two = _cards("/job/houston/x/1", "/job/plano/x/2", *[""] * 18)
    assert AQ.verdict_from(AQ.tally(two, _COMCAST_URL)) == "leaning-foreign"
    # 4 foreign of 116 (Hunter Douglas) is 3.4%: not evidence about the other 112
    thin = _cards("/job/sydney/1", "/job/bogota/2", "/job/mexico/3", "/job/berlin/4", *[""] * 112)
    assert AQ.verdict_from(AQ.tally(thin, _COMCAST_URL)) == "leaning-foreign"
    # a squashed slug is still a place; a company's own name in a title tail is not one
    assert AQ.card_signal({"url": "https://x.wd3.myworkdayjobs.com/job/Ness-ZionaIsrael/x_R1",
                           "title": "Engineer"}, _COMCAST_URL) == "il"
    assert AQ.card_signal({"url": "https://jobs.sw.siemens.com/ra-anana-isr/x/9", "title": "x"},
                          _COMCAST_URL) == "il"
    assert AQ.card_signal({"url": "https://jobs.bostonscientific.com/job/512345/",
                           "title": "Data Analyst, Boston Scientific"}, _COMCAST_URL,
                          company="Boston Scientific") == ""
    assert AQ.card_signal({"url": "", "country_code": "ISR"}, _COMCAST_URL) == "il"
    assert AQ.card_signal({"url": "", "country_code": "972"}, _COMCAST_URL) == ""
    # a title tail may carry a comma of its own: `Reston, VA` is a place, `VA` alone was not
    for t in ("Data Analyst - Reston, VA", "Senior Analyst, Houston, TX", "Analyst - Philadelphia, PA",
              "BI Analyst - Springfield, MO"):
        assert AQ.card_signal({"url": "", "title": t}, _COMCAST_URL) == "foreign", t
    assert AQ.card_signal({"url": "", "title": "Data Analyst - Tel Aviv, Israel"}, _COMCAST_URL) == "il"
    assert AQ.card_signal({"url": "", "title": "Data Analyst, Boston Scientific"}, _COMCAST_URL,
                          company="Boston Scientific") == ""
    leaks = _cards("/job/houston/x/1", "/job/tel-aviv/x/2", "/job/houston/x/3", "/job/plano/x/4")
    assert AQ.verdict_from(AQ.tally(leaks, _COMCAST_URL)) == "leaks", "1 IL among 3 abroad parks"
    mixed = _cards("/job/houston/x/1", "/job/tel-aviv/x/2", "/job/haifa/x/3", "/job/plano/x/4",
                   "/job/herzliya/x/5")
    assert AQ.verdict_from(AQ.tally(mixed, _COMCAST_URL)) == "mixed", "Israel the majority stays"
    assert AQ._seg("leaks", AQ.tally(leaks, _COMCAST_URL)).endswith(AQ.POOL_TOKEN)
    honoured = _cards("/job/tel-aviv/x/2", "/job/haifa/x/3")
    assert AQ.verdict_from(AQ.tally(honoured, _COMCAST_URL)) == "honoured"
    assert AQ.verdict_from(AQ.tally([], _COMCAST_URL)) == "no-cards"
    # a card whose url IS the page url says nothing, whatever the page url says
    assert AQ.card_signal({"url": _COMCAST_URL, "title": "Filter Results"}, _COMCAST_URL) == ""
    # a native row's location field is the API's answer, not our stamp
    assert AQ.card_signal({"url": "", "location": "Petah Tikva, Israel"}, "https://api/x?country=ISR",
                          platform="custom_json") == "il"
    assert AQ.card_signal({"url": "", "location": "Petah Tikva, Israel"}, "https://api/x?country=ISR",
                          platform="scrape") == ""


def test_a_query_url_never_activates_on_stamped_locations(capsys):
    """Kills `hunt-query-url-stamped-il`.

    On `?location=Israel` every card is stamped Israel by the scraper, so `len(il) >= 1`
    was our own assumption counted back; the park was undone by the next hunt on the same
    14 US cards. A card that names its own city still activates, and a plain URL is untouched.
    """
    import listing_hunt as L
    stamped = _cards("/job/houston/x/1", "/job/pennsylvania/y/2")
