    rows, counts = roles.build_rows(recs, run_date="2026-08-31")
    for bad in ("0", "false", "javascript:alert(1)", "analystjobsil.github.io/board/roles.csv", "  "):
        m = roles.build_meta(rows, counts, recs, run_date="2026-08-31", pages_url=bad)
