def test_the_digest_dry_run_exercises_the_run_and_writes_nothing_outward():
    """The operator's ask (2026-08-30): the real cloud on demand, without side effects. The
    manual dispatch of 2026-08-30 collided with the scheduled run (deliver refused a
    same-date duplicate, the step exited 1, the publish step was skipped), so the way to
    see the schedule work was the thing that broke it. `dry_run` keeps every step that
    reads, fetches, classifies and renders, and turns the six that reach outside the runner
    into a printed line. This pins that every outward step reads DRY_RUN and that the flag
    is empty (never "0") on a scheduled run."""
    dd = open(os.path.join(_REPO, ".github", "workflows", "daily-digest.yml"), encoding="utf-8").read()
    assert re.search(r"^      dry_run:\n        description:", dd, re.M), "the dispatch input"
    assert "DRY_RUN: ${{ github.event.inputs.dry_run == 'true' && '1' || '' }}" in dd, \
        "the flag is '1' on a dry-run dispatch and EMPTY on the schedule"
    steps = dd.split("      - name:")[1:]
    by_id = {re.search(r"\n        id: (\w+)", s).group(1): s for s in steps if re.search(r"\n        id: (\w+)", s)}
    for sid, must in (("pipeline", "deliver --date \"$(date -u +%F)\" $DRY"),
                      ("mark_sent", "WOULD mark sent"), ("persist", "commit --as \"github-actions[bot]\" $DRY"),
                      ("publish", "WOULD publish"), ("outcome", "persist_state.py outcome\n"),
                      ("notify_relay", "WOULD hand the relay")):
        assert '"$DRY_RUN" = 1' in by_id[sid], f"{sid}: does not read DRY_RUN"
        assert must in by_id[sid], f"{sid}: the dry branch is missing ({must!r})"
    # the dry branches of the two steps that PUSH never reach the push command
    for sid, push in (("publish", "git push origin"), ("notify_relay", "git push -q origin")):
        body = by_id[sid]
        assert body.index('"$DRY_RUN" = 1') < body.index("exit 0") < body.index(push), sid


@_needs_git
def test_persist_dry_run_runs_the_gates_prints_the_commit_and_pushes_nothing(tmp_path):
    """`persist_state.py commit --dry-run` (the cloud dry-run's persist step): the gates run
    for real -- a file that fails one is reported as refused -- the would-be commit is
    printed path by path, and origin, HEAD and the audit log are untouched."""
    origin, a, b = _repo_pair(tmp_path, {"x.txt": "x", "cloud_state/y.json": "{}",
                                         "cloud_state/persist_log.jsonl": ""})
    (b / "x.txt").write_text("changed", encoding="utf-8")
    (b / "cloud_state" / "y.json").write_text("{not json", encoding="utf-8")
    head = _g(str(b), "rev-parse", "HEAD")
    r = _persist(b, "x.txt", "cloud_state/y.json", extra=("--dry-run",))
    out = r.stdout.decode("utf-8", "replace") + r.stderr.decode("utf-8", "replace")
    assert r.returncode == 1, out                     # the refused file is still a red step
    assert "DRY RUN -- would commit 1 path(s)" in out and " M x.txt" in out, out
    assert "refused: cloud_state/y.json" in out, out
    assert _g(str(b), "rev-parse", "HEAD") == head, "a dry run makes no commit"
    assert _origin(origin, "x.txt") == "x", "a dry run pushes nothing"
    assert (b / "x.txt").read_text(encoding="utf-8") == "changed", "the run's bytes are left in place"
    assert _g(str(b), "diff", "--cached", "--name-only").strip() == "", "nothing stays staged"
    assert (b / "cloud_state" / "persist_log.jsonl").read_text(encoding="utf-8") == "", \
        "no audit line for a commit that never happened"
    assert (b / "cloud_state" / "y.json").read_text(encoding="utf-8") == "{}", \
        "the gate's restore is real, as it would be on the true run"



# --- docs lane, 2026-08-30 (c): a filed diff outlived five commits to its target file, and
# --- `next` read only the local file while four numbers came to name two items each -------
def _debt_repo(tmp_path, backlog, handoff_before, handoff_after, touch, second_commit=True):
    """A two-commit repo: origin/master at the baseline, HEAD one commit on. The check
    diffs COMMITTED trees (`git diff base HEAD`), so the branch's change must be a commit -
    a working-tree edit is invisible to it by design, exactly as it is to a push."""
    import shutil
    import subprocess

    def git(*a):
        return subprocess.run(["git"] + list(a), cwd=str(tmp_path), capture_output=True,
                              text=True, encoding="utf-8", errors="replace")
    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    (tmp_path / "docs").mkdir(parents=True, exist_ok=True)
    (tmp_path / "pipeline").mkdir(exist_ok=True)
    (tmp_path / "tests").mkdir(exist_ok=True)
    shutil.copy(os.path.join(root, "docs", "backlog.py"), str(tmp_path / "docs" / "backlog.py"))
    (tmp_path / "docs" / "AGENT_BRIEF.md").write_text(
        "| **`registry`** | 2 | rows | `companies.csv` |" + chr(10), encoding="utf-8")
    (tmp_path / "docs" / "BACKLOG.md").write_text(backlog, encoding="utf-8")
    (tmp_path / "pipeline" / "jdfill.py").write_text("def load_secrets():" + chr(10)
                                                     + "    pass" + chr(10), encoding="utf-8")
    (tmp_path / "tests" / "test_units.py").write_text("# tests" + chr(10), encoding="utf-8")
    (tmp_path / "HANDOFF.md").write_text(handoff_before, encoding="utf-8")
    git("init", "-q")
    git("config", "user.email", "guard@example.invalid")
    git("config", "user.name", "guard")
    git("config", "commit.gpgsign", "false")
    git("add", "-A")
    assert git("commit", "-q", "-m", "baseline").returncode == 0
    git("update-ref", "refs/remotes/origin/master", "HEAD")
    for rel in touch:
        p = tmp_path / rel
        p.write_text(p.read_text(encoding="utf-8") + "# touched" + chr(10), encoding="utf-8")
    (tmp_path / "HANDOFF.md").write_text(handoff_after, encoding="utf-8")
    if second_commit:
        git("add", "-A")
        assert git("commit", "-q", "-m", "the branch").returncode == 0
    cd = _cd()
    cd.ROOT = str(tmp_path)
    with _not_ci():
        cd.check_debt_on_touched_files()
    return list(cd.ERRORS)


_DEBT_ITEM = ("## From the infra lane, 2026-08-30" + chr(10) * 2
              + "468. **Three modules still carry their own `_load_secrets`** - lane: "
              "`registry`. `pipeline/jdfill.py:1`: " + chr(10) * 2
              + "    ```python" + chr(10) + "    def load_secrets():" + chr(10)
              + "        from pipeline import secretsenv" + chr(10) + "    ```" + chr(10))


def test_a_filed_diff_is_applied_or_declined_by_the_next_lane_to_open_the_file(tmp_path):
    """Item 468 carried the three-line replacement for `pipeline/jdfill.py`'s copy of
    `_load_secrets` by the morning of 2026-08-30; the file took five commits that day and
    kept its copy. Filing does not kill debt. The lane already inside the file can, and
    this is the gate that asks it to - or to say, with the number, why not."""
    handoff = "- **2026-08-30 `jd-text`** - filled 30." + chr(10)
    # the file changed, the item is open, HANDOFF says nothing: refused
    errs = _debt_repo(tmp_path / "a", _DEBT_ITEM, "", handoff, ["pipeline/jdfill.py"])
    assert len(errs) == 1 and "468@registry" in errs[0] and "pipeline/jdfill.py" in errs[0], errs
    # the same, with the number cited in the line this branch ADDS: allowed
    errs = _debt_repo(tmp_path / "b", _DEBT_ITEM, "",
                      handoff.replace("filled 30.", "filled 30; 468 not applied: the loader "
                                      "is not on this branch yet."), ["pipeline/jdfill.py"])
    assert errs == [], errs
    # a citation that was ALREADY in HANDOFF before the branch does not count
    errs = _debt_repo(tmp_path / "c", _DEBT_ITEM, "- old line citing 468" + chr(10),
                      "- old line citing 468" + chr(10) + handoff, ["pipeline/jdfill.py"])
    assert len(errs) == 1, errs
    # a closed item carries no debt
    errs = _debt_repo(tmp_path / "d", _DEBT_ITEM.replace("468. **Three", "468. **CLOSED "
                      "2026-08-30** ~~Three"), "", handoff, ["pipeline/jdfill.py"])
    assert errs == [], errs
    # the file is not the one the diff is for: silent
    errs = _debt_repo(tmp_path / "e", _DEBT_ITEM, "", handoff, ["tests/test_units.py"])
    assert errs == [], errs
    # a working-tree edit that was never committed is not a push: silent, by design
    errs = _debt_repo(tmp_path / "f", _DEBT_ITEM, "", handoff, ["pipeline/jdfill.py"],
                      second_commit=False)
    assert errs == [], errs


def test_a_diff_is_attributed_by_a_line_anchor_and_never_to_a_file_every_lane_appends():
    """Measured before the rule: with a bare path mention counting, the check would have
    refused 26 of the 66 commits of 2026-08-30 - 25 of them on items 311 and 421, which
    name `tests/test_units.py`, the file every lane appends to. With the line anchor and
    the every-lane list it refuses 5, each a real filed diff for a file one lane owns."""
    cd = _cd()
    bl = _bl()
    cd._git = lambda *a: ("pipeline/jdfill.py" + chr(10) + "tests/test_units.py" + chr(10)
                          + "docs/check_docs.py" + chr(10)) if a[0] == "ls-files" else None
    text = (_DEBT_ITEM
            + chr(10) + "469. **A gap described in prose** - lane: `registry`. "
              "`docs/check_docs.py` is honest here:" + chr(10) * 2
            + "    ```" + chr(10) + "    a chain, not a diff" + chr(10) + "    ```" + chr(10)
            + chr(10) + "470. **A test that asserts a wall clock** - lane: `registry`. "
              "`tests/test_units.py:11136`:" + chr(10) * 2
            + "    ```python" + chr(10) + "    assert x" + chr(10) + "    ```" + chr(10))
    owed = {it.num: files for it, files in cd._diff_bearing(bl.parse(text))}
    assert owed == {468: ["pipeline/jdfill.py"]}, owed


def test_next_reads_origin_master_and_the_gate_refuses_a_collision_this_branch_adds():
    """`next` printed `max+1` of the LOCAL file, so two branches cut from the same base got
    the same number and both landed: 445, 446, 461 and 462 each name two items since
    2026-08-30. Reading master's file narrows the window; refusing the collision at the
    gate closes it - and only for a claimant this branch added, so the 38 that already
    exist stay grandfathered and cited by key."""
    bl = _bl()
    item = lambda n, title: "%d. **%s** - lane: `infra`." % (n, title) + chr(10)
    head = "## s" + chr(10) * 2 + item(1, "one") + item(4, "four") + item(4, "other four") + item(5, "mine")
    base = "## s" + chr(10) * 2 + item(1, "one") + item(4, "four") + item(4, "other four")
    master = base + item(5, "theirs") + item(7, "and another")
    items = bl.parse(head)
    # next: master is ahead of this tree, and its number wins
    bl._git_show = lambda ref, rel="docs/BACKLOG.md": master
    assert bl.next_free(items) == 8
    bl._git_show = lambda ref, rel="docs/BACKLOG.md": None
    assert bl.next_free(items) == 6, "no master to read: the local answer, never a crash"
    # the gate: 4 collides at the base too (grandfathered); 5 would collide once rebased
    assert bl.new_collisions(items, base) == {}
    rebased = bl.parse(master + item(5, "mine"))
    got = bl.new_collisions(rebased, base)
    assert list(got) == [5] and {i.title for i in got[5]} == {"**theirs**", "**mine**"}, got
    assert bl.new_collisions(rebased, None) == {}, "no base: nothing to judge, never red"


# --- scraper lane, 2026-08-30: a location is the posting's own or nothing; error != empty ---


def test_scrape_a_wall_serving_a_decoy_page_is_an_error_not_an_empty_board():
    """lakeFS on 2026-08-30: the render was refused http:403, plain HTTP got a 200 marketing
    shell, and `_classify` booked the night "empty" — so `scrape_rot.json` read `why: empty`
    beside `error: http:403`, and `health.overnight_verdict` (which relabels an error night
    `fetch-error`) never fired. An ip-shaped refusal may read as empty only when the plain
    page SHOWS a jobs section, or says outright there are no openings."""
    import scrape_universal as N
    shell = "<html><body><h1>Data, versioned</h1>" + "x" * 3000 + "</body></html>"
    r = _rendered(http_status=403, plain_status=200, plain_html=shell)
    assert N._classify(r, []) == ("error", "http:403")
    honest = "<html><body>We have no open positions at this time.</body></html>" + "y" * 3000
    r2 = _rendered(http_status=403, plain_status=200, plain_html=honest)
    # ...and an ACCEPTED empty drops the refusal code: `why: empty` never sits beside an
    # ip-shaped code in the rot file (the belt in `_apply_result` enforces exactly that,
    # and lakeFS proved the two classifiers would otherwise disagree; the 403 survives in
    # the rot entry's `http` field)
    assert N._classify(r2, []) == ("empty", "")
    # a non-ip refusal (a slow site, honestly empty in plain HTML) keeps the old judgement
    r3 = _rendered(http_status=None, error="goto:TimeoutError", plain_status=200,
                   plain_html=shell)
    assert N._classify(r3, []) == ("empty", "goto:TimeoutError")


def test_refresh_a_rot_entry_never_reads_empty_with_an_ip_shaped_code():
    """The artefact behind BACKLOG 228's lakeFS note: `why: "empty"` beside
    `error: "http:403"` — a wall misfiled as a measurement (lakeFS, Nokia, Schneider
    Electric, 5 nights each). The belt in `_apply_result` — independent of `_classify`,
    which a stale worker tree could bypass — books such a night as an error: rot
    `why: error`, the stamp counts it in `errors`, and, ip-shaped never parking, the row
    is not parked."""
    import refresh_scrape_cache as R
    st, rot = R.RunState(), {}
    res = {"name": "lakeFS", "jobs": [], "status": "empty", "error": "http:403",
           "http_status": 403, "strategy": "", "seconds": 1.0}
    R._apply_result({"company_name": "lakeFS"}, res, {}, rot, "2026-08-30", st)
    assert rot["lakeFS"]["why"] == "error" and rot["lakeFS"]["shape"] == "ip"
    assert st.counts["errors"] == 1 and st.counts["empty"] == 0 and not st.parked
    # a goto-timeout empty (Aquarius Engines) is NOT ip-shaped and stays a measurement
    st2, rot2 = R.RunState(), {}
    R._apply_result({"company_name": "Aquarius Engines"},
                    {**res, "name": "Aquarius Engines", "error": "goto:TimeoutError",
                     "http_status": None}, {}, rot2, "2026-08-30", st2)
    assert rot2["Aquarius Engines"]["why"] == "empty" and st2.counts["empty"] == 1


def test_page_is_il_ignores_the_url(monkeypatch):
    """The listing URL is our own search input — query (`?location=Israel`, Comcast: 14 US
    postings stamped and two published) or path (`/search-jobs/Israel`, Arm: 17 more) — and
    is never evidence about a card. Only `SCRAPE_ASSUME_IL` with an Israel token on the
    PAGE answers yes, and the hunt's own "0" disarms it."""
    import scrape_universal as N
    monkeypatch.delenv("SCRAPE_ASSUME_IL", raising=False)
    assert N._page_is_il("https://jobs.comcast.com/search-jobs?location=Israel", "") is False
    assert N._page_is_il("https://jobs.citi.com/search-jobs/Israel", "") is False
    assert N._page_is_il("https://careers.arm.com/location/israel-jobs/33099/", "x") is False
    monkeypatch.setenv("SCRAPE_ASSUME_IL", "1")
    assert N._page_is_il("https://co.example/careers", "<p>Herzliya</p>") is True
    monkeypatch.setenv("SCRAPE_ASSUME_IL", "0")
    assert N._page_is_il("https://co.example/careers", "<p>Herzliya</p>") is False
    assert N._url_scoped_il("https://jobs.comcast.com/search-jobs?location=Israel") is True
    assert N._url_scoped_il("https://co.example/careers") is False


def test_scrape_adder_url_fallback_strips_the_query():
    """A card with no link of its own inherits the LISTING as its address — and until
    2026-08-30 that included `?location=Israel`, which `israel.is_israel_job` scans as the
    posting's own url: the search term passed the gate on the posting's behalf. The
    fallback is now the bare listing."""
    import scrape_universal as N
