def test_scrape_board_group_verdict_still_stamps_israel_with_provenance():
    """The Pecan/VAST group inference is EVIDENCE (opened position pages), not the query:
    it survives the query-stamp removal, and its verdict is marked `_loc_src="group"` so a
    bare "Israel" in the cache always says where it came from. Kills any over-fix that
    guts `flush` along with the fabrication."""
    import scrape_universal as N
    pecan = ("<html><h1>%s</h1><p>Pecan was acknowledged as one of Israel's fastest "
             "growing startups.</p></html>")
    titles = ["Solution Engineer", "Product Manager", "Data Analyst",
              "Account Executive", "Backend Developer", "QA Engineer"]
    add, jobs = N._make_adder("Pecan", "https://co.example/careers")
    board = N._Board(add)
    for i, t in enumerate(titles):
        assert not board.read(pecan % t, f"https://co.example/careers/{i}/")
    assert board.flush()
    assert len(jobs) == 6 and {j["location"] for j in jobs} == {"Israel"}
    assert {j["_loc_src"] for j in jobs} == {"group"}
    # ...and a board that named a foreign place still refuses its held pages (VAST shape)
    utila = ("<html><h1>Sales Engineer, APAC</h1><p>Singapore (Remote). We are one of "
             "Israel's leading teams.</p></html>")
    add2, jobs2 = N._make_adder("Vast", "https://co.example/careers")
    gb = N._Board(add2)
    assert not gb.read(utila, "https://co.example/careers/apac/")
    assert not gb.flush() and jobs2 == []


def test_collect_stamp_counts_loc_unknown_and_alarms_on_fabricated(tmp_path, monkeypatch):
    """The durability half of 496: `loc_unknown` (cards nothing placed — the level that
    shows a board hiding its locations), `legacy_loc` (pre-fix stamps still republished by
    carries — must ratchet to 0), and `fabricated-loc-N` (an unprovenanced bare "Israel"
    in TONIGHT's fresh reads — a bug by construction, so any N alarms)."""
    import refresh_scrape_cache as R
    st = R.RunState()
    res = {"name": "Co", "jobs": [], "status": "empty", "error": "", "http_status": 200,
           "strategy": "", "loc_unknown": 3, "seconds": 0.1}
    R._apply_result({"company_name": "Co"}, res, {}, {}, _TODAY, st)
    assert st.counts["loc_unknown"] == 3
    bare = dict(_il_job("Co"), location="Israel")
    assert R._unprovenanced([bare]) == 1
    assert R._unprovenanced([dict(bare, _loc_src="group")]) == 0
    assert R._unprovenanced([_il_job("Co")]) == 0, 'a real place needs no provenance mark'
    assert "fabricated-loc-2" in R._alarm(st, fabricated=2)
    assert "fabricated-loc" not in R._alarm(st)
    # end to end: a carried error night republishes an old bare-"Israel" -> legacy_loc=1,
    # loc_unknown rides the stamp, and nothing alarms (carried is the level, not the bug)
    p = _refresh_sandbox(tmp_path, monkeypatch, [["Old Co"]],
                         old_cache={"Old Co": [dict(bare, company="Old Co")]},
                         outcomes={"Old Co": ("error", "goto:TimeoutError")})
    assert p.R.run(["--workers", "1"]) == 0
    stamp = _json.loads(p.stages.read_text(encoding="utf-8"))["collect"]
    assert stamp["legacy_loc"] == 1 and stamp["loc_unknown"] == 0
    assert "fabricated-loc" not in str(stamp.get("alarm", ""))


def test_scrape_a_comeet_slug_settles_the_title_tail():
    """BACKLOG 235: the comeet widget runs place/level/type chips into the visible title
    while the posting url's slug names the clean title — measured 2026-08-31, 118 of 295
    sluggable cached cards carried such a tail and `_split_title_tail` (which needs a
    trailing TYPE word) cleaned 0, so `store.merge_key` forked one posting into two role
    records (Modellama's was emailed twice). The cut only shortens to the boundary the
    board's own url names; the residue is the card's own place claim."""
    import scrape_universal as N
    from pipeline.israel import is_israel_job
    U = "https://www.comeet.com/jobs/dealhub/A1.234/%s/B2.345"
    add, jobs = N._make_adder("DealHub.ai", "https://www.dealhub.ai/careers/")
    assert add("Solution Expert Holon, Senior", "", U % "solution-expert")
    assert (jobs[0]["title"], jobs[0]["location"]) == ("Solution Expert", "Holon")
    assert jobs[0]["_loc_src"] == "own", "the card's own url spoke"
    # the same posting's US twin: cut, kept WITH its foreign place, hard country negative
    assert add("Solution Expert Austin, Texas", "",
               "https://www.comeet.com/jobs/dealhub/A1.234/solution-expert/C3.456")
    assert (jobs[1]["title"], jobs[1]["location"]) == ("Solution Expert", "Austin, Texas")
    assert jobs[1]["country_code"] == "XX" and not is_israel_job(jobs[1])
    # a ", ST" tail is a state code without a city list (Seattle is in no vocabulary),
    # and it writes the hard country negative too (wave-1 attacker C, F6: without XX the
    # path echo of an /israel-jobs/ listing still passed the gate on the url text)
    assert add("Enterprise Account Manager Seattle, WA", "", U % "enterprise-account-manager")
    assert jobs[2]["location"] == "Seattle, WA" and jobs[2]["country_code"] == "XX"
    assert not is_israel_job(jobs[2])
    # the boundary may land inside a parenthesis the slug swallowed
    assert add("QA Engineer(Entry Level) Holon, Entry-level", "", U % "qa-engineerentry-level")
    assert (jobs[3]["title"], jobs[3]["location"]) == ("QA Engineer(Entry Level)", "Holon")
    # a chips-only residue cuts the title and claims nothing (the dedupe is the point)
    assert add("Data Analyst Senior", "Tel Aviv", U % "data-analyst")
    assert (jobs[4]["title"], jobs[4]["location"]) == ("Data Analyst", "Tel Aviv")
    # NEVER a rename: a title that does not extend the slug is a mis-addressed card
    # (Legit Security carried nine neighbours' urls), and a url must not rename a role
    assert add("Bookkeeper", "Tel Aviv", U % "application-security-sales-engineer")
    assert jobs[5]["title"] == "Bookkeeper"
    # ...and a ROLE-worded or numbered residue refuses the cut outright: a bare prefix
    # test RENAMED "Data Analyst Team Lead" to "Data Analyst" and merged "Data Analyst 2"
    # into its sibling (wave-1 attacker C, F2 — the fork bug inverted into a merge)
    assert add("Data Analyst Team Lead", "Tel Aviv",
               "https://www.comeet.com/jobs/dealhub/A1.234/data-analyst/D4.567")
    assert jobs[6]["title"] == "Data Analyst Team Lead"
    assert add("Data Analyst 2", "Haifa",
               "https://www.comeet.com/jobs/dealhub/A1.234/data-analyst/E5.678")
    assert jobs[7]["title"] == "Data Analyst 2"
    # 497: an entity never reaches a public title or a role id again
    assert add("Manager 2, Business Operations &amp; Analytics", "Tel Aviv", "")
    assert jobs[8]["title"] == "Manager 2, Business Operations & Analytics"


def test_scrape_a_card_takes_the_anchor_that_names_it_never_a_neighbours():
    """BACKLOG 434's worse sibling: byte-nearest href on an interleaved layout is the
    NEIGHBOUR's link — Legit Security shipped nine cards under another role's comeet url
    (AppSec Analyst Team Lead -> …/account-executive/…), so `jdfill` described the wrong
    job and a reader landed on another role. An address is taken from something that NAMES
    the role; a nearest href whose slug names a DIFFERENT role is refused — a wrong address
    is worse than none."""
    import scrape_universal as N
    cards = "".join(
        f'<a href="https://www.comeet.com/jobs/co/A.1/{prev}/B.{i}">Apply</a>'
        f'<p class="job-post-title">{t}</p><span>Tel Aviv</span>'
        for i, (t, prev) in enumerate([
            ("AppSec Analyst Team Lead", "account-executive"),
            ("Application Security Analyst", "appsec-analyst-team-lead"),
            ("Data Analyst", "application-security-analyst")]))
    add, jobs = N._make_adder("Legit", "https://co.example/careers")
    N._from_cards("<html>" + cards + "</html>", False, add)
    assert len(jobs) == 3
    for j in jobs:
        assert N._card_slug_names(j["title"], j["url"]) != -1, \
            (j["title"], j["url"], "a neighbour's address on a card")


