def test_the_donor_rung_is_reachable_by_every_monkeypatch_the_suite_already_uses(monkeypatch,
                                                                                 tmp_path):
    """`enrich_matched_jd` must not bind `fetch_jd`/`plain_fetch`/`wayback_snapshot` into its
    own namespace: 43 tests disarm them on `pipeline.jdfill`, and a local binding escapes
    every one — four tests that believed they had stubbed the fetcher were making real
    requests to LinkedIn, on the public repo's CI runner, on every push (wave C).

    Asserted by DOING it, not by checking an absence: a stub installed the way the rest of
    the suite installs one has to be what the donor pass calls. (The `hasattr` check below
    says the same thing and cannot fail on its own — at the base commit the names were not
    bound because the rung did not exist yet.)"""
    import sqlite3
    from types import SimpleNamespace
    import enrich_matched_jd as E
    from pipeline import jdfill
    called = []
    monkeypatch.setattr(jdfill, "fetch_jd",
                        lambda url, **k: (called.append(url)
                                          or jdfill.JD("", "none", "shell", False)))
    row = ("acme|data analyst", "Acme", "Data Analyst", "https://acme.example/careers", "",
           "discovery-linkedin:linkedin:4409973742", "", 0, "2026-08-31")
    conn = sqlite3.connect(str(tmp_path / "s.db"))
    conn.execute("CREATE TABLE matched (mkey TEXT PRIMARY KEY, description TEXT, jd_why TEXT)")
    conn.execute("INSERT INTO matched VALUES (?,?,?)", (row[0], "", ""))
    conn.commit()
    E._donor_pass(conn, [row], {}, None, set(),
                  SimpleNamespace(dry_run=False, archived_bd=False), log=lambda s: None)
    assert called == ["https://www.linkedin.com/jobs/view/4409973742"], (
        "the donor pass did not call the stub the suite installed on pipeline.jdfill")
    for name in ("fetch_jd", "plain_fetch", "wayback_snapshot"):
        assert not hasattr(E, name), (
            "%s is bound in enrich_matched_jd's namespace; call it as jdfill.%s so the "
            "suite's monkeypatches reach it" % (name, name))


def test_the_listing_page_is_never_offered_as_a_posting_however_it_is_written():
    """The self-link skip shipped with the `(host, path)` fix and WITHOUT a test, which is
    `docs/BACKLOG.md` 480 in miniature — the hole was found, closed, and left unguarded
    (wave C found both mutants silent). A listing page is exactly what `is_job_url` refuses,
    so handing it back as "this role's own address" sends the row to the address it is
    already stuck at. Kills `donor-selflink-string-compare` — catalogued rather than killing
    in range because the fix shipped one commit before this test, and `guard_kill` measures
    "new since the last push".

    (The `www.` variant is suppressed by `_page_links`' same-origin check, not by this rule,
    so it is deliberately not the case under test.)"""
    from pipeline.jdfill import role_addresses_on
    page = "https://acme.co.il/jobs/data-analyst/"
    for variant in (page, page + "?page=2", page + "#top", page.rstrip("/")):
        assert role_addresses_on(_listing_page([variant]), page, "Data Analyst", "") == [], variant
    # the same link seen from a DIFFERENT page is a posting, so the rule suppresses nothing else
    assert role_addresses_on(_listing_page([page]), "https://acme.co.il/jobs/",
                             "Data Analyst", "") == [page]


def test_an_address_that_mixes_raw_hebrew_with_an_existing_escape_is_not_encoded_twice():
    """`%` in `wire_url`'s safe set only ever decides a MIXED address: a fully encoded url is
    all-ASCII and returns before `quote` is reached. There are 0 such urls in the caches
    today, so this is the defensive case pinned deliberately rather than a live one — without
    it, `%D7%90` becomes `%25D7%2590` and the address 404s. Kills `wire-url-double-encodes`
    — catalogued for the same reason as the guard above: the fix is one commit older than
    its test."""
    from pipeline.jdfill import wire_url
    mixed = "https://x.com/jobs/%D7%90-דיגיטל/"
    out = wire_url(mixed)
    assert "%25" not in out, out
    assert out.startswith("https://x.com/jobs/%D7%90-"), out
    assert wire_url(out) == out
# --- roles, 2026-08-31 (b): the alias fold, the twin collapse, the blocker column ---------
# lane: roles — 533's class (one employer, two strings), the seen-id collision class
# (one posting, two merge_keys), and the structural-blocker loop agreed with jd-text.
def _fold_env(active=("NVIDIA", "AppSec", "Acme", "Bounce", "Bounce AI"),
              parked=("Meta Israel",), origins=None):
    """registry facts in the run.py shape: every row's exact name; active names by identity."""
    from pipeline.firmographics import identity_key
    rn = set(active) | set(parked)
    abi = {}
    for n in active:
        abi.setdefault(identity_key(n), set()).add(n)
    return rn, abi, (origins or {})


def _fold(name, url="", **kw):
    from pipeline import roles
    rn, abi, org = _fold_env(**kw)
    return roles._alias_fold_target(name, url, rn, abi, org)


def test_alias_fold_rewrites_a_declared_showcase_name_onto_the_registry_row():
    """`NVIDIA AI` is a LinkedIn showcase page, not an employer: run 33387229779 judged one
    posting twice and emailed it twice under two names (533). The fold consumes the curated
    `ALIASES` declaration and the original string rides `_claimed_by` for the audit."""
    from pipeline import roles
    assert _fold("NVIDIA AI") == ("NVIDIA", "declared")
    rn, abi, org = _fold_env()
    jobs = [{"company": "NVIDIA AI", "title": "Senior BI Analyst",
             "url": "https://il.linkedin.com/jobs/view/x-4458885094"}]
    out, folds = roles.fold_company_aliases(jobs, registry_names=rn,
                                            active_by_identity=abi, origins=org)
    assert out[0]["company"] == "NVIDIA" and out[0]["_claimed_by"] == ["NVIDIA AI"]
    assert folds == {"NVIDIA<-NVIDIA AI": 1}


def test_the_live_registry_does_not_park_a_non_employer_on_a_declared_alias_string():
    """LIVE DATA, and the one thing the fixtures above cannot say: the fold's first refusal
    is `name in registry_names`, an exact-string test over EVERY row whatever its `active`
    (`pipeline/run.py` builds it from `load_companies(active_only=False)`). So a row that is
    not an employer at all, sitting on a string `ALIASES` declares, silently cancels a
    curated declaration — no log line, no counter, nothing in the ledger (BACKLOG 522).

    Measured: `Oak` was a Teamtailor DIVISION FILTER on Opera Group's shared board
    (`&division=Oak`, whose own cards read `Oak Isle of Man` / `Oak Guernsey`, offshore
    fiduciary work, zero Israel). It blocked `ALIASES["oak"] = "oak identity security os"`
    while the Israeli company's `Product Analyst` published twice — once under `Oak` from
    Indeed, once under `Oak - Identity Security OS` from its own Ashby board. The row was
    renamed to its board's real employer on 2026-09-01 and retired `redundant`.

    This asserts the OUTCOME on the shipped registry, so restoring a row named `Oak` reds
    it. It is deliberately not the general form "no row name may be an ALIASES key": seven
    keys legitimately name live rows (`AWS`, `JPMorganChase`, `Habana Labs (Intel)`,
    `VMware (Broadcom)`, ...), which are real separate scanner rows and must never fold."""
    import csv as _c
    import os as _o
    from pipeline import roles
    from pipeline.firmographics import identity_key
    root = _o.path.dirname(_o.path.dirname(_o.path.abspath(__file__)))
    rows = [r for r in list(_c.reader(open(_o.path.join(root, "companies.csv"),
                                           encoding="utf-8")))[1:] if r]
    names = {r[0] for r in rows}
    origins = {r[0]: ((r[2] or "").strip() or r[3] or "") for r in rows}
    abi = {}
    for r in rows:
        if (r[4] or "").strip().lower() == "true":
            abi.setdefault(identity_key(r[0]), set()).add(r[0])
    assert roles._alias_fold_target("Oak", "", names, abi, origins) == \
        ("Oak - Identity Security OS", "declared"), \
        "a registry row is holding the string `Oak` again and the declared fold is dead"


def test_alias_fold_never_rewrites_a_registry_name():
    """A registry name — active or parked — is never rewritten: Bounce and Bounce AI are
    both rows (and different identities besides); a parked `Meta Israel` keeps its
    historical string; and an identity two active rows answer to folds onto neither."""
    from pipeline.firmographics import identity_key
    assert _fold("Bounce") is None and _fold("Bounce AI") is None
    assert _fold("Meta Israel") is None, "parked rows are still registry rows"
    # ambiguity: two active rows on one identity (the Amazon/AWS class)
    rn, abi, org = _fold_env(active=("Acme", "Acme Israel"))
    from pipeline import roles
    assert identity_key("Acme") == identity_key("Acme Israel")
    assert roles._alias_fold_target("Acme Ltd", "", rn, abi, org) is None
    # ...and a case-twin ambiguity refuses WHICHEVER member an arbitrary pick would take:
    # a mutant that folds onto "any one of them" folds here on every iteration order
    rn2, abi2, org2 = _fold_env(active=("Acme", "acme"))
    assert roles._alias_fold_target("ACME", "", rn2, abi2, org2) is None


def test_alias_fold_refuses_bare_suffix_strip_equality():
    """`identity_key("AppSec Labs") == identity_key("AppSec")` because `labs` is a stripped
    suffix — and those were two different employers (BACKLOG 144). Equality that arrives
    only via the strip, with no declaration and no board evidence, must stay two names."""
    from pipeline.firmographics import identity_key
    assert identity_key("AppSec Labs") == identity_key("AppSec")
    assert _fold("AppSec Labs", "https://il.linkedin.com/jobs/view/1") is None


def test_alias_fold_declaration_is_the_alias_key_not_the_stripped_stem():
    """The `in ALIASES.values()` leak, pinned closed: `identity_key("NVIDIA Labs")` is
    `nvidia` (strip), which IS an alias VALUE — but `nvidia labs` is not an alias KEY, so
    there is no declaration and no fold. And every alias key must stay a fixed point of
    `_plain_norm`, or the declaration test silently stops matching that key (drift wire)."""
    from pipeline import roles
    from pipeline.firmographics import ALIASES, identity_key
    assert identity_key("NVIDIA Labs") == "nvidia" and "nvidia" in set(ALIASES.values())
    assert _fold("NVIDIA Labs") is None
    assert all(roles._plain_norm(a) == a for a in ALIASES), \
        "an ALIASES key is not normal-form; roles._plain_norm can no longer match it"


def test_alias_fold_has_no_board_gate_because_same_origin_never_checks_the_host():
    """The deleted third gate, pinned deleted (wave A, finding 3): `_same_origin`'s
    tenant branch asks only whether the token names a path segment, so Bounce AI's
    COMEET posting proved Bounce's ASHBY board, and every suffix-strip variant —
    `Bounce Labs`, `Bounce Ltd`, `Bounce Israel` — folded onto the OTHER employer,
    board-authoritative and free to donate its url and text. The gate bought 0 live
    folds against 7 foreign-row passes; it is gone, and this asserts it stays gone."""
    import csv
    from pipeline import roles
    from pipeline.firmographics import identity_key
    regs = list(csv.DictReader(open("companies.csv", encoding="utf-8")))
    rn = {r["company_name"] for r in regs}
    abi, org = {}, {}
    for r in regs:
        org[r["company_name"]] = (r.get("token") or "").strip() or r.get("api_url") or ""
        if (r.get("active") or "").strip().lower() == "true":
            abi.setdefault(identity_key(r["company_name"]), set()).add(r["company_name"])
    burl = "https://www.comeet.com/jobs/bounce/E9.00C/data-analyst/3E.E6D"
    for n in ("Bounce Labs", "Bounce Ltd", "Bounce Israel", "Bounce Technologies"):
        assert roles._alias_fold_target(n, burl, rn, abi, org) is None, n
    # a synthetic same-board form refuses too: on-board evidence is not identity evidence
    org2 = {"Acme": "acmetoken"}
    url = "https://www.comeet.com/jobs/acmetoken/12.005/data-analyst/9.AAA"
    assert _fold("Acme Technologies", url, origins=org2) is None
    # and an EMPTY identity is never a bucket (identity_key deletes Cyrillic/fullwidth)
    rn3, abi3, org3 = _fold_env()
    abi3[""] = {"Acme"}
    assert roles._alias_fold_target("Данные", "", rn3, abi3, org3) is None


def test_alias_sweep_supersedes_the_stored_twin_and_unions_its_ids(tmp_path):
    """The committed store's live case: `nvidia ai|senior business intelligence analyst`
    beside `nvidia|…` — one employer, one title, two records, both emailed 2026-08-31.
    The sweep supersedes the alias record into the canonical one, unions seen_ids and the
    sent mirror, and `filter_new` still sees the delivery — nothing is ever re-emailed."""
    from pipeline import roles, store
    st = store.SeenStore(str(tmp_path / "t.db"))
    nv = _role("NVIDIA", "Senior Business Intelligence Analyst",
               "https://il.indeed.com/viewjob?jk=745", "indeed:745", src="discovery-indeed")
    ai = _role("NVIDIA AI", "Senior Business Intelligence Analyst",
               "https://il.linkedin.com/jobs/view/x-4458885094", "linkedin:4458885094",
               src="discovery-linkedin")
    for j in (nv, ai):
        j["seen_ids"] = [store.seen_id(j)]
        st.upsert_matched(j, "2026-08-30")
    st.mark_sent(ai, "2026-08-30")            # the alias twin was the one delivered
    L = roles.Ledger(st)
    L.open_sync()
    # the delivery lives in the `sent` TABLE; the record's mirror is record_run's job —
    # stamp it by hand so the fold's mirror-union is exercised too
    L.records["nvidia ai|senior business intelligence analyst"]["sent"] = {
        "discovery-linkedin:linkedin:4458885094": "2026-08-30"}
    rn, abi, org = _fold_env()
    lines = L.fold_aliases(lambda n, u: roles._alias_fold_target(n, u, rn, abi, org))
    assert any("alias folds" in x and "NVIDIA<-NVIDIA AI" in x for x in lines), lines
    win = L.records["nvidia|senior business intelligence analyst"]
    lose = L.records["nvidia ai|senior business intelligence analyst"]
    assert lose["status"] == "superseded" and lose["superseded_by"] == win["role_id"]
    assert "discovery-linkedin:linkedin:4458885094" in win["seen_ids"]
    assert "NVIDIA AI" in (win.get("attribution") or {}).get("claimed_by", [])
    assert "discovery-linkedin:linkedin:4458885094" in (win.get("sent") or {})
    row = next(r for r in st.get_matched_since("0000-01-01") if r["company"] == "NVIDIA")
    assert st.filter_new([row]) == [], "the delivered twin's id suppresses the winner too"
    assert not L.frozen
    st.close()


